insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-252', 'Neha: the sleeping pill that became three (sedative-hypnotic use disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-252-1","text":"Takes three zolpidem tablets a night, sometimes in the day, for six months","bucket":"presenting"},{"id":"form-252-2","text":"Rebound insomnia when she misses a dose","bucket":"perpetuating"},{"id":"form-252-3","text":"Episodes of sleep-eating and messages she does not remember sending","bucket":"presenting"},{"id":"form-252-4","text":"A doctor prescribed zolpidem during a stressful project","bucket":"precipitating"},{"id":"form-252-5","text":"Frightened after waking to messages she did not remember","bucket":"protective"},{"id":"form-252-6","text":"Flatmate who supports her","bucket":"protective"},{"id":"form-252-7","text":"She lives in Hyderabad","bucket":"distractor"},{"id":"form-252-8","text":"Believes she cannot sleep without it","bucket":"perpetuating"},{"id":"form-252-9","text":"Buys extra strips from chemists without a prescription","bucket":"perpetuating"},{"id":"form-252-10","text":"Works rotating shifts","bucket":"predisposing"},{"id":"form-252-11","text":"Anxious since college with poor sleep","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Neha, 29, presents with a sedative-hypnotic use disorder from zolpidem: rising doses, daytime use, and complex sleep behaviours such as sleep-eating and sending messages with no memory. These behaviours are a known and dangerous effect of the medicine. Long-standing anxiety, poor sleep and shift work (predisposing) raised her risk; a prescription during a stressful project (precipitating) started it. Buying extra strips, rebound insomnia when she misses doses and the belief that she cannot sleep without it (perpetuating) keep it going. Her fright and her flatmate''s support (protective) open the door to a slow taper, CBT for insomnia and treatment of anxiety. Hyderabad is a distractor.","hint":"A 29-year-old software tester who takes three times her prescribed zolpidem","tags":{"topic":"substance","difficulty":2,"objective":"Recognise sedative-hypnotic use disorder from a prescribed sleeping tablet","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"substance","diagnosis":"Sedative, hypnotic or anxiolytic use disorder (zolpidem), moderate"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-253', 'Joseph: the slaps after the drinks (alcohol use disorder with violence at home)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-253-1","text":"Drinking friends who joke about ''keeping wives in line''","bucket":"perpetuating"},{"id":"form-253-2","text":"Believes a husband should ''control'' the home","bucket":"predisposing"},{"id":"form-253-3","text":"Has a steady job at a garage","bucket":"protective"},{"id":"form-253-4","text":"Blames alcohol for the violence rather than taking responsibility","bucket":"perpetuating"},{"id":"form-253-5","text":"Drinks heavily most evenings and has hit his wife several times when drunk","bucket":"presenting"},{"id":"form-253-6","text":"Debt from drinking causes arguments","bucket":"perpetuating"},{"id":"form-253-7","text":"Says he loves his two daughters and does not want them to fear him","bucket":"protective"},{"id":"form-253-8","text":"His wife took a job, which he saw as a challenge to his authority","bucket":"precipitating"},{"id":"form-253-9","text":"He fixes two-wheelers in Mangaluru","bucket":"distractor"},{"id":"form-253-10","text":"Grew up watching his father beat his mother when drunk","bucket":"predisposing"},{"id":"form-253-11","text":"Referred by the court after she filed a complaint","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Joseph, 40, presents with a moderate alcohol use disorder with intimate partner violence. Alcohol raises the risk of violence but does not cause it on its own; beliefs about control and responsibility matter. Seeing his father''s violence and rigid beliefs about a husband''s control (predisposing) shaped his behaviour; his wife''s new job (precipitating) threatened those beliefs. Blaming alcohol, peers who endorse control and money stress from drinking (perpetuating) maintain both problems. His love for his daughters and stable work (protective) offer motivation. The plan puts his wife''s and children''s safety first, with alcohol treatment, a programme that addresses violence and responsibility, and links with legal and support services for his wife. The two-wheelers are a distractor.","hint":"A 40-year-old mechanic referred after his wife went to the police","tags":{"topic":"substance","difficulty":3,"objective":"Formulate alcohol use and partner violence, keeping safety central","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"substance","diagnosis":"Alcohol use disorder, moderate, with intimate partner violence"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-254', 'Sahil: the gym injections and the new rage (anabolic steroid use, not bipolar disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-254-1","text":"Mood episodes for years before any steroid use","bucket":"distractor"},{"id":"form-254-2","text":"Uses more steroids to get rid of the low mood after cycles","bucket":"perpetuating"},{"id":"form-254-3","text":"Gym culture that praises size","bucket":"perpetuating"},{"id":"form-254-4","text":"Irritable, aggressive outbursts and little need for sleep during steroid cycles","bucket":"presenting"},{"id":"form-254-5","text":"Believes he looks small despite large muscles","bucket":"perpetuating"},{"id":"form-254-6","text":"Teased about being thin as a teenager","bucket":"predisposing"},{"id":"form-254-7","text":"Strong focus on appearance and body size","bucket":"predisposing"},{"id":"form-254-8","text":"Started injecting anabolic steroids supplied by a gym trainer before a competition","bucket":"precipitating"},{"id":"form-254-9","text":"Elder sister who noticed the change","bucket":"protective"},{"id":"form-254-10","text":"He trains at a gym in Chandigarh","bucket":"distractor"},{"id":"form-254-11","text":"Low mood and tiredness in the weeks after each cycle ends","bucket":"presenting"},{"id":"form-254-12","text":"No mood episodes before steroids","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sahil, 22, presents with anabolic steroid use with substance-induced mood symptoms: irritability, aggression and less sleep on cycles, and low mood after cycles end. The mood changes follow steroid use, and there were no episodes before, so bipolar disorder is less likely; the distractor of years of mood episodes before steroids does not fit. Childhood teasing and a strong focus on size (predisposing), possibly with muscle dysmorphia, raised his vulnerability; a trainer supplying steroids (precipitating) started use. Seeing himself as small, using more to escape the post-cycle low and gym culture (perpetuating) keep it going. No earlier mood disorder and his sister''s support (protective) help. The plan checks physical health, addresses body image and plans safe stopping. The gym''s location is a distractor.","hint":"A 22-year-old bodybuilder whose mood changed after starting injections","tags":{"topic":"substance","difficulty":4,"objective":"Tell steroid-related mood changes apart from a primary mood disorder","exams":["md-psychiatry","mcp-entrance"],"module":"substance","diagnosis":"Anabolic steroid use with substance-induced mood symptoms"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-255', 'Raghu: the first week out of jail (opioid relapse and overdose risk)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-255-1","text":"Released from prison ten days ago and has used heroin twice","bucket":"presenting"},{"id":"form-255-2","text":"Grew up in care homes","bucket":"predisposing"},{"id":"form-255-3","text":"Uses alone at night in a rented room","bucket":"perpetuating"},{"id":"form-255-4","text":"Release with no housing and no link to an opioid substitution clinic","bucket":"precipitating"},{"id":"form-255-5","text":"Was opioid-free in prison for two years and now feels he ''must make up for lost time''","bucket":"presenting"},{"id":"form-255-6","text":"Wants to see his son again","bucket":"protective"},{"id":"form-255-7","text":"Old friends who supply him","bucket":"perpetuating"},{"id":"form-255-8","text":"He learned carpentry in prison","bucket":"distractor"},{"id":"form-255-9","text":"Fifteen years of opioid dependence with two earlier overdoses","bucket":"predisposing"},{"id":"form-255-10","text":"Probation officer who checks on him weekly","bucket":"protective"},{"id":"form-255-11","text":"Also drinks alcohol, which adds to breathing risk","bucket":"perpetuating"},{"id":"form-255-12","text":"Lost tolerance after two years without opioids","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Raghu, 36, presents with early relapse of severe opioid use disorder after release from prison, with very high overdose risk. The weeks after release are one of the most dangerous times because tolerance has fallen. Long dependence, two earlier overdoses and a childhood in care (predisposing) increase his risk; release with no housing or treatment link (precipitating) left him without support. Lost tolerance, using alone, adding alcohol and old supply networks (perpetuating) make overdose likely. His probation officer and his wish to see his son (protective) give contact points. Urgent actions: start buprenorphine or methadone, give naloxone and teach its use, advise never using alone, address alcohol and help with housing. Carpentry is a distractor.","hint":"A 36-year-old released from prison after two years, now using heroin again","tags":{"topic":"substance","difficulty":5,"objective":"Build a risk formulation for overdose after release from prison","exams":["md-psychiatry","mcp-entrance"],"module":"substance","diagnosis":"Opioid use disorder, severe, early relapse with high overdose risk"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-256', 'Mrs Devi: always waiting for the gate to open (carer stress in a wife of a man who drinks)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-256-1","text":"Close to her sister","bucket":"protective"},{"id":"form-256-2","text":"She lives in Gaya","bucket":"distractor"},{"id":"form-256-3","text":"Lies awake until her husband comes home drunk","bucket":"presenting"},{"id":"form-256-4","text":"Takes on all the household money worries alone","bucket":"perpetuating"},{"id":"form-256-5","text":"Headaches, poor sleep, worry and tearfulness for six months","bucket":"presenting"},{"id":"form-256-6","text":"Works as an anganwadi helper and is respected","bucket":"protective"},{"id":"form-256-7","text":"Has stopped visiting her friends out of shame","bucket":"perpetuating"},{"id":"form-256-8","text":"Taught to keep family problems private","bucket":"predisposing"},{"id":"form-256-9","text":"Husband lost his job and began drinking every night","bucket":"precipitating"},{"id":"form-256-10","text":"Covers up for him with relatives and his employer","bucket":"perpetuating"},{"id":"form-256-11","text":"Grew up with a father who drank","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Devi, 38, presents with an adjustment disorder with mixed anxiety and low mood in response to living with her husband''s alcohol dependence. Family members of people with alcohol problems carry heavy stress that often shows as physical complaints such as headaches. Growing up with a father who drank and a belief that problems must stay private (predisposing) shape her coping; her husband''s job loss and nightly drinking (precipitating) set off her symptoms. Covering for him, withdrawing from friends and carrying all money worries alone (perpetuating) keep her stuck. Her sister and her respected work (protective) are resources. Help for her includes support for herself in her own right, a family support group, safety screening and, if he agrees, treatment for her husband. Gaya is a distractor.","hint":"A 38-year-old woman with headaches and sleeplessness whose husband drinks every night","tags":{"topic":"substance","difficulty":2,"objective":"Formulate the distress of a family member living with alcohol dependence","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"substance","diagnosis":"Adjustment disorder with mixed anxiety and depressed mood, in the wife of a man with alcohol dependence"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-257', 'Shirin: the centre of every room (histrionic personality disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-257-1","text":"Since her teens she feels uncomfortable when she is not the centre of attention","bucket":"presenting"},{"id":"form-257-2","text":"Childhood in which attention came only when she performed or was ill","bucket":"predisposing"},{"id":"form-257-3","text":"Wants to understand why friendships end","bucket":"protective"},{"id":"form-257-4","text":"Warm, energetic and good at her job","bucket":"protective"},{"id":"form-257-5","text":"Her closest friend stopped speaking to her after a scene at a wedding","bucket":"precipitating"},{"id":"form-257-6","text":"Sees others'' irritation as proof they are jealous","bucket":"perpetuating"},{"id":"form-257-7","text":"Dramatic, quickly shifting emotions and relationships she believes are closer than they are","bucket":"presenting"},{"id":"form-257-8","text":"Responds to feeling ignored with louder displays, which push people away","bucket":"perpetuating"},{"id":"form-257-9","text":"Praised mainly for her looks","bucket":"predisposing"},{"id":"form-257-10","text":"She lives in Mumbai''s Bandra suburb","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Shirin, 29, shows histrionic personality disorder: a pervasive pattern since adolescence of excessive emotion and attention-seeking, discomfort when not the focus, rapidly shifting shallow emotions and seeing relationships as closer than they are. A childhood where attention came through performance or illness and praise focused on looks (predisposing) shaped the pattern; losing her closest friend after a public scene (precipitating) brought her to help. Escalating displays when she feels ignored, and reading others'' irritation as jealousy (perpetuating), keep the cycle going. Her warmth, work skills and curiosity about her relationships (protective) are a good base for therapy focused on needs, emotions and how others respond. Her suburb is a distractor.","hint":"A 29-year-old event planner whose friendships keep ending","tags":{"topic":"personality","difficulty":1,"objective":"Recognise the long-standing pattern of histrionic personality disorder","exams":["cuet-pg","ma-semester","mcp-entrance","ugc-net"],"module":"personality","diagnosis":"Histrionic personality disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-258', 'Mr Dhar: content with the night shift and no visitors (schizoid personality disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-258-1","text":"Night shifts suit his wish to avoid people","bucket":"perpetuating"},{"id":"form-258-2","text":"Steady job for twenty years","bucket":"protective"},{"id":"form-258-3","text":"Has always preferred to be alone, has no close friends and no wish for any","bucket":"presenting"},{"id":"form-258-4","text":"Quiet, solitary child who played alone","bucket":"predisposing"},{"id":"form-258-5","text":"Shows little emotion and seems indifferent to praise or criticism","bucket":"presenting"},{"id":"form-258-6","text":"Recent loss of interest in his garden and books, with low mood","bucket":"distractor"},{"id":"form-258-7","text":"Parents emotionally distant","bucket":"predisposing"},{"id":"form-258-8","text":"Family pressure to marry increases his withdrawal","bucket":"perpetuating"},{"id":"form-258-9","text":"Reads widely and keeps a garden","bucket":"protective"},{"id":"form-258-10","text":"His sister insisted on the visit after their mother''s death left him living alone","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Dhar, 46, shows schizoid personality disorder: a lifelong pattern of detachment from relationships, preferring solitary activities and a narrow range of emotional expression, without psychotic symptoms. He is not distressed by being alone, which separates this from social anxiety or avoidant personality, where people want contact but fear rejection. A solitary temperament and distant parents (predisposing) shaped the pattern; his mother''s death and his sister''s worry (precipitating) brought him in. Night work and family pressure to marry (perpetuating) reinforce withdrawal. A long, stable job and his reading and garden (protective) show good functioning on his own terms. Recent loss of interest and low mood would suggest depression and is a distractor; it is not part of his picture, though it is worth checking after his mother''s death.","hint":"A 46-year-old night watchman referred by his sister, who worries he is lonely","tags":{"topic":"personality","difficulty":1,"objective":"Recognise schizoid personality disorder and its difference from depression","exams":["cuet-pg","ma-semester","mcp-entrance","ugc-net"],"module":"personality","diagnosis":"Schizoid personality disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-259', 'Aakash: the punched wall after every rejection (borderline personality disorder in a young man)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-259-1","text":"Close bond with his younger sister","bucket":"protective"},{"id":"form-259-2","text":"Others see only his anger and respond with rejection","bucket":"perpetuating"},{"id":"form-259-3","text":"Explosive anger, impulsive spending and drinking, and cutting his arm after breakups","bucket":"presenting"},{"id":"form-259-4","text":"Believes ''everyone leaves in the end''","bucket":"perpetuating"},{"id":"form-259-5","text":"Drinks to calm himself, which makes him more impulsive","bucket":"perpetuating"},{"id":"form-259-6","text":"Intense, unstable relationships with fear of abandonment","bucket":"presenting"},{"id":"form-259-7","text":"Good at his job as a bike mechanic","bucket":"protective"},{"id":"form-259-8","text":"Father left when he was six and his mother was often unpredictable","bucket":"predisposing"},{"id":"form-259-9","text":"He supports a Chennai IPL team","bucket":"distractor"},{"id":"form-259-10","text":"His girlfriend ended the relationship by text","bucket":"precipitating"},{"id":"form-259-11","text":"Bullied at school","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Aakash, 24, presents with borderline personality disorder: unstable relationships, fear of abandonment, intense anger, impulsivity and self-harm. In men the anger and substance use are often what others notice, while the fear of being left is missed. Early loss of his father, an unpredictable home and bullying (predisposing) shaped a core belief that everyone leaves; a breakup by text (precipitating) triggered his crisis. Others reacting to his anger with rejection, drinking to calm down and the belief itself (perpetuating) confirm his fears. His sister and his work (protective) are anchors. Treatment such as DBT or mentalisation-based therapy, safety planning and work on alcohol fits him. The IPL team is a distractor.","hint":"A 24-year-old with anger, impulsive spending and fear of being left","tags":{"topic":"personality","difficulty":2,"objective":"Recognise borderline personality disorder in a man, where anger may hide fear","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"personality","diagnosis":"Borderline personality disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-260', 'Mr Nanda: retirement without a timetable (personality disorder with prominent anankastic traits)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-260-1","text":"Enjoys teaching his grandson mathematics","bucket":"protective"},{"id":"form-260-2","text":"Unwanted intrusive thoughts that he tries to neutralise with rituals","bucket":"distractor"},{"id":"form-260-3","text":"Family resistance is seen as disrespect, so he tightens control","bucket":"perpetuating"},{"id":"form-260-4","text":"Reliable, honest and devoted to his family","bucket":"protective"},{"id":"form-260-5","text":"Retired from a public sector engineering firm six months ago","bucket":"precipitating"},{"id":"form-260-6","text":"No work to absorb his need for order","bucket":"perpetuating"},{"id":"form-260-7","text":"Lifelong rigid perfectionism and control, now insisting the family follows his schedules","bucket":"presenting"},{"id":"form-260-8","text":"Praised throughout his career for precision","bucket":"predisposing"},{"id":"form-260-9","text":"Strict father who punished mistakes","bucket":"predisposing"},{"id":"form-260-10","text":"Anger and low mood when routines are broken","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Nanda, 61, is best described with the dimensional personality model as having a mild personality disorder with prominent anankastic traits: perfectionism, rigid control of himself and others and difficulty adapting. Unlike OCD, his rules feel right to him rather than unwanted, so intrusive thoughts with rituals are a distractor. A strict, punishing father and a career that rewarded precision (predisposing) built the pattern; retirement (precipitating) removed the setting where his traits worked well. Lacking work to channel order, and treating family resistance as disrespect (perpetuating), worsen conflict. His reliability, devotion and joy in teaching his grandson (protective) can be used to build new roles and flexibility through therapy and family sessions.","hint":"A 61-year-old retired engineer who is making his family''s life unbearable","tags":{"topic":"personality","difficulty":3,"objective":"Use the dimensional model of personality to formulate rigid perfectionism","exams":["mcp-entrance","md-psychiatry","ugc-net"],"module":"personality","diagnosis":"Personality disorder, mild, with prominent anankastic traits"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-261', 'Sunaina: the cuts and the friendships that flare and burn (emerging borderline traits in a teenager)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-261-1","text":"Close to her school counsellor","bucket":"protective"},{"id":"form-261-2","text":"Parents argue about who is to blame for her cutting","bucket":"perpetuating"},{"id":"form-261-3","text":"Sensitive, intense child","bucket":"predisposing"},{"id":"form-261-4","text":"Excluded from her friend group''s chat after an argument","bucket":"precipitating"},{"id":"form-261-5","text":"Talented dancer","bucket":"protective"},{"id":"form-261-6","text":"Social media keeps her watching the group she was removed from","bucket":"perpetuating"},{"id":"form-261-7","text":"Parents divorced bitterly when she was ten","bucket":"predisposing"},{"id":"form-261-8","text":"Feels empty and unsure who she is","bucket":"presenting"},{"id":"form-261-9","text":"Self-cutting when upset, stormy friendships and sudden mood shifts for over a year","bucket":"presenting"},{"id":"form-261-10","text":"Hides cuts, which delays help","bucket":"perpetuating"},{"id":"form-261-11","text":"She studies in class eleven in Dehradun","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sunaina, 16, shows emerging borderline personality traits with non-suicidal self-injury: unstable relationships, mood shifts, emptiness and identity confusion over more than a year. Personality difficulties can be recognised in adolescents when the pattern is persistent, and early help works well, but labels should be used with care. A bitter parental divorce and an intense temperament (predisposing) shaped her emotional sensitivity; exclusion from her friends'' chat (precipitating) set off a crisis. Watching the group online, parents blaming each other and hiding her cuts (perpetuating) maintain distress. Her counsellor and dancing (protective) are strengths. The plan includes adolescent DBT skills, family work to reduce blame, wound care and suicide risk assessment. Her class and city are distractors.","hint":"A 16-year-old with self-harm and stormy friendships for over a year","tags":{"topic":"personality","difficulty":3,"objective":"Formulate emerging personality difficulties in an adolescent without labelling too early","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"personality","diagnosis":"Emerging borderline personality traits in an adolescent, with non-suicidal self-injury"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-262', 'Arjun: moods that turn in an hour after an argument (borderline personality disorder, not bipolar II)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-262-1","text":"Chronic emptiness, impulsivity and repeated self-harm since his teens","bucket":"presenting"},{"id":"form-262-2","text":"Fight with his partner about moving cities","bucket":"precipitating"},{"id":"form-262-3","text":"Intense, reactive temperament","bucket":"predisposing"},{"id":"form-262-4","text":"Motivated after reading about therapy for emotion regulation","bucket":"protective"},{"id":"form-262-5","text":"Several mood stabilisers with little effect, adding side effects","bucket":"perpetuating"},{"id":"form-262-6","text":"Splits people into all good or all bad","bucket":"perpetuating"},{"id":"form-262-7","text":"Stable job in a bank","bucket":"protective"},{"id":"form-262-8","text":"Episodes of four or more days of raised mood and energy with little need for sleep, without any trigger","bucket":"distractor"},{"id":"form-262-9","text":"Believes he has ''bipolar'' and waits for medicine to fix his relationships","bucket":"perpetuating"},{"id":"form-262-10","text":"Emotional neglect in childhood and an alcoholic father","bucket":"predisposing"},{"id":"form-262-11","text":"Mood shifts lasting hours, triggered by arguments or feeling rejected","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Arjun, 27, presents with borderline personality disorder rather than bipolar II disorder. His mood shifts last hours, are set off by interpersonal events and sit within long-standing emptiness, impulsivity and self-harm. Bipolar II needs distinct hypomanic episodes of at least four days with raised energy and less need for sleep, often without a trigger; that is the distractor and does not fit him. Childhood neglect, a father who drank and an intense temperament (predisposing) shaped his difficulties; a fight with his partner (precipitating) triggered the latest crisis. The bipolar label leading him to wait for medicine, unhelpful mood stabilisers and splitting (perpetuating) keep him stuck. His motivation and stable job (protective) support a move to structured psychotherapy and careful review of medicines.","hint":"A 27-year-old referred with ''mood swings'' and an earlier label of bipolar disorder","tags":{"topic":"personality","difficulty":4,"objective":"Tell borderline mood instability apart from bipolar II disorder","exams":["md-psychiatry","mcp-entrance"],"module":"personality","diagnosis":"Borderline personality disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-263', 'Mr Banerjee: a new man at fifty-five (personality change due to a frontal tumour)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-263-1","text":"No history of behaviour problems before this year","bucket":"predisposing"},{"id":"form-263-2","text":"Polite, careful man all his life","bucket":"predisposing"},{"id":"form-263-3","text":"Headaches in the morning and loss of sense of smell","bucket":"presenting"},{"id":"form-263-4","text":"Family thought it was a ''midlife crisis'' and delayed seeking help","bucket":"perpetuating"},{"id":"form-263-5","text":"Lack of insight means he refuses tests","bucket":"perpetuating"},{"id":"form-263-6","text":"Over a year has become rude, makes sexual jokes, spends recklessly and is unconcerned about it","bucket":"presenting"},{"id":"form-263-7","text":"Wife who kept a diary of the changes","bucket":"protective"},{"id":"form-263-8","text":"A pattern of impulsive, reckless behaviour since adolescence","bucket":"distractor"},{"id":"form-263-9","text":"A brain scan, ordered after a fall, shows a large mass at the front of the brain","bucket":"precipitating"},{"id":"form-263-10","text":"Surgery is possible","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Banerjee, 55, presents with a personality change due to a frontal meningioma: disinhibition, poor judgement, reckless spending and lack of concern starting in mid-life, with morning headaches and loss of smell. A new personality change after early adulthood points to a brain cause, not a personality disorder, which by definition begins by adolescence or early adulthood; the distractor of reckless behaviour since adolescence does not fit. His lifelong careful nature (predisposing context) makes the change stark; the scan (precipitating discovery) shows the cause. The family''s ''midlife crisis'' explanation and his lack of insight (perpetuating) delayed care. His wife''s diary and the chance of surgery (protective) are reasons for hope. Plan: neurosurgery referral, capacity assessment and protecting finances.","hint":"A 55-year-old accountant who has become crude, careless and unconcerned","tags":{"topic":"neurocognitive","difficulty":4,"objective":"Recognise a late-onset personality change as a sign of brain disease","exams":["md-psychiatry","mcp-entrance"],"module":"brain","diagnosis":"Personality change due to a frontal meningioma"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-264', 'Meera: the ninth admission this year (borderline personality disorder with repeated crises)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-264-1","text":"Staff frustration shows, which she reads as rejection","bucket":"perpetuating"},{"id":"form-264-2","text":"Each admission gives brief relief but no therapy, then sudden discharge","bucket":"perpetuating"},{"id":"form-264-3","text":"Mother with severe depression","bucket":"predisposing"},{"id":"form-264-4","text":"Did well in a skills group three years ago","bucket":"protective"},{"id":"form-264-5","text":"Drinks heavily during crises; feels empty and hates herself between them","bucket":"presenting"},{"id":"form-264-6","text":"Different doctors each time and changing medicines","bucket":"perpetuating"},{"id":"form-264-7","text":"Alcohol makes overdoses more dangerous","bucket":"perpetuating"},{"id":"form-264-8","text":"Wants to train as a beautician","bucket":"protective"},{"id":"form-264-9","text":"A friend who has stayed with her for ten years","bucket":"protective"},{"id":"form-264-10","text":"Sexual abuse by a relative from age eight","bucket":"predisposing"},{"id":"form-264-11","text":"Nine short admissions this year after overdoses or self-harm, usually after relationship crises","bucket":"presenting"},{"id":"form-264-12","text":"She lives in a rented room in Navi Mumbai","bucket":"distractor"},{"id":"form-264-13","text":"Her keyworker left the service three months ago","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Meera, 31, presents with borderline personality disorder with alcohol use disorder and frequent self-poisoning. Childhood sexual abuse and a depressed mother (predisposing) shaped her deep self-hatred and fear of abandonment; her keyworker leaving (precipitating) removed her main secure relationship. The care system now helps keep the crises going (perpetuating): short admissions bring relief without therapy, many doctors change her medicines, and staff frustration feels like rejection, while alcohol makes each overdose riskier. Her long friendship, earlier success in a skills group and her goal of training as a beautician (protective) are real strengths. The plan is one consistent team, a shared crisis plan, a return to structured therapy, alcohol treatment, careful prescribing of small amounts and planned brief admissions only when needed. Her address is a distractor.","hint":"A 31-year-old with frequent overdoses, alcohol use and many short admissions","tags":{"topic":"personality","difficulty":5,"objective":"Formulate a complex case where the care system itself keeps the crises going","exams":["md-psychiatry","mcp-entrance"],"module":"personality","diagnosis":"Borderline personality disorder with alcohol use disorder and recurrent self-poisoning"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-265', 'Vijay: every choice used to be his mother''s (dependent personality disorder in a man)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-265-1","text":"Lifelong need for others to make decisions and fear of being alone","bucket":"presenting"},{"id":"form-265-2","text":"Overprotective mother who did everything for him","bucket":"predisposing"},{"id":"form-265-3","text":"Anxious child who was often ill","bucket":"predisposing"},{"id":"form-265-4","text":"Avoids taking on any new task alone","bucket":"perpetuating"},{"id":"form-265-5","text":"His mother''s death four months ago","bucket":"precipitating"},{"id":"form-265-6","text":"Agrees with everyone to avoid disapproval","bucket":"perpetuating"},{"id":"form-265-7","text":"Steady clerical job in a government office","bucket":"protective"},{"id":"form-265-8","text":"Kind colleagues","bucket":"protective"},{"id":"form-265-9","text":"Since his mother died, cannot decide what to eat or wear and phones his aunt dozens of times a day","bucket":"presenting"},{"id":"form-265-10","text":"Aunt makes all decisions to calm him","bucket":"perpetuating"},{"id":"form-265-11","text":"He likes old Hindi film songs","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Vijay, 34, shows dependent personality disorder: a long-standing need to be taken care of, difficulty making everyday decisions without advice, fear of being alone and going along with others to avoid disapproval. An overprotective mother and an anxious, sickly childhood (predisposing) shaped this pattern; her death (precipitating) removed his main caretaker and exposed his difficulties, alongside his grief. His aunt taking over decisions, agreeing with everyone and avoiding new tasks (perpetuating) reinforce dependence. His steady job and kind colleagues (protective) are supports. Therapy can build decision-making and confidence step by step while supporting his grief and screening for depression. The film songs are a distractor.","hint":"A 34-year-old who cannot choose his own shirt since his mother died","tags":{"topic":"personality","difficulty":2,"objective":"Recognise dependent personality disorder and the crisis of losing a caretaker","exams":["mcp-entrance","ma-semester","ugc-net"],"module":"personality","diagnosis":"Dependent personality disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-266', 'Pallavi: the faints that come when she feels unseen (dissociative seizures with histrionic traits)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-266-1","text":"Normal brain wave test during an episode; no injuries or tongue biting","bucket":"presenting"},{"id":"form-266-2","text":"Felt ignored as a child among five siblings except when unwell","bucket":"predisposing"},{"id":"form-266-3","text":"Dramatic, emotional style since her teens","bucket":"predisposing"},{"id":"form-266-4","text":"Accepts the explanation when given respectfully","bucket":"protective"},{"id":"form-266-5","text":"Close to her younger brother","bucket":"protective"},{"id":"form-266-6","text":"Tongue biting, incontinence and abnormal brain wave activity during the episodes","bucket":"distractor"},{"id":"form-266-7","text":"Episodes bring the family together around her, which eases her distress for a while","bucket":"perpetuating"},{"id":"form-266-8","text":"Her husband''s family began planning her younger sister-in-law''s wedding and she felt pushed aside","bucket":"precipitating"},{"id":"form-266-9","text":"Repeated emergency visits and tests keep the focus on the body","bucket":"perpetuating"},{"id":"form-266-10","text":"Collapses with shaking and closed eyes during family arguments, lasting twenty minutes","bucket":"presenting"},{"id":"form-266-11","text":"Hard for her to put feelings into words","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Pallavi, 27, presents with dissociative (functional) seizures alongside histrionic personality traits. The long episodes with closed eyes during conflict and a normal brain wave recording during an attack support functional seizures; tongue biting and abnormal brain waves, the distractor, would point to epilepsy. The episodes are not deliberate. Feeling noticed only when ill and a dramatic emotional style (predisposing) shape how distress is expressed; feeling pushed aside during wedding planning (precipitating) triggered episodes. Family attention that briefly soothes her, repeated tests and difficulty naming feelings (perpetuating) keep them going. Her openness to explanation and her brother''s support (protective) suit a plan with a clear, kind explanation, family guidance to stay calm during episodes and therapy for emotions and needs.","hint":"A 27-year-old with dramatic collapses during family conflict","tags":{"topic":"somatic","difficulty":4,"objective":"Formulate dissociative seizures alongside personality traits without blaming","exams":["md-psychiatry","mcp-entrance"],"module":"more-disorders","diagnosis":"Dissociative (functional) seizures with histrionic personality traits"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-267', 'Mr Rathod: charming, cold and back in custody (antisocial personality disorder with high psychopathic traits)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-267-1","text":"Long record of fraud, assault and broken parole; charming in interview but shows no remorse","bucket":"presenting"},{"id":"form-267-2","text":"Lies easily and blames victims","bucket":"presenting"},{"id":"form-267-3","text":"Conduct problems before 15, including fire-setting and cruelty to animals","bucket":"predisposing"},{"id":"form-267-4","text":"Assaulted a business partner who confronted him about missing money","bucket":"precipitating"},{"id":"form-267-5","text":"Heavy alcohol and cocaine use","bucket":"perpetuating"},{"id":"form-267-6","text":"Harsh, inconsistent parenting and a father in prison","bucket":"predisposing"},{"id":"form-267-7","text":"Persecutory voices that tell him to attack people","bucket":"distractor"},{"id":"form-267-8","text":"Has kept one job for two years in the past","bucket":"protective"},{"id":"form-267-9","text":"Peers involved in crime","bucket":"perpetuating"},{"id":"form-267-10","text":"Sees rules as for other people and treatment as a way to get a lighter sentence","bucket":"perpetuating"},{"id":"form-267-11","text":"Some attachment to his teenage daughter","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Rathod, 38, shows antisocial personality disorder with marked psychopathic traits: persistent disregard for others'' rights with conduct problems before 15, deceit, aggression, lack of remorse and superficial charm. A structured risk formulation looks at history, current state and future plans. Early conduct problems, harsh parenting and a father in prison (predisposing) underlie his pattern; the confrontation over money (precipitating) led to the assault. Alcohol and cocaine, criminal peers and his view of treatment as a tool (perpetuating) raise his risk. Some attachment to his daughter and a past period of stable work (protective) are limited but real. There are no psychotic symptoms, so voices commanding attacks are a distractor. Management focuses on risk scenarios, substance treatment, structured programmes and clear boundaries.","hint":"A 38-year-old in a prison hospital awaiting trial for fraud and assault","tags":{"topic":"forensic","difficulty":5,"objective":"Build a structured violence risk formulation in antisocial personality disorder","exams":["md-psychiatry","mcp-entrance"],"module":"personality","diagnosis":"Antisocial personality disorder with marked psychopathic traits"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-268', 'Komal: afraid to be left, quick to self-harm (borderline personality disorder, core features)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-268-1","text":"Frantic efforts to avoid being left, with intense relationships that swing from idealising to hating","bucket":"presenting"},{"id":"form-268-2","text":"Her roommate moved out to live with a new friend","bucket":"precipitating"},{"id":"form-268-3","text":"Self-harm brings short relief from overwhelming emotion","bucket":"perpetuating"},{"id":"form-268-4","text":"Willing to join a skills group","bucket":"protective"},{"id":"form-268-5","text":"Unstable home with parents who often threatened to leave","bucket":"predisposing"},{"id":"form-268-6","text":"Doing well in her psychology course","bucket":"protective"},{"id":"form-268-7","text":"Self-harm and threats of suicide during conflicts, and chronic emptiness","bucket":"presenting"},{"id":"form-268-8","text":"She grew up in Ranchi","bucket":"distractor"},{"id":"form-268-9","text":"Clings to new friends, who then pull away","bucket":"perpetuating"},{"id":"form-268-10","text":"Emotional sensitivity from childhood","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Komal, 22, shows the core features of borderline personality disorder: fear of abandonment, unstable intense relationships, self-harm, emptiness and emotional swings. An unstable home with threats of leaving and an emotionally sensitive temperament (predisposing) shaped these patterns; her roommate moving out (precipitating) set off a crisis. Clinging that pushes friends away and the short relief of self-harm (perpetuating) keep the cycle going. Success in her course and willingness to join a skills group (protective) are hopeful. Borderline personality disorder responds well to structured therapies such as DBT. Her home town is a distractor.","hint":"A 22-year-old student whose friends say she is ''too intense''","tags":{"topic":"personality","difficulty":1,"objective":"Recognise the core features of borderline personality disorder","exams":["cuet-pg","ma-semester","mcp-entrance","ugc-net"],"module":"personality","diagnosis":"Borderline personality disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-269', 'Mrs Fernandes: the daughter''s visits that are never enough (long-standing borderline traits in later life)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-269-1","text":"Accuses her daughter of abandoning her, then calls her a saint, many times a day","bucket":"presenting"},{"id":"form-269-2","text":"Lives alone and has few friends left","bucket":"perpetuating"},{"id":"form-269-3","text":"Similar stormy relationships all her adult life, described by her siblings","bucket":"predisposing"},{"id":"form-269-4","text":"Active in her parish choir","bucket":"protective"},{"id":"form-269-5","text":"Death of her husband, who had calmed and steadied her, a year ago","bucket":"precipitating"},{"id":"form-269-6","text":"Daughter swings between giving in and withdrawing","bucket":"perpetuating"},{"id":"form-269-7","text":"Lost her mother at age five","bucket":"predisposing"},{"id":"form-269-8","text":"Took an overdose of her blood pressure tablets after her daughter went on holiday","bucket":"presenting"},{"id":"form-269-9","text":"Memory and thinking tested as normal","bucket":"protective"},{"id":"form-269-10","text":"Health problems limit her outings","bucket":"perpetuating"},{"id":"form-269-11","text":"New changes in personality starting only this year, with memory loss","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Fernandes, 72, shows long-standing borderline personality disorder now presenting in later life: unstable relationships alternating between idealising and devaluing, fear of abandonment and a recent overdose. Personality disorders persist into old age, though impulsive behaviour often lessens, and losses can expose them. A pattern described through her adult life and the early loss of her mother (predisposing) shaped her; her husband''s death (precipitating) removed the person who steadied her. Living alone, few friends, her daughter''s inconsistent responses and health limits (perpetuating) maintain crises. Normal cognitive tests and her choir (protective) help. New personality change with memory loss would point to dementia and is a distractor; it does not fit her lifelong history. The plan includes risk management, therapy adapted for older adults and support for her daughter.","hint":"A 72-year-old widow whose daughter feels exhausted by her calls and accusations","tags":{"topic":"personality","difficulty":4,"objective":"Recognise personality difficulties in an older adult and rule out new brain disease","exams":["md-psychiatry","mcp-entrance"],"module":"lifespan","diagnosis":"Borderline personality disorder in later life, long-standing"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-270', 'Dr Prateek: the surgeon who cannot bear a complaint (narcissistic personality traits with depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-270-1","text":"Parents valued him only for achievements","bucket":"predisposing"},{"id":"form-270-2","text":"Respected for his skill","bucket":"protective"},{"id":"form-270-3","text":"Low mood, poor sleep and rage since a patient''s family complained about him to the hospital","bucket":"presenting"},{"id":"form-270-4","text":"A formal complaint and inquiry after a surgical complication","bucket":"precipitating"},{"id":"form-270-5","text":"He works in a private hospital in Pune","bucket":"distractor"},{"id":"form-270-6","text":"Works longer hours to prove himself and sleeps less","bucket":"perpetuating"},{"id":"form-270-7","text":"Wife who encouraged him to come","bucket":"protective"},{"id":"form-270-8","text":"Will not consider therapy as he sees it as weakness","bucket":"perpetuating"},{"id":"form-270-9","text":"Feels humiliated and has thoughts that life is not worth living","bucket":"presenting"},{"id":"form-270-10","text":"Lifelong need to be admired and difficulty with criticism","bucket":"predisposing"},{"id":"form-270-11","text":"Avoids colleagues to hide his shame","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Dr Prateek, 36, presents with a depressive episode in the context of narcissistic personality traits. Behind his grandiosity lies fragile self-esteem, so criticism can trigger deep shame, rage and depression, and suicide risk can rise sharply after a public humiliation. Parents who valued only achievement and a lifelong need for admiration (predisposing) shaped this vulnerability; the complaint and inquiry (precipitating) wounded his self-image. Avoiding colleagues, overworking and seeing therapy as weakness (perpetuating) maintain the depression. His skill and supportive wife (protective) help. The plan assesses suicide risk carefully, treats depression, offers confidential doctors'' support and uses a respectful, non-shaming therapy approach. The hospital''s location is a distractor.","hint":"A 36-year-old surgeon who became low and furious after a patient complaint","tags":{"topic":"personality","difficulty":3,"objective":"Formulate depression in a person with narcissistic vulnerability","exams":["mcp-entrance","md-psychiatry","ugc-net"],"module":"personality","diagnosis":"Depressive episode in a man with narcissistic personality traits"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-271', 'Anil: always a loner, always the same routine (autism, not schizoid personality)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-271-1","text":"Few friends, prefers routines and becomes very distressed when they change","bucket":"presenting"},{"id":"form-271-2","text":"Sensory overload in the noisy new building","bucket":"perpetuating"},{"id":"form-271-3","text":"Colleagues tease him for literal replies","bucket":"perpetuating"},{"id":"form-271-4","text":"His library moved to a new building, breaking all his routines","bucket":"precipitating"},{"id":"form-271-5","text":"Mother who remembers his childhood clearly","bucket":"protective"},{"id":"form-271-6","text":"Brother''s son was recently diagnosed with autism","bucket":"predisposing"},{"id":"form-271-7","text":"Valued for his memory and accuracy at work","bucket":"protective"},{"id":"form-271-8","text":"Indifference to people with no difficulty reading social cues and no special interests or routines","bucket":"distractor"},{"id":"form-271-9","text":"Late to speak and lined up toys as a child, according to his mother","bucket":"predisposing"},{"id":"form-271-10","text":"Takes things literally, misses social cues and has a deep interest in railway timetables","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Anil, 40, has autism spectrum disorder diagnosed in adulthood. Unlike schizoid personality disorder, in which people are indifferent to relationships but understand social cues, he has difficulty reading social signals, takes language literally, depends on routines and has an intense special interest, with early developmental signs reported by his mother. The distractor describing indifference without social communication difficulty or routines fits schizoid personality instead. A developmental history and a nephew with autism (predisposing) support the diagnosis; the library''s move (precipitating) broke his routines. Teasing and sensory overload (perpetuating) maintain distress. His mother''s account and his valued skills (protective) help. The plan offers explanation, workplace adjustments and support for change.","hint":"A 40-year-old librarian referred for ''lack of interest in people''","tags":{"topic":"neurodevelopmental","difficulty":4,"objective":"Tell autism apart from schizoid personality disorder","exams":["md-psychiatry","mcp-entrance"],"module":"child","diagnosis":"Autism spectrum disorder without intellectual disability, diagnosed in adulthood"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-272', 'Chintu: questions about where Nani has gone (grief in a young child)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-272-1","text":"Good friends at school","bucket":"protective"},{"id":"form-272-2","text":"Loving parents who want to help","bucket":"protective"},{"id":"form-272-3","text":"Clingy, bedwetting again and asking repeatedly when his grandmother will come back, for six weeks","bucket":"presenting"},{"id":"form-272-4","text":"Grandmother cared for him daily while his parents worked","bucket":"predisposing"},{"id":"form-272-5","text":"Adults tell him she has ''gone to sleep'', which makes him afraid of sleeping","bucket":"perpetuating"},{"id":"form-272-6","text":"He goes to school in Indore","bucket":"distractor"},{"id":"form-272-7","text":"Sensitive child","bucket":"predisposing"},{"id":"form-272-8","text":"Parents avoid talking about her to protect him","bucket":"perpetuating"},{"id":"form-272-9","text":"Plays happily at times, then becomes tearful","bucket":"presenting"},{"id":"form-272-10","text":"Grandmother died suddenly of a stroke; he was sent to a neighbour''s home during the rituals","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Chintu, 7, shows a normal grief reaction: clinginess, temporary bedwetting, repeated questions about his grandmother''s return and moving in and out of sadness, which is typical of young children. At this age children often do not yet fully understand that death is permanent. A close daily bond with his grandmother and a sensitive temperament (predisposing) shape the depth of his reaction; her sudden death and being sent away during the rituals (precipitating) left him confused. Being told she has ''gone to sleep'' and adults avoiding the topic (perpetuating) add fear and confusion. Loving parents and school friends (protective) are strengths. Advice: use clear, simple words about death, include him in remembering her, keep routines and reassure him about sleep. His school location is a distractor.","hint":"A 7-year-old who is clingy and wets the bed since his grandmother died","tags":{"topic":"grief","difficulty":2,"objective":"Formulate a normal grief reaction in a young child","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"lifespan","diagnosis":"Normal grief reaction in a child"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-273', 'Sneha: why did my brother not tell me? (bereavement after suicide)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-273-1","text":"She works at a travel agency in Kochi","bucket":"distractor"},{"id":"form-273-2","text":"Past episode of depression at 19","bucket":"predisposing"},{"id":"form-273-3","text":"Willing to join a support group for people bereaved by suicide","bucket":"protective"},{"id":"form-273-4","text":"Relatives tell neighbours it was an accident, so she cannot talk about it openly","bucket":"perpetuating"},{"id":"form-273-5","text":"Supportive partner","bucket":"protective"},{"id":"form-273-6","text":"Blames herself for not answering his last call","bucket":"perpetuating"},{"id":"form-273-7","text":"Her brother''s death by suicide after he lost his job","bucket":"precipitating"},{"id":"form-273-8","text":"Very close to her brother since childhood","bucket":"predisposing"},{"id":"form-273-9","text":"Poor sleep and passive thoughts that she would like to be with him","bucket":"presenting"},{"id":"form-273-10","text":"Guilt, anger and endless questions about what she missed, four months after her brother''s suicide","bucket":"presenting"},{"id":"form-273-11","text":"Rereads his last messages every night","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sneha, 26, is grieving after her brother''s suicide. Grief after suicide often carries intense guilt, anger, searching for reasons and stigma, and the bereaved have a higher risk of suicide themselves, so her passive wish to be with him needs careful risk assessment. A very close bond and her past depression (predisposing) increase her vulnerability; his death by suicide (precipitating) is the loss. Family secrecy that blocks open talk, nightly rereading of his messages and self-blame for the missed call (perpetuating) keep her grief raw. Her partner and willingness to join a suicide bereavement group (protective) are important. The plan checks risk, offers grief-focused support and screens for depression. Her workplace is a distractor.","hint":"A 26-year-old whose brother died by suicide four months ago","tags":{"topic":"grief","difficulty":3,"objective":"Formulate the special features of grief after a suicide","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"suicide","diagnosis":"Grief after suicide bereavement, with risk to the bereaved"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-274', 'Mr Bhide: grief that turned into something else (major depression after bereavement)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-274-1","text":"Son who calls daily from Pune","bucket":"protective"},{"id":"form-274-2","text":"Long friendship with a neighbour","bucket":"protective"},{"id":"form-274-3","text":"Mother had depression","bucket":"predisposing"},{"id":"form-274-4","text":"Waves of sadness linked to memories of his wife, with self-esteem intact and moments of warmth","bucket":"distractor"},{"id":"form-274-5","text":"Feels worthless, has slowed movements, has lost eight kilos and thinks he deserves to die","bucket":"presenting"},{"id":"form-274-6","text":"Episode of depression in his forties","bucket":"predisposing"},{"id":"form-274-7","text":"Lives alone and has stopped cooking","bucket":"perpetuating"},{"id":"form-274-8","text":"Death of his wife of forty years after a long illness","bucket":"precipitating"},{"id":"form-274-9","text":"Believes seeking help would dishonour her memory","bucket":"perpetuating"},{"id":"form-274-10","text":"Three months after his wife''s death, constant low mood with no moments of relief","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Bhide, 66, has a major depressive episode after bereavement, not only normal grief. In grief, sadness comes in waves tied to the loss, with self-esteem preserved and moments of humour; that is the distractor. His mood is low all the time, with worthlessness, slowing, marked weight loss and thoughts that he deserves to die, which mark depression and raise urgent risk questions. A past depressive episode and a mother with depression (predisposing) raise his vulnerability; his wife''s death (precipitating) triggered the episode. Living alone, not eating and believing help would dishonour her (perpetuating) maintain it. His son and neighbour (protective) can support a plan of urgent risk assessment, antidepressant treatment, nutrition and grief support.","hint":"A 66-year-old widower who feels worthless and has stopped eating","tags":{"topic":"grief","difficulty":4,"objective":"Tell a depressive episode apart from normal grief after a loss","exams":["md-psychiatry","mcp-entrance"],"module":"depression","diagnosis":"Major depressive disorder, single episode, following bereavement"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-275', 'Rukmini: the grief nobody would let her show (disenfranchised grief)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-275-1","text":"Twenty-year hidden relationship with a married man","bucket":"predisposing"},{"id":"form-275-2","text":"Widowed young, with few close friends","bucket":"predisposing"},{"id":"form-275-3","text":"Her partner died suddenly of a heart attack","bucket":"precipitating"},{"id":"form-275-4","text":"Has started writing letters to him","bucket":"protective"},{"id":"form-275-5","text":"Could not attend the funeral or tell anyone why she is grieving","bucket":"presenting"},{"id":"form-275-6","text":"Shame and fear of gossip in her small town","bucket":"perpetuating"},{"id":"form-275-7","text":"Not allowed to grieve publicly or join rituals","bucket":"perpetuating"},{"id":"form-275-8","text":"Deep sadness, numbness and sleeplessness for two months","bucket":"presenting"},{"id":"form-275-9","text":"No one knows, so no one offers comfort","bucket":"perpetuating"},{"id":"form-275-10","text":"She lives in a town near Nashik","bucket":"distractor"},{"id":"form-275-11","text":"Works as a school librarian and loves her work","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rukmini, 48, is experiencing disenfranchised grief: a loss that society does not recognise, so the bereaved person cannot mourn openly or receive support. A long hidden relationship and few close friends (predisposing) left her isolated; her partner''s sudden death (precipitating) is the loss. Lack of comfort, exclusion from rituals and fear of gossip (perpetuating) block the normal supports of grief. Her valued work and letter writing (protective) are healthy ways of continuing the bond. Therapy offers a private place to grieve, to create her own rituals and to screen for depression and prolonged grief. Her town is a distractor.","hint":"A 48-year-old woman whose long-term secret partner died","tags":{"topic":"grief","difficulty":3,"objective":"Formulate grief that cannot be openly acknowledged","exams":["mcp-entrance","md-psychiatry","ugc-net"],"module":"lifespan","diagnosis":"Grief complicated by lack of social recognition (disenfranchised grief)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-276', 'Dr Anjali: the father she could not hold (prolonged grief disorder in a doctor)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-276-1","text":"Husband who is patient and supportive","bucket":"protective"},{"id":"form-276-2","text":"Believes she should have saved him and that being a doctor made it worse","bucket":"perpetuating"},{"id":"form-276-3","text":"Avoids all reminders, so grief cannot be processed","bucket":"perpetuating"},{"id":"form-276-4","text":"She has two dogs","bucket":"distractor"},{"id":"form-276-5","text":"Intense yearning for her father and inability to accept his death, over two years later","bucket":"presenting"},{"id":"form-276-6","text":"High standards and a tendency to blame herself","bucket":"predisposing"},{"id":"form-276-7","text":"Very close to her father, who raised her after her mother died","bucket":"predisposing"},{"id":"form-276-8","text":"Avoids his room and photographs, feels part of her died with him, and has not returned to work in intensive care","bucket":"presenting"},{"id":"form-276-9","text":"Her father died of COVID in another hospital while she was treating patients; she could not be with him","bucket":"precipitating"},{"id":"form-276-10","text":"Still active in teaching medical students","bucket":"protective"},{"id":"form-276-11","text":"Colleagues avoid the subject","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Dr Anjali, 39, presents with prolonged grief disorder: persistent, intense yearning and preoccupation with her father well beyond twelve months, with difficulty accepting the death, emotional numbness, a sense that part of her died and marked impairment. Guilt from not being able to save him or be with him adds moral injury. A very close bond with her father and harsh self-blame (predisposing) increased risk; dying apart from her during the pandemic (precipitating) made the loss traumatic. Beliefs that she failed him, avoidance of reminders and colleagues'' silence (perpetuating) prevent her grief from moving. Her husband and her teaching (protective) are strengths. Grief-focused therapy can address avoidance, guilt and meaning; also screen for depression and PTSD. The dogs are a distractor.","hint":"A 39-year-old intensive care doctor whose father died during the pandemic","tags":{"topic":"grief","difficulty":5,"objective":"Formulate prolonged grief disorder with guilt and work-related trauma","exams":["md-psychiatry","mcp-entrance"],"module":"lifespan","diagnosis":"Prolonged grief disorder with features of moral injury"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-277', 'Ritika: the results evening (suicide risk in an adolescent)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-277-1","text":"Has not told anyone how long she has felt low","bucket":"perpetuating"},{"id":"form-277-2","text":"Perfectionist who ties her worth to marks","bucket":"predisposing"},{"id":"form-277-3","text":"Friend who received the message and alerted her parents","bucket":"protective"},{"id":"form-277-4","text":"Parents compared her with a topper cousin that evening","bucket":"perpetuating"},{"id":"form-277-5","text":"Close to her music teacher","bucket":"protective"},{"id":"form-277-6","text":"Scored lower than her parents expected in the board exams","bucket":"precipitating"},{"id":"form-277-7","text":"Low mood, guilt and poor sleep for two months before the exams","bucket":"presenting"},{"id":"form-277-8","text":"She studies science stream in Jaipur","bucket":"distractor"},{"id":"form-277-9","text":"Wrote a goodbye message to a friend on the night of her board results","bucket":"presenting"},{"id":"form-277-10","text":"Cousin died by suicide two years ago","bucket":"predisposing"},{"id":"form-277-11","text":"Spends nights reading online posts about hopelessness","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ritika, 17, presents with a depressive episode and high suicide risk after her board results. Young people under exam pressure are at real risk, especially when worth is tied to marks. A cousin''s suicide and perfectionism (predisposing) raise her vulnerability; lower than expected marks (precipitating) triggered the crisis. Being compared with a cousin, reading hopeless content online and hiding her low mood (perpetuating) increase risk. The friend who raised the alarm and her music teacher (protective) are vital. Immediate steps: safety planning with her and her parents, removing means at home, close follow-up, treatment for depression and work with the family on expectations. Her stream and city are distractors.","hint":"A 17-year-old who wrote a goodbye message after her board results","tags":{"topic":"suicide-risk","difficulty":2,"objective":"Sort risk and protective factors for adolescent suicide into the 5 Ps","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"suicide","diagnosis":"Depressive episode with high suicide risk in an adolescent"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-278', 'Mr Sharma: the scan result and the silent house (suicide risk in an older man)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-278-1","text":"Older man living alone after his wife''s death","bucket":"predisposing"},{"id":"form-278-2","text":"Has given away his watch and books to his grandsons","bucket":"presenting"},{"id":"form-278-3","text":"Withdrawn and saying he does not want to be ''a burden'' since hearing the cancer has spread","bucket":"presenting"},{"id":"form-278-4","text":"Believes he will be a burden to his son","bucket":"perpetuating"},{"id":"form-278-5","text":"Told a week ago that his prostate cancer has spread to his bones","bucket":"precipitating"},{"id":"form-278-6","text":"Son who visits every weekend","bucket":"protective"},{"id":"form-278-7","text":"He retired as a railway station master in Agra","bucket":"distractor"},{"id":"form-278-8","text":"Keeps a stock of his late wife''s sleeping tablets","bucket":"perpetuating"},{"id":"form-278-9","text":"Proud, private and has never asked for help","bucket":"predisposing"},{"id":"form-278-10","text":"Respected member of his temple committee","bucket":"protective"},{"id":"form-278-11","text":"Uncontrolled bone pain","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Sharma, 70, presents with depression and high suicide risk. Older men living alone, with a new serious illness, pain and a sense of being a burden, are among the highest-risk groups. Giving away valued belongings is a warning sign. Being an older widower who never asks for help (predisposing) raises risk; learning the cancer has spread (precipitating) is the trigger. Uncontrolled pain, burden beliefs and access to stored tablets (perpetuating) make risk acute. His son''s visits and temple role (protective) can be drawn on. Immediate steps: ask clearly about suicidal thoughts and plans, remove the stored tablets, control pain with the palliative team, treat depression and involve his son. His past job is a distractor.","hint":"A 70-year-old widower told last week that his cancer has spread","tags":{"topic":"suicide-risk","difficulty":3,"objective":"Formulate the high suicide risk of older men with illness and isolation","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"suicide","diagnosis":"Depressive episode with high suicide risk in later life"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-279', 'Sunny: the thoughts that are always there, and the night that was different (chronic and acute suicide risk)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-279-1","text":"This week he has a specific plan, has written letters and says he feels oddly calm","bucket":"presenting"},{"id":"form-279-2","text":"Has stopped seeing his therapist","bucket":"perpetuating"},{"id":"form-279-3","text":"Close to his niece and has promised to attend her birthday","bucket":"protective"},{"id":"form-279-4","text":"Has had thoughts of death most days for ten years","bucket":"presenting"},{"id":"form-279-5","text":"Has used his safety plan in the past","bucket":"protective"},{"id":"form-279-6","text":"Drinking heavily","bucket":"perpetuating"},{"id":"form-279-7","text":"Staff at the emergency department told him last time he was ''attention seeking''","bucket":"perpetuating"},{"id":"form-279-8","text":"He works as a call centre trainer in Gurugram","bucket":"distractor"},{"id":"form-279-9","text":"Diagnosis of borderline personality disorder","bucket":"predisposing"},{"id":"form-279-10","text":"Childhood abuse and many past self-harm episodes","bucket":"predisposing"},{"id":"form-279-11","text":"Lost his job and his long-term partner in the same month","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sunny, 28, has chronic suicidal thoughts as part of borderline personality disorder, but his risk has risen sharply now. Chronic risk is his baseline; acute warning signs this week include a specific plan, writing letters and a sudden calm after deciding, which often signals danger. Childhood abuse, past self-harm and his diagnosis (predisposing) shape his baseline risk; losing his job and partner together (precipitating) are major losses. Stopping therapy, heavy drinking and being dismissed by staff (perpetuating) increase acute risk. His bond with his niece and past use of a safety plan (protective) are strengths. The plan treats this as an emergency: close supervision, a review of his safety plan, alcohol treatment and reconnecting him with his therapist. His job and city are distractors.","hint":"A 28-year-old with long-standing suicidal thoughts who now has a plan","tags":{"topic":"suicide-risk","difficulty":4,"objective":"Tell a rise in acute risk apart from a baseline of chronic suicidal thoughts","exams":["md-psychiatry","mcp-entrance"],"module":"suicide","diagnosis":"Borderline personality disorder with chronic suicidal ideation and acutely raised risk"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-280', 'Constable Yadav: the service pistol and the evening bottle (suicide risk with access to a firearm)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-280-1","text":"Father died by suicide","bucket":"predisposing"},{"id":"form-280-2","text":"Drinks every evening, keeps his service pistol at home, and has said ''one bullet would solve everything''","bucket":"presenting"},{"id":"form-280-3","text":"Alone at home","bucket":"perpetuating"},{"id":"form-280-4","text":"Suspended after an internal inquiry, and his wife took the children to her parents'' home","bucket":"precipitating"},{"id":"form-280-5","text":"Easy access to a firearm","bucket":"perpetuating"},{"id":"form-280-6","text":"Exposed to violent deaths in his work for fifteen years","bucket":"predisposing"},{"id":"form-280-7","text":"Alcohol lowers his restraint","bucket":"perpetuating"},{"id":"form-280-8","text":"Shame and police culture stop him seeking help","bucket":"perpetuating"},{"id":"form-280-9","text":"Low mood, insomnia and hopelessness for four months","bucket":"presenting"},{"id":"form-280-10","text":"Close bond with his son","bucket":"protective"},{"id":"form-280-11","text":"A senior officer he trusts who noticed the change","bucket":"protective"},{"id":"form-280-12","text":"He likes watching wrestling","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Constable Yadav, 41, has depression with an alcohol use disorder and very high suicide risk. A family history of suicide and repeated exposure to violent death (predisposing) raise his risk; suspension and his family leaving (precipitating) are major losses of role and connection. Access to a firearm is the most dangerous factor, because firearms are very lethal and leave little time for rescue; alcohol, shame, police culture and being alone (perpetuating) add to the danger. His bond with his son and a trusted senior officer (protective) can help. Urgent actions include working with the senior officer to remove the weapon from home, close monitoring or admission, treating depression and alcohol, and involving his family with consent. Wrestling is a distractor.","hint":"A 41-year-old police constable with depression and heavy drinking","tags":{"topic":"suicide-risk","difficulty":5,"objective":"Build a full risk formulation where access to lethal means is central","exams":["md-psychiatry","mcp-entrance"],"module":"suicide","diagnosis":"Depressive episode with alcohol use disorder and very high suicide risk"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-281', 'Laxmi: the pesticide bottle after the quarrel (impulsive self-poisoning)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-281-1","text":"Married at 18 into a joint family with frequent conflict","bucket":"predisposing"},{"id":"form-281-2","text":"Two young children she loves","bucket":"protective"},{"id":"form-281-3","text":"Drank pesticide within minutes of a quarrel with her husband and mother-in-law","bucket":"presenting"},{"id":"form-281-4","text":"A quarrel over dowry demands and her husband slapping her","bucket":"precipitating"},{"id":"form-281-5","text":"Her brother wants to support her","bucket":"protective"},{"id":"form-281-6","text":"Ongoing harassment from her in-laws","bucket":"perpetuating"},{"id":"form-281-7","text":"No one to talk to in her husband''s village","bucket":"perpetuating"},{"id":"form-281-8","text":"Impulsive when angry since her teens","bucket":"predisposing"},{"id":"form-281-9","text":"The family grows cotton in Vidarbha","bucket":"distractor"},{"id":"form-281-10","text":"Pesticide stored openly in the house","bucket":"perpetuating"},{"id":"form-281-11","text":"Regretted it at once and called for help; no long-standing low mood","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Laxmi, 32, made an impulsive suicide attempt by drinking pesticide minutes after a violent quarrel, with immediate regret and no long history of depression. In rural India, many suicide attempts are impulsive and pesticides are both easy to reach and highly lethal, so safe storage saves lives. Early marriage into a conflictual home and an impulsive temperament (predisposing) raise vulnerability; dowry demands and being slapped (precipitating) triggered the act. Pesticide at home, continued harassment and isolation (perpetuating) keep her at risk. Her children and her brother (protective) are important. The plan includes medical care, safety assessment for domestic violence and dowry harassment with legal support, safe storage or removal of pesticides, and follow-up. The crop is a distractor.","hint":"A 32-year-old woman admitted after drinking pesticide during a fight","tags":{"topic":"suicide-risk","difficulty":2,"objective":"Formulate an impulsive suicide attempt and the role of means","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"suicide","diagnosis":"Impulsive suicide attempt by self-poisoning, in the context of domestic conflict"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-282', 'Rafiq: the moneylender''s visits (suicide risk in a migrant worker in debt)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-282-1","text":"Ashamed to tell his family about the debt","bucket":"perpetuating"},{"id":"form-282-2","text":"Drinks alcohol at weekends","bucket":"predisposing"},{"id":"form-282-3","text":"Low mood, poor sleep and hopelessness for two months","bucket":"presenting"},{"id":"form-282-4","text":"Deep love for his children","bucket":"protective"},{"id":"form-282-5","text":"Says his family would be better off with the insurance money","bucket":"presenting"},{"id":"form-282-6","text":"A contractor who has offered lighter work","bucket":"protective"},{"id":"form-282-7","text":"Borrowed money at high interest for his daughter''s wedding and has lost work after an injury","bucket":"precipitating"},{"id":"form-282-8","text":"Lives in a crowded room with no close friends","bucket":"perpetuating"},{"id":"form-282-9","text":"Moneylender threatens him and his family","bucket":"perpetuating"},{"id":"form-282-10","text":"He works on high-rise buildings","bucket":"distractor"},{"id":"form-282-11","text":"Migrated alone from Bihar ten years ago","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rafiq, 45, presents with depression and suicide risk driven by debt. Financial crisis, especially with threats from moneylenders, is a strong suicide risk factor in India. Migrating alone and weekend drinking (predisposing) increase vulnerability; a high-interest wedding loan and loss of work after injury (precipitating) created an unpayable debt. Threats, isolation and shame (perpetuating) narrow his choices, and the belief that his family would be better off is a serious warning sign. His love for his children and the contractor''s offer (protective) open doors. The plan assesses risk directly, connects him to legal aid against illegal lending, labour welfare support, treatment for depression and alcohol, and safe contact with his family. His type of work is a distractor.","hint":"A 45-year-old construction worker in Surat with mounting debt","tags":{"topic":"suicide-risk","difficulty":3,"objective":"Formulate suicide risk driven by financial crisis and isolation","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"suicide","diagnosis":"Depressive episode with suicide risk linked to debt and migration"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-283', 'Ananya: the cuts that bring relief, not death (non-suicidal self-injury)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-283-1","text":"She studies economics","bucket":"distractor"},{"id":"form-283-2","text":"Hides wounds and avoids the college doctor","bucket":"perpetuating"},{"id":"form-283-3","text":"Anxious since childhood","bucket":"predisposing"},{"id":"form-283-4","text":"Few other ways to manage strong emotions","bucket":"perpetuating"},{"id":"form-283-5","text":"Cutting brings quick relief, which reinforces it","bucket":"perpetuating"},{"id":"form-283-6","text":"Cuts her forearm several times a month to relieve unbearable tension, for two years","bucket":"presenting"},{"id":"form-283-7","text":"Emotionally invalidating home where feelings were dismissed","bucket":"predisposing"},{"id":"form-283-8","text":"Enjoys painting","bucket":"protective"},{"id":"form-283-9","text":"Denies wanting to die and feels calmer afterwards","bucket":"presenting"},{"id":"form-283-10","text":"Moved to a hostel in Delhi and began struggling with her course","bucket":"precipitating"},{"id":"form-283-11","text":"Says she cut with the intention of ending her life and was disappointed to wake up","bucket":"distractor"},{"id":"form-283-12","text":"Roommate she trusts","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ananya, 20, presents with non-suicidal self-injury: repeated cutting to relieve tension without the intent to die. The distractor describing an intention to die and disappointment at surviving would mean a suicide attempt and is not her account; still, self-injury raises the long-term risk of suicide, so risk must be reviewed regularly. An invalidating home and anxious temperament (predisposing) left her with few ways to manage feelings; hostel life and course stress (precipitating) increased her distress. The quick relief of cutting, secrecy and lack of other skills (perpetuating) keep it going. Her trusted roommate and painting (protective) help. The plan offers wound care advice without judgement, emotion regulation skills, and treatment of anxiety. Her course is a distractor.","hint":"A 20-year-old who cuts to calm herself and denies wanting to die","tags":{"topic":"suicide-risk","difficulty":4,"objective":"Tell non-suicidal self-injury apart from a suicide attempt while keeping risk in view","exams":["md-psychiatry","mcp-entrance","ma-semester"],"module":"suicide","diagnosis":"Non-suicidal self-injury with emotion regulation difficulties"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-284', 'Baldev: the goddess who speaks through him at the jagran (trance and possession disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-284-1","text":"Wife who noticed the change and brought him","bucket":"protective"},{"id":"form-284-2","text":"Episodes give him relief from overwhelming worry","bucket":"perpetuating"},{"id":"form-284-3","text":"Episodes now happen at home and at work, outside religious gatherings, and frighten his family","bucket":"presenting"},{"id":"form-284-4","text":"Persistent voices and beliefs between episodes, with a decline in self-care","bucket":"distractor"},{"id":"form-284-5","text":"Few ways of expressing personal distress","bucket":"predisposing"},{"id":"form-284-6","text":"Respected by villagers","bucket":"protective"},{"id":"form-284-7","text":"The family sees each episode as a blessing and asks the goddess questions","bucket":"perpetuating"},{"id":"form-284-8","text":"His son''s arrest in a land dispute","bucket":"precipitating"},{"id":"form-284-9","text":"Long-standing role in the village as someone the goddess visits during the jagran","bucket":"predisposing"},{"id":"form-284-10","text":"Avoids talking about his son","bucket":"perpetuating"},{"id":"form-284-11","text":"Episodes in which he speaks in another voice as a goddess, then has no memory of them","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Baldev, 50, presents with trance and possession disorder. Trance and possession that occur within accepted religious practice are not a disorder; they become one when they happen involuntarily, outside cultural settings, and cause distress or impairment, as now. A long-standing role as a vessel for the goddess and limited ways of expressing distress (predisposing) shape the form of his reaction; his son''s arrest (precipitating) brought overwhelming worry. Family responses that treat episodes as blessings, avoidance of the topic and relief from worry during episodes (perpetuating) maintain them. His standing and his wife''s concern (protective) help. Psychosis is less likely, as the distractor of persistent voices and decline between episodes does not fit. The plan respects his beliefs while addressing his worry, with family guidance and support.","hint":"A 50-year-old man whose possession episodes now happen outside rituals","tags":{"topic":"culture","difficulty":3,"objective":"Tell a culturally accepted trance from a possession disorder","exams":["mcp-entrance","md-psychiatry","ugc-net"],"module":"more-disorders","diagnosis":"Trance and possession disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-285', 'Bikash: the fear that his body is shrinking away (koro)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-285-1","text":"Every bodily sensation is checked repeatedly","bucket":"perpetuating"},{"id":"form-285-2","text":"Relatives tie a string to prevent ''retraction'', which increases his fear","bucket":"perpetuating"},{"id":"form-285-3","text":"Anxious temperament and guilt about masturbation","bucket":"predisposing"},{"id":"form-285-4","text":"Reassured partly by a trusted local doctor","bucket":"protective"},{"id":"form-285-5","text":"Belief in his community that such retraction can be fatal","bucket":"predisposing"},{"id":"form-285-6","text":"No past mental illness","bucket":"protective"},{"id":"form-285-7","text":"Holding it tightly, palpitations and sweating; examination is normal","bucket":"presenting"},{"id":"form-285-8","text":"Sudden intense fear that his penis is shrinking into his body and that he will die","bucket":"presenting"},{"id":"form-285-9","text":"He works at a tea stall near Guwahati","bucket":"distractor"},{"id":"form-285-10","text":"Heard that several men in a nearby village had the same problem last week","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Bikash, 22, presents with koro, a culture-related syndrome of acute fear that the genitals are retracting into the body, with the belief that this could be fatal. It has occurred in outbreaks in parts of north-east India and South East Asia and usually responds to reassurance and education. Community beliefs about fatal retraction and an anxious, guilty temperament (predisposing) shape the fear; hearing of cases in a nearby village (precipitating) sparked his episode. Relatives'' physical measures and repeated checking (perpetuating) feed the anxiety. His partial reassurance by a trusted doctor and no past illness (protective) suggest a good outcome with calm explanation, examination, education about the body and brief anxiety management. The tea stall is a distractor.","hint":"A 22-year-old in Assam convinced his genitals are retracting into his body","tags":{"topic":"culture","difficulty":2,"objective":"Recognise a culture-related anxiety syndrome","exams":["mcp-entrance","ma-semester","ugc-net","cuet-pg"],"module":"anxiety","diagnosis":"Koro (genital retraction syndrome), an acute anxiety reaction"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-286', 'Mr Chhabra: seventy and still at war with everyone (paranoid traits in an older man, not a new psychosis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-286-1","text":"Has filed three police complaints this year; no hallucinations and no fixed bizarre beliefs","bucket":"presenting"},{"id":"form-286-2","text":"Cannot hear conversations, so assumes people talk about him","bucket":"perpetuating"},{"id":"form-286-3","text":"Childhood marked by betrayal when relatives took his father''s land","bucket":"predisposing"},{"id":"form-286-4","text":"Neighbours avoid him, which confirms his view","bucket":"perpetuating"},{"id":"form-286-5","text":"Rapid decline in hearing over the past two years, without hearing aids","bucket":"precipitating"},{"id":"form-286-6","text":"Memory and thinking tested as normal","bucket":"protective"},{"id":"form-286-7","text":"Trusts his family doctor of thirty years","bucket":"protective"},{"id":"form-286-8","text":"New, fixed beliefs that a device has been placed in his body","bucket":"distractor"},{"id":"form-286-9","text":"Lives alone after his wife''s death and has stopped meeting friends","bucket":"perpetuating"},{"id":"form-286-10","text":"Lifelong suspicion and grudges, now worse: accuses neighbours of talking about him","bucket":"presenting"},{"id":"form-286-11","text":"Suspicious and quick to take offence all his adult life, according to his brother","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Chhabra, 70, shows paranoid personality disorder that has worsened in later life, rather than a new psychotic illness. His suspicion and grudges are lifelong, and he has no hallucinations or fixed bizarre beliefs; a new belief about a device in his body, the distractor, would suggest a late-onset psychosis and needs separate assessment. Lifelong traits and childhood betrayal (predisposing) underlie his pattern; hearing loss (precipitating) has made it harder to know what people are saying, which feeds suspicion. Missed conversations, isolation after his wife''s death and neighbours'' avoidance (perpetuating) form a vicious cycle. Normal cognition and trust in his family doctor (protective) help. Hearing aids, social contact and a patient, respectful relationship are key; check for depression and keep reviewing for psychosis.","hint":"A 70-year-old whose suspicious nature has worsened since his hearing declined","tags":{"topic":"personality","difficulty":5,"objective":"Untangle lifelong personality traits from new contributors in later life","exams":["md-psychiatry","mcp-entrance"],"module":"lifespan","diagnosis":"Paranoid personality disorder, worsened by hearing loss and isolation"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-287', 'Golu: no, no and no (oppositional defiant disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-287-1","text":"For over a year, loses his temper several times a day, argues with adults and refuses rules","bucket":"presenting"},{"id":"form-287-2","text":"He likes cartoons about superheroes","bucket":"distractor"},{"id":"form-287-3","text":"Started a strict new school with long hours of homework","bucket":"precipitating"},{"id":"form-287-4","text":"Loving parents who want to learn new ways","bucket":"protective"},{"id":"form-287-5","text":"Strong-willed, intense temperament from infancy","bucket":"predisposing"},{"id":"form-287-6","text":"Plays well with children in the colony","bucket":"protective"},{"id":"form-287-7","text":"Deliberately annoys his sister and blames others for his mistakes","bucket":"presenting"},{"id":"form-287-8","text":"Parents give in after long fights, so tantrums pay off","bucket":"perpetuating"},{"id":"form-287-9","text":"Harsh shouting from his grandfather, then sudden treats from his mother","bucket":"perpetuating"},{"id":"form-287-10","text":"Little praise for good behaviour","bucket":"perpetuating"},{"id":"form-287-11","text":"Father works away and parenting has been inconsistent","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Golu, 6, presents with oppositional defiant disorder: a pattern for over six months of angry, irritable mood, arguing and defiance, and annoying or blaming others. An intense temperament and inconsistent parenting while his father works away (predisposing) set the stage; a strict new school (precipitating) added stress. Giving in after fights, mixed harshness and treats, and little praise (perpetuating) teach him that defiance works. Parents who want to learn and good play with other children (protective) make parent training, with consistent rules, praise and calm consequences, the first step. Superhero cartoons are a distractor.","hint":"A 6-year-old who argues with every instruction at home and school","tags":{"topic":"child-adolescent","difficulty":1,"objective":"Sort oppositional defiant disorder in a young child into the 5 Ps","exams":["cuet-pg","ma-semester","mcp-entrance"],"module":"child","diagnosis":"Oppositional defiant disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-288', 'Munni: the letters that jump around (specific learning disorder with impairment in reading)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-288-1","text":"Teacher calls her lazy in front of the class","bucket":"perpetuating"},{"id":"form-288-2","text":"Mother who noticed the gap and asked for help","bucket":"protective"},{"id":"form-288-3","text":"Answers well when questions are read aloud","bucket":"presenting"},{"id":"form-288-4","text":"Avoids reading and so gets less practice","bucket":"perpetuating"},{"id":"form-288-5","text":"Late to learn letter sounds","bucket":"predisposing"},{"id":"form-288-6","text":"Father had trouble reading at school","bucket":"predisposing"},{"id":"form-288-7","text":"Tuitions focus on copying, not reading skills","bucket":"perpetuating"},{"id":"form-288-8","text":"Reads slowly with many errors in both Hindi and English, despite a year of extra help","bucket":"presenting"},{"id":"form-288-9","text":"She likes drawing rangoli at Diwali","bucket":"distractor"},{"id":"form-288-10","text":"Good intelligence and memory for stories","bucket":"protective"},{"id":"form-288-11","text":"Class three exams moved from oral answers to written ones","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Munni, 8, has a specific learning disorder with impairment in reading. Her reading is well below what is expected for her age in both languages despite help, while her understanding when questions are read aloud shows good intelligence. A family history of reading difficulty and slow early letter-sound learning (predisposing) fit dyslexia; the move to written exams (precipitating) exposed the problem. Being called lazy, avoiding reading and tuition that does not teach reading skills (perpetuating) harm her confidence and progress. Her intelligence and her mother''s support (protective) are strengths. A certified assessment can give exam accommodations such as extra time or a reader, along with structured phonics teaching. Rangoli is a distractor.","hint":"An 8-year-old who is bright in class talk but cannot read","tags":{"topic":"child-adolescent","difficulty":1,"objective":"Recognise a specific reading difficulty and its effect on self-esteem","exams":["cuet-pg","ma-semester","mcp-entrance"],"module":"child","diagnosis":"Specific learning disorder with impairment in reading (dyslexia)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-289', 'Bittu: three years old and only five words (language delay from screen time and little talk, not autism)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-289-1","text":"Says about five words at three years","bucket":"presenting"},{"id":"form-289-2","text":"Born at full term with normal hearing on testing","bucket":"predisposing"},{"id":"form-289-3","text":"Moved from his grandparents'' home to a city flat with a caregiver who keeps the TV and phone on all day","bucket":"precipitating"},{"id":"form-289-4","text":"Mixed languages at home with no one consistent","bucket":"perpetuating"},{"id":"form-289-5","text":"Parents keen to change routines","bucket":"protective"},{"id":"form-289-6","text":"Adults speak for him before he tries","bucket":"perpetuating"},{"id":"form-289-7","text":"Points to share interest, brings toys to show, smiles back and plays pretend with his cousin","bucket":"presenting"},{"id":"form-289-8","text":"Both parents work long hours","bucket":"predisposing"},{"id":"form-289-9","text":"Strong social interest and eye contact","bucket":"protective"},{"id":"form-289-10","text":"Lines up toys, does not respond to his name and does not point to show","bucket":"distractor"},{"id":"form-289-11","text":"Hours of screen time with little back-and-forth talk","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Bittu, 3, has a language delay that is most likely linked to low language exposure, not autism. His social communication is good: he points to share, shows toys, smiles back and plays pretend. The distractor of lining up toys, not responding to his name and no pointing would raise concern for autism and does not fit him. Normal hearing and a full-term birth make other causes less likely; busy parents (predisposing) and a move to a caregiver who relies on screens (precipitating) reduced talk with adults. Long screen time, adults speaking for him and inconsistent languages (perpetuating) slow progress. His social interest and willing parents (protective) predict a good response to speech therapy, cutting screen time and daily talk and reading together.","hint":"A 3-year-old who points, plays and smiles but hardly speaks","tags":{"topic":"child-adolescent","difficulty":4,"objective":"Tell a language delay apart from autism using social communication","exams":["md-psychiatry","mcp-entrance","ma-semester"],"module":"child","diagnosis":"Language delay linked to low language exposure, without autism"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-290', 'Aisha: soiled pants and a hard tummy (encopresis with constipation)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-290-1","text":"Parents scold her, thinking she does it on purpose","bucket":"perpetuating"},{"id":"form-290-2","text":"Low-fibre diet, drinks little water","bucket":"predisposing"},{"id":"form-290-3","text":"Close to her mother","bucket":"protective"},{"id":"form-290-4","text":"Holds stool to avoid pain, so the bowel stretches and leaks","bucket":"perpetuating"},{"id":"form-290-5","text":"She lives in Malegaon","bucket":"distractor"},{"id":"form-290-6","text":"Hides soiled clothes","bucket":"perpetuating"},{"id":"form-290-7","text":"Started at a school where the toilets are dirty and she avoids them all day","bucket":"precipitating"},{"id":"form-290-8","text":"Doctor willing to start a bowel plan","bucket":"protective"},{"id":"form-290-9","text":"Painful stool and a small tear at age four","bucket":"predisposing"},{"id":"form-290-10","text":"Hard stools every five or six days that hurt to pass","bucket":"presenting"},{"id":"form-290-11","text":"Soils her underwear most days, smells, and is teased at school","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Aisha, 7, presents with encopresis caused by constipation with overflow: stool builds up, the bowel stretches and liquid stool leaks without her control. A painful episode at four and a low-fibre, low-water diet (predisposing) made her afraid to pass stool; dirty school toilets (precipitating) led her to hold it all day. Withholding, scolding by parents who think it is deliberate and hiding clothes (perpetuating) maintain the cycle and add shame. Her bond with her mother and a doctor ready to help (protective) support a plan of clearing the bowel, regular laxatives, toilet sitting after meals, diet change, praise and a word with the school. Her town is a distractor.","hint":"A 7-year-old who soils her clothes at school","tags":{"topic":"child-adolescent","difficulty":2,"objective":"Recognise soiling caused by constipation with overflow","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"Encopresis with constipation and overflow incontinence"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-291', 'Kavya: the quiet dreamer at the back of the class (ADHD, inattentive presentation, in a girl)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-291-1","text":"Teachers describe her as ''quiet but in her own world'' since class one","bucket":"presenting"},{"id":"form-291-2","text":"Good friendships","bucket":"protective"},{"id":"form-291-3","text":"Daydreams, makes careless mistakes, loses books and does not finish work, at school and at home","bucket":"presenting"},{"id":"form-291-4","text":"Musical and enjoys singing lessons","bucket":"protective"},{"id":"form-291-5","text":"Seen as lazy rather than struggling, so no help is offered","bucket":"perpetuating"},{"id":"form-291-6","text":"Brother diagnosed with ADHD","bucket":"predisposing"},{"id":"form-291-7","text":"Born early at 33 weeks","bucket":"predisposing"},{"id":"form-291-8","text":"Anxiety about marks makes concentration worse","bucket":"perpetuating"},{"id":"form-291-9","text":"Phone in her room at night cuts her sleep","bucket":"perpetuating"},{"id":"form-291-10","text":"Moved to class seven with more subjects and homework","bucket":"precipitating"},{"id":"form-291-11","text":"Inattention that began only after her grandmother''s death last month","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Kavya, 12, has ADHD, predominantly inattentive presentation: inattention in more than one setting since early school years, without much hyperactivity. Girls with this presentation are often missed because they are quiet and not disruptive. A brother with ADHD and preterm birth (predisposing) raise her risk; the bigger workload of class seven (precipitating) made her difficulties obvious. Being seen as lazy, anxiety about marks and poor sleep (perpetuating) worsen her focus. Friendships and singing (protective) protect her self-esteem. The distractor of inattention starting only after a recent bereavement would suggest grief or low mood rather than ADHD, which must begin in childhood. Plan: assessment with school reports, school support, sleep routine and possibly medicine.","hint":"A 12-year-old girl who loses everything and drifts off in class","tags":{"topic":"neurodevelopmental","difficulty":3,"objective":"Recognise inattentive ADHD in a girl, which is often missed","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"child","diagnosis":"Attention-deficit/hyperactivity disorder, predominantly inattentive presentation"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-292', 'Raju: always two steps behind in class (mild intellectual disability)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-292-1","text":"Behind in all subjects, cannot tell time or handle money as well as younger children","bucket":"presenting"},{"id":"form-292-2","text":"Teased and called names by classmates","bucket":"perpetuating"},{"id":"form-292-3","text":"Plays with younger children and is easily led by others","bucket":"presenting"},{"id":"form-292-4","text":"Pushed to keep up with his brother''s tuition","bucket":"perpetuating"},{"id":"form-292-5","text":"Promoted to class six, where the work became abstract","bucket":"precipitating"},{"id":"form-292-6","text":"Cheerful and helpful at home","bucket":"protective"},{"id":"form-292-7","text":"Born after a long, difficult labour with a delayed cry","bucket":"predisposing"},{"id":"form-292-8","text":"Walked and spoke later than his siblings","bucket":"predisposing"},{"id":"form-292-9","text":"Poor marks only in reading, with good maths and good daily living skills","bucket":"distractor"},{"id":"form-292-10","text":"No formal assessment, so no support at school","bucket":"perpetuating"},{"id":"form-292-11","text":"Grandfather who teaches him farm tasks patiently","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Raju, 11, has mild intellectual disability: limits in both intellectual functioning across subjects and in adaptive skills such as telling time and handling money, starting in childhood. A difficult birth with a delayed cry and late milestones (predisposing) point to an early cause; class six work becoming abstract (precipitating) made the gap clear. Pressure to match his brother, teasing and lack of assessment or support (perpetuating) hurt his confidence. His cheerful nature and his grandfather''s patient teaching (protective) are strengths. Poor marks only in reading with good maths and daily skills, the distractor, would point to a specific learning disorder instead. Plan: formal assessment, a disability certificate for support, a suited school plan and building life skills.","hint":"An 11-year-old who struggles with all subjects and daily tasks","tags":{"topic":"neurodevelopmental","difficulty":2,"objective":"Recognise mild intellectual disability with both intellectual and adaptive limits","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"Intellectual disability, mild"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-293', 'Tara: the girl who never asks to be held (reactive attachment disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-293-1","text":"Spent her first five years in an overcrowded orphanage with many changing caregivers","bucket":"predisposing"},{"id":"form-293-2","text":"Goes off happily with strangers and hugs anyone she meets","bucket":"distractor"},{"id":"form-293-3","text":"Adoptive mother feels rejected and has begun to withdraw","bucket":"perpetuating"},{"id":"form-293-4","text":"Frequent changes in nanny","bucket":"perpetuating"},{"id":"form-293-5","text":"Responds a little to a calm, predictable routine","bucket":"protective"},{"id":"form-293-6","text":"Adopted a year ago and moved to a new city","bucket":"precipitating"},{"id":"form-293-7","text":"Little positive emotion, with sudden irritability and sadness even with her caring adoptive parents","bucket":"presenting"},{"id":"form-293-8","text":"Rarely seeks or accepts comfort when hurt or upset","bucket":"presenting"},{"id":"form-293-9","text":"Little individual attention or play in her early years","bucket":"predisposing"},{"id":"form-293-10","text":"Grandparents say she is ''ungrateful''","bucket":"perpetuating"},{"id":"form-293-11","text":"Adoptive parents committed and seeking help","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Tara, 6, shows reactive attachment disorder: a consistent pattern of emotionally withdrawn behaviour towards caregivers, rarely seeking or responding to comfort, with limited positive emotion, after extreme lack of care in early life. Years in an overcrowded orphanage with changing caregivers (predisposing) caused this; adoption and a move (precipitating) placed her with new parents she does not yet trust. Her mother withdrawing, grandparents'' criticism and changing nannies (perpetuating) can deepen the pattern. Committed parents and early response to routine (protective) are hopeful. The distractor, going happily with strangers, describes disinhibited social engagement disorder, a different condition. Plan: attachment-focused parent support, consistent caregivers and patience.","hint":"A 6-year-old adopted from an orphanage a year ago","tags":{"topic":"child-adolescent","difficulty":4,"objective":"Recognise reactive attachment disorder after severe early neglect","exams":["md-psychiatry","mcp-entrance"],"module":"child","diagnosis":"Reactive attachment disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-294', 'Chiku: screaming in the night with no memory in the morning (sleep terrors)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-294-1","text":"Healthy, happy child during the day","bucket":"protective"},{"id":"form-294-2","text":"Parents wake him and shake him during episodes, which makes them longer","bucket":"perpetuating"},{"id":"form-294-3","text":"Cannot be comforted during the episode and remembers nothing the next morning","bucket":"presenting"},{"id":"form-294-4","text":"Father had similar episodes as a child","bucket":"predisposing"},{"id":"form-294-5","text":"He lives in Surat","bucket":"distractor"},{"id":"form-294-6","text":"Sits up screaming, sweating and wide-eyed about an hour after sleep, several nights a week","bucket":"presenting"},{"id":"form-294-7","text":"Deep sleeper","bucket":"predisposing"},{"id":"form-294-8","text":"Late bedtimes because of family TV time","bucket":"perpetuating"},{"id":"form-294-9","text":"Parents keen to follow advice","bucket":"protective"},{"id":"form-294-10","text":"Stopped his afternoon nap when he started school and goes to bed overtired","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Chiku, 5, has sleep terrors: sudden screaming arousals with fear and sweating in the first part of the night, during deep non-dream sleep, with no memory the next day. They are common in young children, often run in families and usually stop with age. A family history and deep sleep (predisposing) fit this; losing his nap and going to bed overtired (precipitating) increased episodes. Waking and shaking him and late bedtimes (perpetuating) prolong them. A happy, healthy daytime and willing parents (protective) mean simple advice works: keep him safe, do not wake him, earlier bedtime and enough sleep. Surat is a distractor.","hint":"A 5-year-old who sits up screaming an hour after falling asleep","tags":{"topic":"sleep","difficulty":1,"objective":"Recognise sleep terrors in a young child","exams":["cuet-pg","ma-semester","mcp-entrance"],"module":"lifespan","diagnosis":"Non-rapid eye movement sleep arousal disorder, sleep terror type"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-295', 'Riya: afraid to swallow since the fish bone (avoidant/restrictive food intake disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-295-1","text":"Panics if asked to eat solid food","bucket":"presenting"},{"id":"form-295-2","text":"Picky eater since toddler years","bucket":"predisposing"},{"id":"form-295-3","text":"Choked on a fish bone at a family dinner three months ago","bucket":"precipitating"},{"id":"form-295-4","text":"Relatives tell scary stories about choking","bucket":"perpetuating"},{"id":"form-295-5","text":"Family gives in and serves only liquids to avoid panic","bucket":"perpetuating"},{"id":"form-295-6","text":"Eats only dal water, milk and soft rice for three months, and has lost four kilos","bucket":"presenting"},{"id":"form-295-7","text":"Avoidance makes the fear stronger","bucket":"perpetuating"},{"id":"form-295-8","text":"Supportive parents","bucket":"protective"},{"id":"form-295-9","text":"Wants to eat her favourite fried snacks again","bucket":"protective"},{"id":"form-295-10","text":"Anxious child who worries about her health","bucket":"predisposing"},{"id":"form-295-11","text":"Fear of weight gain and wanting to be thinner","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Riya, 10, has avoidant/restrictive food intake disorder: restricted eating that causes weight loss, driven by fear of choking after a frightening event, not by concern about body shape or weight. The distractor of fear of weight gain would point to anorexia nervosa and does not fit. An anxious temperament and lifelong picky eating (predisposing) raised her risk; choking on a fish bone (precipitating) began the fear. Family accommodation with only liquids, avoidance strengthening the fear and scary stories (perpetuating) keep it going. Her wish to eat favourite foods and supportive parents (protective) help. Plan: medical check of weight and nutrition, graded exposure to textures with a therapist and family guidance.","hint":"A 10-year-old who eats only liquids and soft food and has lost weight","tags":{"topic":"eating","difficulty":4,"objective":"Tell avoidant/restrictive food intake disorder apart from anorexia nervosa","exams":["md-psychiatry","mcp-entrance"],"module":"more-disorders","diagnosis":"Avoidant/restrictive food intake disorder (fear of choking)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-296', 'Rani: eating mud from the courtyard wall (pica)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-296-1","text":"Recovering from a long bout of diarrhoea that worsened her nutrition","bucket":"precipitating"},{"id":"form-296-2","text":"Old wall paint at home may contain lead","bucket":"perpetuating"},{"id":"form-296-3","text":"Eats mud, chalk and flakes of wall paint most days for four months","bucket":"presenting"},{"id":"form-296-4","text":"Mother also ate clay during her pregnancy","bucket":"predisposing"},{"id":"form-296-5","text":"Low-iron diet and worm infestation in her area","bucket":"predisposing"},{"id":"form-296-6","text":"Pale, tired and short of breath on running","bucket":"presenting"},{"id":"form-296-7","text":"She loves skipping rope","bucket":"distractor"},{"id":"form-296-8","text":"Left alone for long hours while parents work","bucket":"perpetuating"},{"id":"form-296-9","text":"Mother is worried and ready to follow treatment","bucket":"protective"},{"id":"form-296-10","text":"Untreated iron deficiency increases the craving","bucket":"perpetuating"},{"id":"form-296-11","text":"Anganwadi worker who visits regularly","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rani, 6, has pica: persistent eating of non-food substances (mud, chalk and paint) beyond the age when this is normal, with signs of iron deficiency anaemia. Pica is strongly linked with iron deficiency and can expose children to lead poisoning and worms. A low-iron diet, worms and a family pattern of eating clay (predisposing) underlie it; a recent diarrhoeal illness (precipitating) worsened her nutrition. Untreated anaemia, old paint at home and long hours alone (perpetuating) keep her at risk. A worried mother and a visiting anganwadi worker (protective) support a plan of blood tests including lead, iron and deworming treatment, better supervision and nutrition support. Skipping rope is a distractor.","hint":"A 6-year-old who eats mud, chalk and paint flakes","tags":{"topic":"eating","difficulty":2,"objective":"Recognise pica and its medical links","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"Pica, with iron deficiency anaemia"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-297', 'Dev: falling marks, a locked door, then the voices (early-onset schizophrenia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-297-1","text":"Started daily cannabis with older boys six months ago","bucket":"precipitating"},{"id":"form-297-2","text":"A year before that, withdrew from friends, stopped bathing, and marks fell from first class to failing","bucket":"presenting"},{"id":"form-297-3","text":"Cannabis use continues","bucket":"perpetuating"},{"id":"form-297-4","text":"Parents first took him to several healers, delaying treatment","bucket":"perpetuating"},{"id":"form-297-5","text":"School counsellor willing to support a return","bucket":"protective"},{"id":"form-297-6","text":"He goes to a CBSE school in Indore","bucket":"distractor"},{"id":"form-297-7","text":"Close to his elder sister, who brought him","bucket":"protective"},{"id":"form-297-8","text":"No violence and no self-harm","bucket":"protective"},{"id":"form-297-9","text":"Maternal uncle with schizophrenia","bucket":"predisposing"},{"id":"form-297-10","text":"Shy, solitary child with mild speech delay","bucket":"predisposing"},{"id":"form-297-11","text":"Hears voices commenting on him and believes classmates can read his thoughts, for three months","bucket":"presenting"},{"id":"form-297-12","text":"Fights at home about his studies and hygiene","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Dev, 16, presents with early-onset schizophrenia: three months of hallucinations and thought interference after a year-long decline with withdrawal, self-neglect and falling marks. Onset before 18 often begins slowly and is easily mistaken for laziness or teenage moods. A family history of schizophrenia and a shy, solitary childhood with speech delay (predisposing) raised his risk; daily cannabis (precipitating) may have brought on the illness earlier. Delayed treatment through healers, ongoing cannabis use and family conflict (perpetuating) worsen the outlook. His sister''s support, absence of violence or self-harm and a willing school counsellor (protective) are strengths. Plan: careful medical work-up, antipsychotic treatment at low dose with side effect monitoring, cannabis help, family psychoeducation and school support. His school board is a distractor.","hint":"A 16-year-old who withdrew over a year and now hears voices","tags":{"topic":"psychosis","difficulty":5,"objective":"Build a full formulation of early-onset psychosis in an adolescent","exams":["md-psychiatry","mcp-entrance"],"module":"psychosis","diagnosis":"Schizophrenia, early onset"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-298', 'Aryan: stuck on the first sound (childhood-onset fluency disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-298-1","text":"Parents finish his sentences for him","bucket":"perpetuating"},{"id":"form-298-2","text":"Classmates laughed when he got stuck during a school assembly speech","bucket":"precipitating"},{"id":"form-298-3","text":"Speaks fluently when singing","bucket":"protective"},{"id":"form-298-4","text":"Friends who do not tease him","bucket":"protective"},{"id":"form-298-5","text":"Sensitive, anxious child","bucket":"predisposing"},{"id":"form-298-6","text":"Teacher hurries him","bucket":"perpetuating"},{"id":"form-298-7","text":"Father stuttered as a child","bucket":"predisposing"},{"id":"form-298-8","text":"Now refuses to read aloud or answer questions in class","bucket":"presenting"},{"id":"form-298-9","text":"He goes to a school in Ranchi","bucket":"distractor"},{"id":"form-298-10","text":"Avoids speaking, which builds fear","bucket":"perpetuating"},{"id":"form-298-11","text":"Repeats and blocks on first sounds of words since age four","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Aryan, 9, has childhood-onset fluency disorder (stuttering): repetitions and blocks on sounds since early childhood, now with avoidance of speaking. A father who stuttered and an anxious temperament (predisposing) fit the strong family pattern; laughter during an assembly speech (precipitating) made speaking frightening. Avoidance, parents finishing his sentences and a hurried teacher (perpetuating) increase fear and stuttering. Fluency while singing and supportive friends (protective) help. Plan: speech therapy, guidance for parents and teachers to slow down and wait, and work on confidence. Ranchi is a distractor.","hint":"A 9-year-old who stutters and now refuses to answer in class","tags":{"topic":"child-adolescent","difficulty":1,"objective":"Sort stuttering and its social effects into the 5 Ps","exams":["cuet-pg","ma-semester","mcp-entrance"],"module":"child","diagnosis":"Childhood-onset fluency disorder (stuttering)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-299', 'Yash: angry every single day (disruptive mood dysregulation disorder, not bipolar disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-299-1","text":"Parents in a tense marriage with frequent fights","bucket":"predisposing"},{"id":"form-299-2","text":"Moved to a new school after being asked to leave the old one","bucket":"precipitating"},{"id":"form-299-3","text":"Poor sleep from late phone use","bucket":"perpetuating"},{"id":"form-299-4","text":"Anxious, sensitive temperament from early childhood","bucket":"predisposing"},{"id":"form-299-5","text":"Grandmother whom he trusts","bucket":"protective"},{"id":"form-299-6","text":"Severe temper outbursts four or five times a week, at home and school, for two years","bucket":"presenting"},{"id":"form-299-7","text":"Irritable and angry most of the day between outbursts","bucket":"presenting"},{"id":"form-299-8","text":"Classmates avoid him, so he feels rejected","bucket":"perpetuating"},{"id":"form-299-9","text":"Parents alternate between shouting and giving in","bucket":"perpetuating"},{"id":"form-299-10","text":"Good at chess and calm when playing","bucket":"protective"},{"id":"form-299-11","text":"Clear episodes of several days with elated mood, little sleep and grand ideas","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Yash, 10, has disruptive mood dysregulation disorder: severe, frequent temper outbursts with persistently irritable mood between them, in more than one setting, for over a year, starting before ten. It is not bipolar disorder, which needs distinct episodes of elevated mood, reduced need for sleep and grandiosity, as in the distractor. An anxious, sensitive temperament and a tense home (predisposing) shaped his irritability; leaving his old school (precipitating) added stress. Inconsistent parenting, peer rejection and poor sleep (perpetuating) maintain it. Chess and his grandmother (protective) are anchors. Plan: parent training, CBT for anger and irritability, school support and treatment of any anxiety.","hint":"A 10-year-old with daily explosions and constant irritability for two years","tags":{"topic":"child-adolescent","difficulty":4,"objective":"Tell chronic irritability in a child apart from bipolar disorder","exams":["md-psychiatry","mcp-entrance"],"module":"child","diagnosis":"Disruptive mood dysregulation disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-300', 'Neha: the photos and the threats from a stranger online (sextortion of a 15-year-old)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-300-1","text":"Not eating or sleeping, panicky when her phone buzzes, and has said she ''wants to disappear''","bucket":"presenting"},{"id":"form-300-2","text":"Lonely after moving cities, with few friends","bucket":"predisposing"},{"id":"form-300-3","text":"Told her school counsellor","bucket":"protective"},{"id":"form-300-4","text":"Believes the shame is entirely hers","bucket":"perpetuating"},{"id":"form-300-5","text":"Keeps paying from her pocket money","bucket":"perpetuating"},{"id":"form-300-6","text":"Her favourite subject is biology","bucket":"distractor"},{"id":"form-300-7","text":"Shared a photo with an online ''friend'' who then began threats a week ago","bucket":"precipitating"},{"id":"form-300-8","text":"Low self-esteem and wish to be liked","bucket":"predisposing"},{"id":"form-300-9","text":"Terrified her parents will find out, so she hides everything","bucket":"perpetuating"},{"id":"form-300-10","text":"Parents, once told, respond with support rather than anger","bucket":"protective"},{"id":"form-300-11","text":"A man she met in a game chat is demanding more photos and money, threatening to share images","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Neha, 15, is a victim of online sexual exploitation and sextortion, now with an acute stress reaction, depressive symptoms and possible suicidal thoughts. The responsibility lies entirely with the adult who exploited her. Loneliness after a move and low self-esteem (predisposing) increased her vulnerability to grooming; sharing a photo with an online ''friend'' who then threatened her (precipitating) started the crisis. Secrecy, continued payments and self-blame (perpetuating) deepen her distress and danger. Telling the counsellor and parents who respond with support (protective) are vital. Plan: assess suicide risk immediately, do not pay, keep evidence, report under child protection law through the police and the national cybercrime helpline, and give trauma-focused support. Biology is a distractor.","hint":"A 15-year-old who has stopped eating and sleeping after a man online threatened her","tags":{"topic":"trauma","difficulty":5,"objective":"Formulate online sexual exploitation in an adolescent, with safety and legal duties","exams":["md-psychiatry","mcp-entrance","ma-semester"],"module":"trauma","diagnosis":"Acute stress reaction with depressive symptoms after online sexual exploitation; child protection concern"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-301', 'Arya: two years old, no words and no pointing (early signs of autism)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-301-1","text":"Normal hearing test","bucket":"protective"},{"id":"form-301-2","text":"Many hours on the phone screen to keep her calm","bucket":"perpetuating"},{"id":"form-301-3","text":"Grandmother noticed she did not wave bye-bye like other children at a family function","bucket":"precipitating"},{"id":"form-301-4","text":"No early intervention yet","bucket":"perpetuating"},{"id":"form-301-5","text":"Lines up blocks for long periods and gets very upset if they are moved","bucket":"presenting"},{"id":"form-301-6","text":"Parents ready to start therapy early","bucket":"protective"},{"id":"form-301-7","text":"Born preterm at 32 weeks","bucket":"predisposing"},{"id":"form-301-8","text":"She was born in Pune","bucket":"distractor"},{"id":"form-301-9","text":"Family told ''girls talk late, wait and see''","bucket":"perpetuating"},{"id":"form-301-10","text":"Older cousin diagnosed with autism","bucket":"predisposing"},{"id":"form-301-11","text":"No words, no pointing to share interest and does not turn when her name is called","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Arya, 2, shows early signs of autism: no pointing to share interest, not responding to her name, no words and repetitive play with distress at change. Early recognition matters because therapy started early improves outcomes. A cousin with autism and preterm birth (predisposing) raise her risk; her grandmother''s observation at a family function (precipitating) brought her for assessment. Being told to ''wait and see'', heavy screen use and no early intervention (perpetuating) delay help. A normal hearing test and parents ready to act (protective) support a plan of full developmental assessment, early intervention with parent-led play and communication therapy, and reduced screen time. Her birthplace is a distractor.","hint":"A 2-year-old who does not look when called and lines up blocks","tags":{"topic":"neurodevelopmental","difficulty":2,"objective":"Recognise early signs of autism in a toddler","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"Autism spectrum disorder, suspected (early signs at two years)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-302', 'Mohit: stealing and running away since his father died (grief behind adolescent conduct problems)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-302-1","text":"Good school record until this year","bucket":"protective"},{"id":"form-302-2","text":"Cricket coach who still checks on him","bucket":"protective"},{"id":"form-302-3","text":"Close bond with his father, who taught him cricket","bucket":"predisposing"},{"id":"form-302-4","text":"Mother now works double shifts and is rarely home","bucket":"perpetuating"},{"id":"form-302-5","text":"Father died suddenly in a road accident eight months ago","bucket":"precipitating"},{"id":"form-302-6","text":"Family does not mention his father to ''protect'' him","bucket":"perpetuating"},{"id":"form-302-7","text":"Joined older boys who steal","bucket":"perpetuating"},{"id":"form-302-8","text":"Irritable, sleeps poorly and refuses to talk about his father","bucket":"presenting"},{"id":"form-302-9","text":"Stealing from shops, staying out at night and skipping school for eight months","bucket":"presenting"},{"id":"form-302-10","text":"Cruelty to animals and fire-setting since age seven","bucket":"distractor"},{"id":"form-302-11","text":"No behaviour problems before age fourteen","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mohit, 15, has adolescent-onset conduct problems that appear to be driven by unresolved grief and low mood after his father''s sudden death. The behaviour began recently, after the loss, in a boy with no earlier problems; the distractor of cruelty and fire-setting from age seven would suggest childhood-onset conduct disorder, which has a worse outlook and does not fit. A close bond with his father (predisposing) made the loss devastating; the accident (precipitating) started the change. Silence about his father, a delinquent peer group and his mother''s long absences (perpetuating) maintain it. His good earlier record and his cricket coach (protective) offer a way back. Plan: grief work, screening for depression and risk, family sessions, more adult supervision and re-engaging him with cricket.","hint":"A 15-year-old who began stealing and skipping school eight months ago","tags":{"topic":"child-adolescent","difficulty":4,"objective":"Tell adolescent-onset conduct problems driven by grief apart from long-standing conduct disorder","exams":["md-psychiatry","mcp-entrance"],"module":"child","diagnosis":"Adolescent-onset conduct problems in the context of unresolved grief and depressive symptoms"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-303', 'Tanmay: new city, new school, new tummy aches (adjustment disorder in a child)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-303-1","text":"Family moved from Lucknow to Bengaluru for his father''s job","bucket":"precipitating"},{"id":"form-303-2","text":"Very close to his grandparents","bucket":"predisposing"},{"id":"form-303-3","text":"Misses video calls with grandparents because of timing","bucket":"perpetuating"},{"id":"form-303-4","text":"He is good at maths","bucket":"distractor"},{"id":"form-303-5","text":"Says he has no friends and wants to go back to Lucknow","bucket":"presenting"},{"id":"form-303-6","text":"Doctor found no medical cause","bucket":"protective"},{"id":"form-303-7","text":"Does not understand Kannada or the new school''s routines","bucket":"perpetuating"},{"id":"form-303-8","text":"Kind class teacher who wants to help him settle","bucket":"protective"},{"id":"form-303-9","text":"Stomach aches and crying every school morning for six weeks","bucket":"presenting"},{"id":"form-303-10","text":"Allowed to stay home on bad mornings","bucket":"perpetuating"},{"id":"form-303-11","text":"Shy child who takes time to warm up","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Tanmay, 8, has an adjustment disorder with anxiety: stomach aches and distress that began within weeks of a big life change and are more than expected. A shy temperament and a close bond with grandparents he left behind (predisposing) increased his vulnerability; the move to a new city (precipitating) brought loss and change. Language and routine barriers, staying home on bad mornings and missed calls (perpetuating) keep him anxious. A normal medical check and a kind teacher (protective) support a plan of a buddy at school, a regular call schedule with his grandparents, a calm morning routine and steady school attendance. Maths is a distractor.","hint":"An 8-year-old with stomach aches every morning since moving to Bengaluru","tags":{"topic":"child-adolescent","difficulty":1,"objective":"Sort a child''s adjustment reaction into the 5 Ps","exams":["cuet-pg","ma-semester","mcp-entrance"],"module":"child","diagnosis":"Adjustment disorder with anxiety"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-304', 'Simran: stomach pain that no test explains (functional abdominal pain in a child)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-304-1","text":"Pain began after a stomach infection last year, around the time her parents began fighting often","bucket":"precipitating"},{"id":"form-304-2","text":"Blood in the stool and weight loss","bucket":"distractor"},{"id":"form-304-3","text":"Good friends and enjoys dance","bucket":"protective"},{"id":"form-304-4","text":"Anxious, perfectionist child","bucket":"predisposing"},{"id":"form-304-5","text":"Mother has irritable bowel syndrome","bucket":"predisposing"},{"id":"form-304-6","text":"Repeated visits to different doctors and tests keep the family focused on finding a cause","bucket":"perpetuating"},{"id":"form-304-7","text":"Pain around the belly button most days for a year, often before school","bucket":"presenting"},{"id":"form-304-8","text":"Paediatrician willing to explain the condition clearly","bucket":"protective"},{"id":"form-304-9","text":"Missed school days increase her worry about falling behind","bucket":"perpetuating"},{"id":"form-304-10","text":"Mother checks on her pain every hour","bucket":"perpetuating"},{"id":"form-304-11","text":"Normal blood tests, stool tests and scan; growing well","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Simran, 10, has functional abdominal pain: real, recurrent pain without a disease cause on tests, with normal growth. The gut and brain are closely linked, so stress and worry can make the gut more sensitive. A mother with irritable bowel syndrome and an anxious, perfectionist temperament (predisposing) raise her risk; a stomach infection and her parents'' fighting (precipitating) came together when the pain began. Repeated tests, missed school and hourly checking (perpetuating) keep attention on pain. Friends, dance and a willing paediatrician (protective) support a plan of clear explanation, return to school, less checking and CBT skills for pain and worry. Blood in the stool and weight loss would be warning signs of disease and are distractors here.","hint":"A 10-year-old with tummy pain for a year and normal tests","tags":{"topic":"somatic","difficulty":3,"objective":"Formulate functional abdominal pain with the gut and stress linked","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"child","diagnosis":"Functional abdominal pain in childhood"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-305', 'Aaru: baby talk again since his sister arrived (regression in a toddler after a new baby)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-305-1","text":"Wetting his pants in the day, baby talk and asking for a bottle since his sister was born two months ago","bucket":"presenting"},{"id":"form-305-2","text":"Only child for four years","bucket":"predisposing"},{"id":"form-305-3","text":"Birth of his baby sister","bucket":"precipitating"},{"id":"form-305-4","text":"Gets more attention for wetting than for being dry","bucket":"perpetuating"},{"id":"form-305-5","text":"Very attached to his mother","bucket":"predisposing"},{"id":"form-305-6","text":"Loving parents","bucket":"protective"},{"id":"form-305-7","text":"Relatives fuss over the baby and tell him to ''be a big boy''","bucket":"perpetuating"},{"id":"form-305-8","text":"He likes toy trains","bucket":"distractor"},{"id":"form-305-9","text":"Grandfather who spends special time with him","bucket":"protective"},{"id":"form-305-10","text":"Clingy and has tantrums when his mother feeds the baby","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Aaru, 4, shows a normal regression after his sister''s birth: daytime wetting, baby talk and clinginess are common when a young child feels displaced. Being an only child for four years and very attached to his mother (predisposing) made the change big; the baby''s arrival (precipitating) set it off. Relatives fussing over the baby, pressure to ''be a big boy'' and extra attention for wetting (perpetuating) can prolong it. Loving parents and special time with his grandfather (protective) help. Advice: daily one-to-one time with each parent, praise for ''big boy'' moments without shaming accidents, and involving him in caring for the baby. Toy trains are a distractor.","hint":"A 4-year-old who has started wetting and wanting a bottle again","tags":{"topic":"child-adolescent","difficulty":1,"objective":"Recognise a normal regression after the birth of a sibling","exams":["cuet-pg","ma-semester","mcp-entrance"],"module":"lifespan","diagnosis":"Normal developmental regression after a sibling''s birth (adjustment reaction)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-306', 'Zain: angry since the new fit medicine (behaviour change from levetiracetam, not oppositional defiant disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-306-1","text":"Hitting his brother, shouting and crying easily for six weeks","bucket":"presenting"},{"id":"form-306-2","text":"Switched from another seizure medicine to levetiracetam two months ago","bucket":"precipitating"},{"id":"form-306-3","text":"School has sent notes home, adding stress","bucket":"perpetuating"},{"id":"form-306-4","text":"Was a calm, affectionate child before","bucket":"protective"},{"id":"form-306-5","text":"Dose was recently increased","bucket":"perpetuating"},{"id":"form-306-6","text":"Mild learning difficulties","bucket":"predisposing"},{"id":"form-306-7","text":"Epilepsy since age five","bucket":"predisposing"},{"id":"form-306-8","text":"Family thinks he has become ''spoilt'' and punishes him","bucket":"perpetuating"},{"id":"form-306-9","text":"Neurologist willing to review the medicine","bucket":"protective"},{"id":"form-306-10","text":"Seizures are now well controlled","bucket":"presenting"},{"id":"form-306-11","text":"Defiance and arguing every day since age four, long before any medicine","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Zain, 9, shows irritability and aggression that began soon after starting levetiracetam, a seizure medicine known to cause behaviour and mood changes in some children. The clear timing and his calm personality before point to a medicine effect, not oppositional defiant disorder; the distractor of daily defiance since four, before any medicine, does not fit. Epilepsy and mild learning difficulties (predisposing) raise his vulnerability; the switch to levetiracetam (precipitating) and a recent dose increase came just before. Punishment, school notes and the higher dose (perpetuating) maintain distress. His earlier temperament and a willing neurologist (protective) support a plan to review the medicine with the neurologist, explain to the family and school, and support his behaviour in the meantime.","hint":"A 9-year-old with epilepsy who became aggressive after a medicine change","tags":{"topic":"child-adolescent","difficulty":4,"objective":"Recognise a medicine side effect behind new behaviour problems","exams":["md-psychiatry","mcp-entrance"],"module":"brain","diagnosis":"Medicine-induced irritability and aggression from levetiracetam in a child with epilepsy"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-307', 'Sam: alone at lunch and low for months (depression in an autistic teenager)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-307-1","text":"Ongoing exclusion at lunch","bucket":"perpetuating"},{"id":"form-307-2","text":"Mother has had depression","bucket":"predisposing"},{"id":"form-307-3","text":"Difficulty putting feelings into words, so the change is seen as ''more autism''","bucket":"perpetuating"},{"id":"form-307-4","text":"Routine broken by the new timetable","bucket":"perpetuating"},{"id":"form-307-5","text":"Lost interest in his lifelong special interest in trains, sleeps poorly and has stopped eating his usual foods for three months","bucket":"presenting"},{"id":"form-307-6","text":"School special educator he trusts","bucket":"protective"},{"id":"form-307-7","text":"Father who knows his signs well","bucket":"protective"},{"id":"form-307-8","text":"The family lives in Thane","bucket":"distractor"},{"id":"form-307-9","text":"More meltdowns and has said ''I am a mistake''","bucket":"presenting"},{"id":"form-307-10","text":"Excluded from a group project and laughed at by classmates after a misunderstanding","bucket":"precipitating"},{"id":"form-307-11","text":"Autism diagnosed at age six","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sam, 15, has a major depressive episode on top of autism. Depression is common in autistic teenagers, and it can show as loss of special interests, changes in eating and sleep, more meltdowns and self-critical statements rather than clear talk of sadness. Autism and a mother with depression (predisposing) raise his risk; exclusion and being laughed at (precipitating) triggered the episode. Difficulty naming feelings, so changes are put down to autism, ongoing exclusion and a broken routine (perpetuating) maintain it. His father and special educator (protective) are key. Plan: careful risk assessment, adapted CBT with visual tools, addressing exclusion with the school, restoring routines and considering medicine. Thane is a distractor.","hint":"A 15-year-old with known autism who has stopped talking about his trains","tags":{"topic":"neurodevelopmental","difficulty":5,"objective":"Recognise depression in an autistic adolescent, where signs can look different","exams":["md-psychiatry","mcp-entrance"],"module":"child","diagnosis":"Major depressive episode in an adolescent with autism spectrum disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-308', 'Ravi: the farewell party and the bottle (alcohol use in a sixteen-year-old)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-308-1","text":"Brought to emergency drunk and vomiting after a school farewell party","bucket":"presenting"},{"id":"form-308-2","text":"Joined a group of older students who drink in a nearby farmhouse","bucket":"precipitating"},{"id":"form-308-3","text":"Believes ''everyone drinks, it is cool''","bucket":"perpetuating"},{"id":"form-308-4","text":"Parents unaware of his weekends","bucket":"perpetuating"},{"id":"form-308-5","text":"Uncle drinks heavily and offers alcohol at family events","bucket":"predisposing"},{"id":"form-308-6","text":"He studies in Lucknow","bucket":"distractor"},{"id":"form-308-7","text":"Easy access through older friends","bucket":"perpetuating"},{"id":"form-308-8","text":"Plays football for the district team","bucket":"protective"},{"id":"form-308-9","text":"Frightened by the emergency visit","bucket":"protective"},{"id":"form-308-10","text":"Impulsive and seeks excitement","bucket":"predisposing"},{"id":"form-308-11","text":"Has been drinking with friends most weekends for three months","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ravi, 16, shows a hazardous pattern of alcohol use without dependence, which is an important moment for early help, because early drinking raises the risk of later problems. An uncle who drinks and offers alcohol and an impulsive temperament (predisposing) raise his risk; a new group of older drinking friends (precipitating) started his use. Easy access, beliefs that drinking is normal and cool, and little parental awareness (perpetuating) keep it going. His football and his fright after emergency (protective) are strong levers for a brief motivational intervention, clear family rules and more supervision. His city is a distractor.","hint":"A 16-year-old found drunk and vomiting after a school party","tags":{"topic":"substance","difficulty":2,"objective":"Formulate early adolescent alcohol use and the chance to intervene early","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"substance","diagnosis":"Alcohol use in an adolescent (hazardous pattern, no dependence)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-309', 'Gauri: cooking, cleaning and watching over her mother (a young carer under strain)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-309-1","text":"Cooks, cleans and reminds her mother to take her tablets","bucket":"presenting"},{"id":"form-309-2","text":"Mature, responsible child","bucket":"predisposing"},{"id":"form-309-3","text":"No one at school knows about her home life","bucket":"perpetuating"},{"id":"form-309-4","text":"No time for friends or play","bucket":"perpetuating"},{"id":"form-309-5","text":"Worries that if she tells anyone, her mother will be taken away","bucket":"perpetuating"},{"id":"form-309-6","text":"A neighbour aunty who sometimes helps","bucket":"protective"},{"id":"form-309-7","text":"She studies in a government school in Kanpur","bucket":"distractor"},{"id":"form-309-8","text":"Anxious, tired and falling asleep in class for six months","bucket":"presenting"},{"id":"form-309-9","text":"Mother loves her and is stable on treatment","bucket":"protective"},{"id":"form-309-10","text":"Mother has schizophrenia; father works in the Gulf","bucket":"predisposing"},{"id":"form-309-11","text":"Her grandmother, who used to help, moved back to the village","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Gauri, 11, is a young carer for her mother with schizophrenia, now with an adjustment disorder with anxiety. Children caring for ill parents often carry adult duties in secret, at a cost to school and childhood. Her mother''s illness, an absent father and her responsible nature (predisposing) set the stage; her grandmother leaving (precipitating) put all the care on her. Secrecy at school, fear that her mother will be taken away and no time to play (perpetuating) maintain her stress. Her mother''s love and stability and a helpful neighbour (protective) are strengths. Plan: involve the mother''s treating team, arrange adult support at home, inform the school with consent, and give Gauri age-appropriate information and time to be a child.","hint":"An 11-year-old who looks after her mother with schizophrenia","tags":{"topic":"child-adolescent","difficulty":3,"objective":"Formulate the stress of a child caring for a parent with mental illness","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"child","diagnosis":"Adjustment disorder with anxiety in a young carer"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-310', 'Naina: told to ''act like a boy'' since childhood (gender dysphoria with depression in an adolescent)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-310-1","text":"She has a pet parrot","bucket":"distractor"},{"id":"form-310-2","text":"Father found her wearing her sister''s clothes and burned them","bucket":"precipitating"},{"id":"form-310-3","text":"Low mood, self-harm and stopped attending school for two months","bucket":"presenting"},{"id":"form-310-4","text":"Elder sister who supports her","bucket":"protective"},{"id":"form-310-5","text":"Bullying by classmates","bucket":"perpetuating"},{"id":"form-310-6","text":"No safe adult to talk to","bucket":"perpetuating"},{"id":"form-310-7","text":"Online peer support group for transgender youth","bucket":"protective"},{"id":"form-310-8","text":"Gender-diverse play and preferences from age four","bucket":"predisposing"},{"id":"form-310-9","text":"Family rejection and pressure to ''act like a boy''","bucket":"perpetuating"},{"id":"form-310-10","text":"Strong, lasting identification as a girl since early childhood, with deep distress about puberty changes","bucket":"presenting"},{"id":"form-310-11","text":"Bullied in school for being ''girly''","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Naina, 16, who was assigned male at birth and identifies as a girl, has gender dysphoria with a depressive episode. Being transgender is not a mental illness; the distress comes from the mismatch with her body and especially from rejection and bullying. A lifelong gender-diverse identity and school bullying (predisposing) underlie her distress; her father burning the clothes (precipitating) triggered the crisis. Family rejection, bullying and having no safe adult (perpetuating) drive the depression and self-harm. Her sister and a peer support group (protective) are lifelines. Plan: assess and manage suicide risk, treat the depression, support the family with education, work with the school on bullying and use her chosen name, Naina. The parrot is a distractor.","hint":"A 16-year-old assigned male at birth who identifies as a girl and has stopped going to school","tags":{"topic":"gender","difficulty":4,"objective":"Formulate distress in a gender-diverse adolescent without treating identity as the problem","exams":["md-psychiatry","mcp-entrance"],"module":"more-disorders","diagnosis":"Gender dysphoria in adolescence with a depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-311', 'Pappu: rocking and hand-flapping when the house is noisy (stereotypic movements in intellectual disability)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-311-1","text":"Calms with music and swinging","bucket":"protective"},{"id":"form-311-2","text":"He lives in Thrissur","bucket":"distractor"},{"id":"form-311-3","text":"Special school teacher who knows him well","bucket":"protective"},{"id":"form-311-4","text":"Family scolds him, which increases distress","bucket":"perpetuating"},{"id":"form-311-5","text":"Moderate intellectual disability after a brain infection in infancy","bucket":"predisposing"},{"id":"form-311-6","text":"Limited speech","bucket":"predisposing"},{"id":"form-311-7","text":"Small sores on his chin from banging","bucket":"presenting"},{"id":"form-311-8","text":"Noise and crowds overwhelm him and he cannot say so","bucket":"perpetuating"},{"id":"form-311-9","text":"Rocks, flaps his hands and bangs his chin for long periods, more in the last three months","bucket":"presenting"},{"id":"form-311-10","text":"Few structured activities during the day","bucket":"perpetuating"},{"id":"form-311-11","text":"A new family with three young children moved in next door, and the house became much noisier","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Pappu, 12, has stereotypic movements (rocking, flapping and chin-banging) with moderate intellectual disability, now causing injury. Such movements often soothe or help a person cope when overwhelmed, bored or unable to communicate. Intellectual disability after an early brain infection and limited speech (predisposing) underlie them; a much noisier home (precipitating) increased his distress. Overwhelming noise he cannot express, scolding and little daily structure (perpetuating) maintain the behaviour. Music, swinging and a teacher who knows him (protective) give ideas for a plan: protect his chin, give a quiet space, teach a simple way to signal distress, add structured activities and check for pain or illness.","hint":"A 12-year-old with moderate intellectual disability whose rocking has increased","tags":{"topic":"neurodevelopmental","difficulty":3,"objective":"Formulate repetitive movements and what triggers them","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"child","diagnosis":"Stereotypic movement disorder in a child with moderate intellectual disability"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-312', 'Prachi: the Kota hostel and the ranking list on the wall (exam stress and perfectionism)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-312-1","text":"Close friend in the hostel","bucket":"protective"},{"id":"form-312-2","text":"Enjoys sketching, which calms her","bucket":"protective"},{"id":"form-312-3","text":"Perfectionist since primary school","bucket":"predisposing"},{"id":"form-312-4","text":"Cannot sleep before weekly tests, has panic attacks in the exam hall and cries after every result","bucket":"presenting"},{"id":"form-312-5","text":"Skips meals and sleep to study more","bucket":"perpetuating"},{"id":"form-312-6","text":"Compares herself with classmates on social media","bucket":"perpetuating"},{"id":"form-312-7","text":"Her coaching institute is near the Chambal river","bucket":"distractor"},{"id":"form-312-8","text":"Dropped from the top batch to a lower batch after a test","bucket":"precipitating"},{"id":"form-312-9","text":"Studies fourteen hours a day and feels she is never doing enough","bucket":"presenting"},{"id":"form-312-10","text":"Parents took a loan to fund her coaching","bucket":"predisposing"},{"id":"form-312-11","text":"Coaching centre displays rankings publicly","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Prachi, 17, has anxiety and insomnia under intense academic pressure, best seen as an adjustment disorder with anxiety driven by perfectionism. A family loan for coaching and long-standing perfectionism (predisposing) make every mark feel like everything; dropping to a lower batch (precipitating) hit her self-worth. Public rankings, giving up sleep and food, and comparison on social media (perpetuating) feed anxiety and lower performance. Her friend and sketching (protective) help. Because exam pressure in coaching hubs can lead to hopelessness, ask clearly about suicidal thoughts. Plan: sleep and study routines, CBT for perfectionism and panic, and a conversation with her parents about expectations. The river is a distractor.","hint":"A 17-year-old medical entrance aspirant with insomnia and panic before tests","tags":{"topic":"anxiety","difficulty":2,"objective":"Formulate performance anxiety driven by perfectionism and pressure","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"anxiety","diagnosis":"Anxiety with perfectionism and insomnia under academic pressure (adjustment disorder with anxiety)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-313', 'Isha: restless, sweaty and losing weight (an overactive thyroid mistaken for ADHD)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-313-1","text":"Teachers and a tutor suggested ADHD and the family started looking for a stimulant","bucket":"perpetuating"},{"id":"form-313-2","text":"Inattention and restlessness noted in school reports since age six","bucket":"distractor"},{"id":"form-313-3","text":"Mother has thyroid disease","bucket":"predisposing"},{"id":"form-313-4","text":"Paediatrician who listened to the history","bucket":"protective"},{"id":"form-313-5","text":"Weight loss despite eating more, feeling hot, sweating and a fine tremor","bucket":"presenting"},{"id":"form-313-6","text":"Poor sleep from a racing heart","bucket":"perpetuating"},{"id":"form-313-7","text":"Symptoms began a few months after a viral illness","bucket":"precipitating"},{"id":"form-313-8","text":"Restless, fidgety and unable to concentrate for four months, with falling marks","bucket":"presenting"},{"id":"form-313-9","text":"Good concentration and marks until this year","bucket":"predisposing"},{"id":"form-313-10","text":"Supportive parents","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Isha, 14, has an overactive thyroid that is causing restlessness and poor concentration, not ADHD. ADHD begins in childhood, as in the distractor of school reports from age six, while her problems are new, with weight loss, heat intolerance, sweating and tremor. A mother with thyroid disease (predisposing) raises her risk; symptoms followed a viral illness (precipitating). The ADHD suggestion, which could lead to a stimulant that worsens a racing heart, and poor sleep (perpetuating) delay correct care. A listening paediatrician and supportive parents (protective) help. Plan: thyroid blood tests, treatment by an endocrinologist, and recheck attention once her thyroid is controlled.","hint":"A 14-year-old girl newly restless and unable to concentrate","tags":{"topic":"child-adolescent","difficulty":4,"objective":"Look for a medical cause when attention problems start suddenly","exams":["md-psychiatry","mcp-entrance"],"module":"child","diagnosis":"Hyperthyroidism (likely Graves'' disease) presenting with restlessness and poor concentration"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-314', 'Bablu: three years old, small, silent and always hungry (neglect and faltering growth)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-314-1","text":"Mother''s drinking has increased","bucket":"perpetuating"},{"id":"form-314-2","text":"No regular meals or routine","bucket":"perpetuating"},{"id":"form-314-3","text":"A genetic condition with normal feeding, normal care and no weight gain in hospital","bucket":"distractor"},{"id":"form-314-4","text":"Mother has untreated depression and alcohol use","bucket":"predisposing"},{"id":"form-314-5","text":"Grabs and hides food, rarely smiles and does not look to adults for comfort","bucket":"presenting"},{"id":"form-314-6","text":"Weight well below the expected range for his age, with delayed speech and walking","bucket":"presenting"},{"id":"form-314-7","text":"Grandmother willing to help if supported","bucket":"protective"},{"id":"form-314-8","text":"Missed all vaccinations and growth checks","bucket":"perpetuating"},{"id":"form-314-9","text":"Family evicted from their room six months ago and now staying with different relatives","bucket":"precipitating"},{"id":"form-314-10","text":"Gains weight quickly in hospital with regular meals","bucket":"protective"},{"id":"form-314-11","text":"Father absent; mother is very young","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Bablu, 3, has faltering growth due to neglect, with developmental delay and food-seeking behaviour. His quick weight gain in hospital with regular meals points to inadequate care rather than a disease; a genetic condition with good care and no weight gain in hospital, the distractor, would suggest a medical cause. His mother''s untreated depression and alcohol use and an absent father (predisposing) underlie the neglect; eviction and moving between relatives (precipitating) worsened it. No routine, missed health checks and rising drinking (perpetuating) keep him at risk. Rapid catch-up and a willing grandmother (protective) give hope. Plan: child protection referral, nutrition and development support, catch-up vaccinations, and treatment for his mother.","hint":"A 3-year-old far below expected weight who grabs food from others","tags":{"topic":"safeguarding","difficulty":5,"objective":"Formulate faltering growth from neglect, with child protection steps","exams":["md-psychiatry","mcp-entrance"],"module":"child","diagnosis":"Faltering growth (failure to thrive) due to neglect, with developmental delay"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-315', 'Aryan: always dropping things and last in races (developmental coordination disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-315-1","text":"Clumsy since early childhood, with poor handwriting and trouble buttoning clothes and catching a ball","bucket":"presenting"},{"id":"form-315-2","text":"Teachers call his writing ''careless''","bucket":"perpetuating"},{"id":"form-315-3","text":"Late to walk at eighteen months","bucket":"predisposing"},{"id":"form-315-4","text":"Avoids practice, so skills do not improve","bucket":"perpetuating"},{"id":"form-315-5","text":"Normal motor skills that worsened only in the last month along with headaches","bucket":"distractor"},{"id":"form-315-6","text":"Classmates choose him last for teams","bucket":"perpetuating"},{"id":"form-315-7","text":"Born preterm","bucket":"predisposing"},{"id":"form-315-8","text":"Avoids games period and says he is ''useless at sports''","bucket":"presenting"},{"id":"form-315-9","text":"Good intelligence and enjoys reading","bucket":"protective"},{"id":"form-315-10","text":"Parents willing to start therapy","bucket":"protective"},{"id":"form-315-11","text":"New school with daily physical education and handwriting marks","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Aryan, 8, has developmental coordination disorder: motor skills well below his age since early childhood, affecting handwriting, dressing and play, not explained by intellectual disability or a neurological illness. Preterm birth and late walking (predisposing) fit this; a new school with daily physical education and handwriting marks (precipitating) made the problem visible. Being chosen last, being called careless and avoiding practice (perpetuating) hurt his confidence and skills. His intelligence, love of reading and willing parents (protective) help. A new loss of motor skills with headaches, the distractor, would need urgent neurological review. Plan: occupational therapy, school adjustments such as extra time and a laptop, and building confidence.","hint":"An 8-year-old who cannot button his shirt or catch a ball","tags":{"topic":"neurodevelopmental","difficulty":2,"objective":"Recognise developmental coordination disorder and its effect on confidence","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"Developmental coordination disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-316', 'Fatima: silent in her new English-medium class (social anxiety in a young adolescent)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-316-1","text":"Freezes, blushes and avoids answering, though she knows the answers","bucket":"presenting"},{"id":"form-316-2","text":"She lives in Hyderabad","bucket":"distractor"},{"id":"form-316-3","text":"Mother is also socially anxious","bucket":"predisposing"},{"id":"form-316-4","text":"One close friend from her old school","bucket":"protective"},{"id":"form-316-5","text":"Teacher allows her to skip oral work","bucket":"perpetuating"},{"id":"form-316-6","text":"Rehearses sentences in her head and then forgets them","bucket":"perpetuating"},{"id":"form-316-7","text":"Shy since childhood","bucket":"predisposing"},{"id":"form-316-8","text":"Strong marks in written work","bucket":"protective"},{"id":"form-316-9","text":"Intense fear of being judged when speaking in class or eating in front of others, for eight months","bucket":"presenting"},{"id":"form-316-10","text":"Moved from an Urdu-medium to an English-medium school and was laughed at for her accent","bucket":"precipitating"},{"id":"form-316-11","text":"Avoids speaking, so her fear is never tested","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Fatima, 13, has social anxiety disorder: a marked fear of being judged when speaking or eating in front of others, with avoidance that affects school, for over six months. A shy temperament and a socially anxious mother (predisposing) raise her risk; being laughed at for her accent after changing to an English-medium school (precipitating) set it off. Avoidance, mental rehearsal and being excused from oral work (perpetuating) keep the fear alive. Strong written work and a close friend (protective) are strengths. Plan: CBT with gradual speaking practice, help with spoken English in a safe setting and a teacher plan that supports small steps rather than avoidance. Hyderabad is a distractor.","hint":"A 13-year-old who freezes when asked to speak in class","tags":{"topic":"anxiety","difficulty":2,"objective":"Sort social anxiety in a young adolescent into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"anxiety","diagnosis":"Social anxiety disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-317', 'Mr Rao: the postmaster who forgot the way home (early Alzheimer''s disease)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-317-1","text":"Two years of slowly worsening memory for recent events, repeating questions","bucket":"presenting"},{"id":"form-317-2","text":"Lives with his wife only; children in other cities","bucket":"perpetuating"},{"id":"form-317-3","text":"Age over seventy-five","bucket":"predisposing"},{"id":"form-317-4","text":"Still dresses, bathes and eats independently","bucket":"protective"},{"id":"form-317-5","text":"He collected stamps all his life","bucket":"distractor"},{"id":"form-317-6","text":"Strong habit of morning walks and temple visits","bucket":"protective"},{"id":"form-317-7","text":"Family attributes changes to ''old age'' and has not sought help","bucket":"perpetuating"},{"id":"form-317-8","text":"Mother had memory loss in old age","bucket":"predisposing"},{"id":"form-317-9","text":"Wife''s hospital admission removed his daily routine and helper","bucket":"precipitating"},{"id":"form-317-10","text":"Got lost walking back from the market he has used for forty years","bucket":"presenting"},{"id":"form-317-11","text":"Hearing loss limits conversation","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Rao, 76, presents with mild Alzheimer''s disease: gradual, progressive loss of recent memory over two years, now affecting safety, while basic self-care is preserved. Age and a mother with late-life memory loss (predisposing) raise his risk; his wife''s admission (precipitating) exposed how much she had been compensating. Few people around him, untreated hearing loss and the family''s ''old age'' explanation (perpetuating) delay diagnosis and support. Preserved self-care and regular routines (protective) help him stay independent for longer. Plan: memory assessment and blood tests, hearing aids, safety steps for walking out, support for his wife and consider medicine. Stamp collecting is a distractor.","hint":"A 76-year-old retired postmaster with two years of slowly worsening memory","tags":{"topic":"neurocognitive","difficulty":1,"objective":"Sort early Alzheimer''s disease into the 5 Ps","exams":["cuet-pg","ma-semester","mcp-entrance"],"module":"neurocognitive","diagnosis":"Mild major neurocognitive disorder due to Alzheimer''s disease"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-318', 'Mrs Gomes: quiet and sleepy, mistaken for low mood (hypoactive delirium)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-318-1","text":"Attention drifts mid-sentence and she is unsure of the day","bucket":"presenting"},{"id":"form-318-2","text":"Infection treatable with antibiotics","bucket":"protective"},{"id":"form-318-3","text":"Chest infection with a low-grade fever","bucket":"precipitating"},{"id":"form-318-4","text":"Not drinking enough","bucket":"perpetuating"},{"id":"form-318-5","text":"Daughter who knows her usual self","bucket":"protective"},{"id":"form-318-6","text":"Two months of steadily low mood with guilt and clear attention","bucket":"distractor"},{"id":"form-318-7","text":"Ward staff think she is ''depressed'' and request an antidepressant","bucket":"perpetuating"},{"id":"form-318-8","text":"Mild memory problems for a year","bucket":"predisposing"},{"id":"form-318-9","text":"Age over eighty with poor eyesight","bucket":"predisposing"},{"id":"form-318-10","text":"Over three days, drowsy, withdrawn, speaks little and stopped eating","bucket":"presenting"},{"id":"form-318-11","text":"No spectacles or clock in the side room","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Gomes, 81, has hypoactive delirium caused by pneumonia: an acute change over days with drowsiness, poor attention and disorientation. The quiet, withdrawn type of delirium is often mistaken for depression, but the sudden onset and poor attention point to delirium; two months of low mood with clear attention, the distractor, would suggest depression and does not fit. Mild memory problems, age and poor eyesight (predisposing) raise her risk; the chest infection (precipitating) triggered it. A mistaken depression label, dehydration and a disorienting room (perpetuating) keep it going. Her daughter''s knowledge and a treatable cause (protective) help. Plan: treat the infection, fluids, glasses and orientation aids, avoid sedatives and new antidepressants, and recheck thinking after recovery.","hint":"An 81-year-old who has become withdrawn and drowsy over three days","tags":{"topic":"neurocognitive","difficulty":4,"objective":"Tell hypoactive delirium apart from depression in an older person","exams":["md-psychiatry","mcp-entrance"],"module":"neurocognitive","diagnosis":"Hypoactive delirium due to pneumonia"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-319', 'Mr Kulkarni: his father''s illness in his own hands (Huntington''s disease with depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-319-1","text":"Fidgety, jerky movements of his hands and face for a year","bucket":"presenting"},{"id":"form-319-2","text":"Father died of a ''shaking illness'' in his fifties","bucket":"predisposing"},{"id":"form-319-3","text":"Genetic test confirms an expanded repeat in the Huntington gene","bucket":"predisposing"},{"id":"form-319-4","text":"He was a good cricketer at school","bucket":"distractor"},{"id":"form-319-5","text":"Wife who is determined to support him","bucket":"protective"},{"id":"form-319-6","text":"Low mood, irritability and thoughts that ''there is no future'' for six months","bucket":"presenting"},{"id":"form-319-7","text":"Shame stops him telling his wider family","bucket":"perpetuating"},{"id":"form-319-8","text":"Fear for his two teenage children, who each have a one in two chance of inheriting it","bucket":"perpetuating"},{"id":"form-319-9","text":"Neurologist and genetic counsellor already involved","bucket":"protective"},{"id":"form-319-10","text":"Irritability causes fights at home","bucket":"perpetuating"},{"id":"form-319-11","text":"Lost his job as a draughtsman because of errors and clumsiness","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Kulkarni, 42, has Huntington''s disease with a depressive episode. Huntington''s disease is inherited in a dominant way, so each child has a one in two chance of carrying the gene; it causes involuntary movements, thinking changes and psychiatric symptoms such as depression and irritability, and suicide risk is raised. His father''s illness and the confirmed gene change (predisposing) underlie it; losing his job (precipitating) brought the illness into the open. Fear for his children, shame and irritability (perpetuating) feed his low mood. A supportive wife and an involved team (protective) are strengths. Plan: careful suicide risk assessment, treatment of depression, genetic counselling for the family when they are ready, and support for work and finances. Cricket is a distractor.","hint":"A 42-year-old with new fidgety movements and low mood, whose father had a ''shaking illness''","tags":{"topic":"neurocognitive","difficulty":4,"objective":"Formulate Huntington''s disease with its psychiatric features and family risks","exams":["md-psychiatry","mcp-entrance"],"module":"neurocognitive","diagnosis":"Huntington''s disease with a depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-320', 'Mr Thakkar: the betting started with the new tablet (impulse control problems from a dopamine agonist)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-320-1","text":"Gambling every week since his twenties","bucket":"distractor"},{"id":"form-320-2","text":"Has access to all bank accounts on his phone","bucket":"perpetuating"},{"id":"form-320-3","text":"Pramipexole was added and increased six months ago","bucket":"precipitating"},{"id":"form-320-4","text":"Son who noticed the bank statements","bucket":"protective"},{"id":"form-320-5","text":"Parkinson''s disease for five years","bucket":"predisposing"},{"id":"form-320-6","text":"Doctor not told, so the dose was raised again","bucket":"perpetuating"},{"id":"form-320-7","text":"Enjoyed taking small risks in business","bucket":"predisposing"},{"id":"form-320-8","text":"Movement symptoms well controlled otherwise","bucket":"protective"},{"id":"form-320-9","text":"Never gambled before; feels unable to stop","bucket":"presenting"},{"id":"form-320-10","text":"Hides losses from his wife","bucket":"perpetuating"},{"id":"form-320-11","text":"New compulsive online betting and overspending for four months, losing several lakh rupees","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Thakkar, 63, has an impulse control disorder with gambling caused by pramipexole, a dopamine agonist used for Parkinson''s disease. These medicines can trigger gambling, shopping, binge eating or sexual behaviour in some people, often hidden from doctors. Parkinson''s disease and a risk-taking temperament (predisposing) raise his vulnerability; starting and raising pramipexole (precipitating) set it off. Secrecy, easy phone banking and further dose increases (perpetuating) maintain it. The new onset with the medicine separates it from lifelong gambling, which the distractor describes. Good motor control and a watchful son (protective) help. Plan: tell the neurologist so the agonist can be reduced or changed, protect finances and offer support for the family.","hint":"A 63-year-old with Parkinson''s disease who suddenly lost lakhs on betting","tags":{"topic":"neurocognitive","difficulty":4,"objective":"Recognise impulse control problems caused by Parkinson''s medicines","exams":["md-psychiatry","mcp-entrance"],"module":"brain","diagnosis":"Impulse control disorder (gambling) caused by a dopamine agonist in Parkinson''s disease"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-321', 'Mrs Bhalla: slower to find words but still running the house (mild cognitive impairment)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-321-1","text":"Fully independent in daily life","bucket":"protective"},{"id":"form-321-2","text":"She lives in Amritsar","bucket":"distractor"},{"id":"form-321-3","text":"Keen reader and keen to stay active","bucket":"protective"},{"id":"form-321-4","text":"Poorly controlled sugar","bucket":"perpetuating"},{"id":"form-321-5","text":"Forgets appointments and names more than before, confirmed on memory testing","bucket":"presenting"},{"id":"form-321-6","text":"Worry about memory disturbs her sleep","bucket":"perpetuating"},{"id":"form-321-7","text":"Diabetes and high blood pressure for fifteen years","bucket":"predisposing"},{"id":"form-321-8","text":"Stopped her evening walks and social visits","bucket":"perpetuating"},{"id":"form-321-9","text":"Still manages money, cooking and travel on her own","bucket":"presenting"},{"id":"form-321-10","text":"Noticed problems after her husband''s retirement changed her routine","bucket":"precipitating"},{"id":"form-321-11","text":"Low physical activity","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Bhalla, 69, has mild cognitive impairment: memory decline beyond what is expected for her age, shown on testing, while she remains independent in daily life. That independence separates it from dementia. Some people with mild cognitive impairment stay stable or improve, while others progress. Long-standing diabetes, high blood pressure and inactivity (predisposing) raise her risk; a change in routine after her husband retired (precipitating) made the problem noticeable. Poor sugar control, giving up walks and visits, and poor sleep from worry (perpetuating) may worsen her thinking. Independence and her love of reading (protective) help. Plan: control sugar and blood pressure, exercise, social and mental activity, treat sleep and review in a year. Amritsar is a distractor.","hint":"A 69-year-old retired teacher who worries about her memory","tags":{"topic":"neurocognitive","difficulty":2,"objective":"Recognise mild cognitive impairment and what separates it from dementia","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"neurocognitive","diagnosis":"Mild cognitive impairment"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-322', 'Shabnam: low between the seizures (depression in epilepsy)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-322-1","text":"A marriage proposal was withdrawn after the family learned of her epilepsy","bucket":"precipitating"},{"id":"form-322-2","text":"Recently started a seizure medicine that can lower mood","bucket":"perpetuating"},{"id":"form-322-3","text":"Low mood, poor sleep and loss of interest for four months","bucket":"presenting"},{"id":"form-322-4","text":"Seizures still occur monthly, and she misses tablets when low","bucket":"perpetuating"},{"id":"form-322-5","text":"Brief low mood only in the day after each seizure","bucket":"distractor"},{"id":"form-322-6","text":"Works from home as a tailor","bucket":"protective"},{"id":"form-322-7","text":"Close to her younger sister","bucket":"protective"},{"id":"form-322-8","text":"Mother had depression","bucket":"predisposing"},{"id":"form-322-9","text":"Feels she is ''a burden'' and ''nobody will marry a girl with fits''","bucket":"presenting"},{"id":"form-322-10","text":"Not allowed to go out alone","bucket":"perpetuating"},{"id":"form-322-11","text":"Temporal lobe epilepsy since age fourteen","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Shabnam, 29, has a depressive episode alongside temporal lobe epilepsy. Depression is common in epilepsy and can be linked to the illness itself, some seizure medicines and stigma; suicide risk is raised, so it must be asked about. Brief low mood only after a seizure, the distractor, would be a short post-seizure change and does not explain four months of symptoms. Temporal lobe epilepsy and a mother with depression (predisposing) raise her risk; the withdrawn marriage proposal (precipitating) triggered the episode. Ongoing seizures, missed tablets when low, a mood-lowering medicine and restricted freedom (perpetuating) maintain it. Her sister and her tailoring work (protective) help. Plan: risk assessment, review of seizure medicines with the neurologist, an antidepressant that is safe in epilepsy and work on stigma.","hint":"A 29-year-old with temporal lobe epilepsy who has been low for months","tags":{"topic":"depression","difficulty":3,"objective":"Formulate depression in a person with epilepsy, including medicine and stigma factors","exams":["mcp-entrance","md-psychiatry"],"module":"brain","diagnosis":"Depressive episode in a woman with temporal lobe epilepsy"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-323', 'Mr Lalchand: slowed thinking with a virus that went untreated (HIV-associated neurocognitive disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-323-1","text":"Six months of slowed thinking, poor concentration and forgetting routes he has driven for years","bucket":"presenting"},{"id":"form-323-2","text":"Strong love for his children","bucket":"protective"},{"id":"form-323-3","text":"Antiretroviral treatment is free and often improves thinking","bucket":"protective"},{"id":"form-323-4","text":"Fear his wife will leave stops him telling her or starting treatment","bucket":"perpetuating"},{"id":"form-323-5","text":"Years of long-distance driving and unprotected sex with sex workers","bucket":"predisposing"},{"id":"form-323-6","text":"Never tested before","bucket":"predisposing"},{"id":"form-323-7","text":"Admitted with pneumonia, when HIV was found","bucket":"precipitating"},{"id":"form-323-8","text":"Counsellor at the ART centre who has built trust","bucket":"protective"},{"id":"form-323-9","text":"Continues to drive while slowed","bucket":"perpetuating"},{"id":"form-323-10","text":"He drives a tanker on the Kandla route","bucket":"distractor"},{"id":"form-323-11","text":"Newly diagnosed with HIV after weight loss and infections, with a low immune count","bucket":"presenting"},{"id":"form-323-12","text":"Drinks alcohol at night to forget","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Lalchand, 44, has HIV-associated neurocognitive disorder with low mood: slowed thinking, poor concentration and memory problems in untreated HIV with a low immune count. Treatment with antiretroviral therapy often improves thinking, so starting it is urgent. Years of unprotected sex and never testing (predisposing) led to late diagnosis; the pneumonia admission (precipitating) revealed it. Fear of telling his wife, which also puts her at risk, continuing to drive while slowed and drinking (perpetuating) are serious problems. Free treatment, a trusted counsellor and love for his children (protective) are the way forward. Plan: start treatment, rule out brain infections, support him to tell his wife and test her, advise him to stop driving until reassessed, treat low mood and alcohol. The tanker route is a distractor.","hint":"A 44-year-old truck driver with slow thinking and a new HIV diagnosis","tags":{"topic":"neurocognitive","difficulty":5,"objective":"Build a full formulation of HIV-related cognitive change with treatment, stigma and safety","exams":["md-psychiatry","mcp-entrance"],"module":"neurocognitive","diagnosis":"HIV-associated neurocognitive disorder, mild, with low mood"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-324', 'Ms Dsouza: exhausted, low and losing words (depression in multiple sclerosis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-324-1","text":"She lives in Goa","bucket":"distractor"},{"id":"form-324-2","text":"Neurologist who takes mood seriously","bucket":"protective"},{"id":"form-324-3","text":"Multiple sclerosis for six years","bucket":"predisposing"},{"id":"form-324-4","text":"A relapse with weakness in her leg forced her to stop working as a dance teacher","bucket":"precipitating"},{"id":"form-324-5","text":"Severe tiredness, slowed thinking and trouble finding words","bucket":"presenting"},{"id":"form-324-6","text":"Recently started interferon, which can lower mood in some people","bucket":"perpetuating"},{"id":"form-324-7","text":"Supportive partner","bucket":"protective"},{"id":"form-324-8","text":"Fatigue makes her rest all day, and she loses contact with friends","bucket":"perpetuating"},{"id":"form-324-9","text":"Believes ''I am useless now''","bucket":"perpetuating"},{"id":"form-324-10","text":"Perfectionist who measures herself by work","bucket":"predisposing"},{"id":"form-324-11","text":"Low mood, loss of interest and hopelessness for three months","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ms Dsouza, 34, has a depressive episode in multiple sclerosis. Depression is common in multiple sclerosis and is more than fatigue: she has low mood, lost interest and hopelessness as well as tiredness. Multiple sclerosis and a perfectionist identity tied to work (predisposing) raise her vulnerability; a relapse that ended her dance teaching (precipitating) triggered the episode. Fatigue-driven withdrawal, the belief that she is useless and interferon treatment (perpetuating) maintain it. Her partner and an attentive neurologist (protective) help. Plan: risk assessment, treat depression, review the interferon with the neurologist, fatigue management and help to find new roles. Goa is a distractor.","hint":"A 34-year-old with multiple sclerosis whose low mood began after a relapse","tags":{"topic":"depression","difficulty":3,"objective":"Formulate depression in multiple sclerosis, separating fatigue from low mood","exams":["mcp-entrance","md-psychiatry"],"module":"brain","diagnosis":"Depressive episode in multiple sclerosis"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-325', 'Havildar Negi: the blast, the headaches and the nightmares (mild brain injury with PTSD)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-325-1","text":"Nightmares, flashbacks of the blast, startle at loud sounds and avoidance of vehicles","bucket":"presenting"},{"id":"form-325-2","text":"Army medical services available","bucket":"protective"},{"id":"form-325-3","text":"Roadside explosion that killed a colleague; brief loss of consciousness","bucket":"precipitating"},{"id":"form-325-4","text":"Poor sleep from nightmares worsens concentration","bucket":"perpetuating"},{"id":"form-325-5","text":"Father also a soldier who never spoke of feelings","bucket":"predisposing"},{"id":"form-325-6","text":"Headaches, poor concentration and irritability since an explosion near his patrol vehicle eight months ago","bucket":"presenting"},{"id":"form-325-7","text":"Headaches lead to daily painkiller use","bucket":"perpetuating"},{"id":"form-325-8","text":"Wife who has noticed and brought him","bucket":"protective"},{"id":"form-325-9","text":"Two earlier deployments with exposure to combat","bucket":"predisposing"},{"id":"form-325-10","text":"Avoids talking about the event in a culture of ''staying strong''","bucket":"perpetuating"},{"id":"form-325-11","text":"He is from a village near Pithoragarh","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Havildar Negi, 33, has PTSD together with persistent symptoms after a mild traumatic brain injury. Headaches, poor concentration and irritability can come from both; nightmares, flashbacks, startle and avoidance point clearly to PTSD, which is treatable. Earlier combat exposure and a family culture of silence (predisposing) raised his risk; the explosion that killed a colleague with brief loss of consciousness (precipitating) caused both problems. Daily painkillers, avoidance and poor sleep (perpetuating) worsen headaches and thinking. His wife and available services (protective) help. Plan: trauma-focused therapy, sleep treatment, managing medication overuse headache, cognitive review and asking about suicide and alcohol. His home village is a distractor.","hint":"A 33-year-old soldier with headaches, poor focus and nightmares after an explosion","tags":{"topic":"trauma","difficulty":4,"objective":"Untangle the overlap of mild traumatic brain injury and PTSD","exams":["md-psychiatry","mcp-entrance"],"module":"trauma","diagnosis":"Post-traumatic stress disorder with persistent symptoms after mild traumatic brain injury"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-326', 'Pooja: lupus, high-dose steroids and the voices (steroid-induced psychosis or lupus in the brain)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-326-1","text":"Frightened of the ward, so refuses tablets","bucket":"perpetuating"},{"id":"form-326-2","text":"Started high-dose prednisolone for a lupus kidney flare ten days ago","bucket":"precipitating"},{"id":"form-326-3","text":"Anxious personality","bucket":"predisposing"},{"id":"form-326-4","text":"Poor sleep worsens confusion","bucket":"perpetuating"},{"id":"form-326-5","text":"No past psychiatric illness","bucket":"protective"},{"id":"form-326-6","text":"Paranoid beliefs that nurses are poisoning her drip and hearing voices for five days","bucket":"presenting"},{"id":"form-326-7","text":"Lupus team working closely with psychiatry","bucket":"protective"},{"id":"form-326-8","text":"Close mother at her bedside","bucket":"protective"},{"id":"form-326-9","text":"Steroid dose cannot simply be stopped because of the kidney flare","bucket":"perpetuating"},{"id":"form-326-10","text":"Voices and paranoia for years before lupus or steroids","bucket":"distractor"},{"id":"form-326-11","text":"Sleeping little and very restless","bucket":"presenting"},{"id":"form-326-12","text":"Lupus diagnosed two years ago","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Pooja, 25, has psychosis that is most likely induced by high-dose steroids, though lupus affecting the brain must be ruled out. Steroid psychosis is linked to dose and usually starts in the first weeks; lupus can also cause psychosis, seizures and confusion. Years of psychotic symptoms before lupus, the distractor, would point to a primary psychotic illness and does not fit. Lupus and an anxious temperament (predisposing) raise her risk; starting high-dose prednisolone (precipitating) came days before onset. The need to keep steroids for her kidneys, refusing tablets and poor sleep (perpetuating) maintain it. No past illness, her mother and joint care (protective) help. Plan: brain scan, spinal fluid and lupus tests as advised, lower the steroid when safe, short-term antipsychotic, good sleep and a calm, safe room.","hint":"A 25-year-old with lupus who became paranoid on high-dose prednisolone","tags":{"topic":"psychosis","difficulty":5,"objective":"Formulate psychosis in lupus, weighing steroid effects against brain involvement","exams":["md-psychiatry","mcp-entrance"],"module":"brain","diagnosis":"Substance-induced psychotic disorder (corticosteroids), with neuropsychiatric lupus to be ruled out"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-327', 'Mrs Banerjee: the lump, the surgery and the sleepless nights (adjustment disorder after a cancer diagnosis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-327-1","text":"Husband and colleagues are very supportive","bucket":"protective"},{"id":"form-327-2","text":"Has not told her teenage daughter","bucket":"perpetuating"},{"id":"form-327-3","text":"She teaches geography","bucket":"distractor"},{"id":"form-327-4","text":"Searches the internet late at night for survival figures","bucket":"perpetuating"},{"id":"form-327-5","text":"Her mother died of cancer when she was a teenager","bucket":"predisposing"},{"id":"form-327-6","text":"Worry, poor sleep and crying spells since her breast cancer diagnosis a month ago","bucket":"presenting"},{"id":"form-327-7","text":"Tends to worry about health","bucket":"predisposing"},{"id":"form-327-8","text":"Diagnosis of early breast cancer and surgery planned next week","bucket":"precipitating"},{"id":"form-327-9","text":"Fear of losing her hair at school","bucket":"perpetuating"},{"id":"form-327-10","text":"Good prognosis for early cancer","bucket":"protective"},{"id":"form-327-11","text":"Still cares for her family and keeps hospital appointments","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Banerjee, 48, has an adjustment disorder with anxiety and low mood after an early breast cancer diagnosis: distress that is understandable but strong enough to disturb her sleep and peace, while she still functions. Losing her mother to cancer and a worrying temperament (predisposing) shape her fear; the diagnosis and upcoming surgery (precipitating) triggered it. Night-time internet searches, keeping it from her daughter and fear about appearance (perpetuating) feed anxiety. A good prognosis and strong support (protective) predict recovery. Plan: clear information from her team, limits on internet searching, support for telling her daughter, sleep help and screening for depression during treatment. Geography is a distractor.","hint":"A 48-year-old school teacher told she has breast cancer a month ago","tags":{"topic":"liaison","difficulty":1,"objective":"Sort an adjustment reaction to a cancer diagnosis into the 5 Ps","exams":["cuet-pg","ma-semester","mcp-entrance"],"module":"lifespan","diagnosis":"Adjustment disorder with mixed anxiety and depressed mood"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-328', 'Mr Siddiqui: three times a week on the dialysis machine (depression in kidney failure)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-328-1","text":"He likes old ghazals","bucket":"distractor"},{"id":"form-328-2","text":"Fluid and diet limits take away food he loves","bucket":"perpetuating"},{"id":"form-328-3","text":"Past episode of low mood after his business failed","bucket":"predisposing"},{"id":"form-328-4","text":"Long hours tied to the machine and travel to the centre","bucket":"perpetuating"},{"id":"form-328-5","text":"Had to sell his shop because he could no longer work full days","bucket":"precipitating"},{"id":"form-328-6","text":"Close bond with his grandchildren","bucket":"protective"},{"id":"form-328-7","text":"Diabetes and kidney failure for years","bucket":"predisposing"},{"id":"form-328-8","text":"Dialysis nurses who know him well","bucket":"protective"},{"id":"form-328-9","text":"Believes he is a burden on his sons","bucket":"perpetuating"},{"id":"form-328-10","text":"Says he wants to stop dialysis because ''this is no life''","bucket":"presenting"},{"id":"form-328-11","text":"Low mood, hopelessness and poor sleep for two months","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Siddiqui, 57, has a depressive episode while on dialysis for kidney failure. Depression is common in dialysis patients and can drive a wish to stop treatment, so treating depression and exploring his wish carefully must come before any decision. Long-standing illness and a past depressive episode (predisposing) raise his risk; selling his shop (precipitating) took away his role. Long treatment hours, diet limits and feeling a burden (perpetuating) maintain it. His grandchildren and the nurses who know him (protective) are supports. Plan: assess suicide risk and capacity, treat depression with a medicine safe in kidney failure, involve the kidney team and family, and explore what would make life feel worth living. Ghazals are a distractor.","hint":"A 57-year-old on dialysis who says he wants to stop treatment","tags":{"topic":"liaison","difficulty":2,"objective":"Recognise depression in a patient on dialysis and why it changes decisions","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"depression","diagnosis":"Depressive episode in end-stage kidney disease on dialysis"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-329', 'Mr Paul: home from intensive care but not himself (post-intensive care syndrome)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-329-1","text":"No one explained what happened to him in the ICU","bucket":"perpetuating"},{"id":"form-329-2","text":"Nightmares of being tied down and ''tortured'' in the ICU, and panics at the smell of hospitals","bucket":"presenting"},{"id":"form-329-3","text":"Physiotherapy is improving his strength","bucket":"protective"},{"id":"form-329-4","text":"Avoids follow-up clinic visits because of the hospital smell","bucket":"perpetuating"},{"id":"form-329-5","text":"Poor memory and concentration, weakness and low mood since discharge two months ago","bucket":"presenting"},{"id":"form-329-6","text":"Anxious personality","bucket":"predisposing"},{"id":"form-329-7","text":"Wife kept a diary of his ICU stay","bucket":"protective"},{"id":"form-329-8","text":"Cannot work and feels useless","bucket":"perpetuating"},{"id":"form-329-9","text":"Diabetes and obesity","bucket":"predisposing"},{"id":"form-329-10","text":"Three weeks on a ventilator with severe pneumonia, with delirium during the stay","bucket":"precipitating"},{"id":"form-329-11","text":"He sells insurance in Kochi","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Paul, 52, has post-intensive care syndrome: new or worse mental health, thinking and physical problems after critical illness. His nightmares of being tied down and tortured are memories of delirium during ventilation, and with panic and avoidance they form PTSD symptoms; he also has memory problems and low mood. An anxious temperament and medical illnesses (predisposing) raised his risk; three weeks on a ventilator with delirium (precipitating) caused the problems. Avoiding clinic, feeling useless and no explanation of what happened (perpetuating) maintain them. Physiotherapy progress and his wife''s ICU diary (protective) help; reading the diary can make sense of frightening memories. Plan: explain delirium and ICU events, trauma-focused therapy, cognitive rehabilitation and graded return to work. His job is a distractor.","hint":"A 52-year-old who survived three weeks on a ventilator and now has nightmares and poor memory","tags":{"topic":"liaison","difficulty":3,"objective":"Formulate the mental and thinking problems after a long intensive care stay","exams":["mcp-entrance","md-psychiatry"],"module":"trauma","diagnosis":"Post-intensive care syndrome with PTSD symptoms and cognitive impairment"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-330', 'Mrs Naik: the round face, the bruises and the low mood (depression from Cushing''s syndrome)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-330-1","text":"Weight gain around the face and tummy, purple stretch marks, easy bruising and new high blood pressure","bucket":"presenting"},{"id":"form-330-2","text":"Supportive husband","bucket":"protective"},{"id":"form-330-3","text":"Symptoms began slowly with no clear life event","bucket":"precipitating"},{"id":"form-330-4","text":"The hormone cause has not been tested","bucket":"perpetuating"},{"id":"form-330-5","text":"No steroid medicines or creams","bucket":"predisposing"},{"id":"form-330-6","text":"A curious general physician who noticed the stretch marks","bucket":"protective"},{"id":"form-330-7","text":"Low mood that began after a clear life event and improved with an antidepressant","bucket":"distractor"},{"id":"form-330-8","text":"Low mood, irritability and poor sleep for six months","bucket":"presenting"},{"id":"form-330-9","text":"Treated with two antidepressants without improvement","bucket":"perpetuating"},{"id":"form-330-10","text":"No past mental illness","bucket":"predisposing"},{"id":"form-330-11","text":"Shame about her appearance keeps her at home","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Naik, 39, has depression caused by Cushing''s syndrome: too much cortisol, shown by central weight gain, a round face, purple stretch marks, bruising and high blood pressure. Depression is common in Cushing''s syndrome and often does not respond until the hormone problem is treated. No past illness and no steroid use (predisposing context) point to the body''s own cortisol; symptoms began without a life event. Ineffective antidepressants, shame and no hormone testing (perpetuating) delay recovery. A supportive husband and an observant physician (protective) help. The distractor, low mood after a life event that improved with treatment, would fit ordinary depression. Plan: cortisol tests, referral to an endocrinologist and support for mood and body image.","hint":"A 39-year-old with weight gain, high blood pressure and depression","tags":{"topic":"depression","difficulty":4,"objective":"Look for a hormone cause behind depression with physical signs","exams":["md-psychiatry","mcp-entrance"],"module":"brain","diagnosis":"Depressive disorder due to Cushing''s syndrome"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-331', 'Mr Shetty: grand schemes and a failing memory (general paresis from neurosyphilis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-331-1","text":"Over a year, grand plans to buy hotels with no money, poor judgement and inappropriate jokes","bucket":"presenting"},{"id":"form-331-2","text":"Treated with a mood stabiliser without benefit","bucket":"perpetuating"},{"id":"form-331-3","text":"Treated for a genital sore twenty years ago without follow-up","bucket":"predisposing"},{"id":"form-331-4","text":"Infection untreated, so the brain damage continues","bucket":"perpetuating"},{"id":"form-331-5","text":"Blood and spinal fluid tests can confirm it","bucket":"protective"},{"id":"form-331-6","text":"Memory and attention declining; small pupils that do not react well to light","bucket":"presenting"},{"id":"form-331-7","text":"Lost his job after making unauthorised deals","bucket":"precipitating"},{"id":"form-331-8","text":"Penicillin treatment can halt progression","bucket":"protective"},{"id":"form-331-9","text":"Family thinks it is ''a midlife crisis'' or mania","bucket":"perpetuating"},{"id":"form-331-10","text":"Episodes of mania in his twenties with full recovery between them","bucket":"distractor"},{"id":"form-331-11","text":"Unprotected sex during years of travel for work","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Shetty, 48, has general paresis, a late form of neurosyphilis, causing grandiosity, poor judgement and a progressive decline in memory and attention, with abnormal pupils. It can be mistaken for mania or a midlife change; the distractor of earlier manic episodes with full recovery would suggest bipolar disorder, which does not fit the steady cognitive decline. A past untreated genital sore and unprotected sex (predisposing) explain the infection; job loss (precipitating) brought him to care. Misreading it as a midlife crisis or mania and an untreated infection (perpetuating) allow damage to continue. Testing and penicillin treatment (protective) can stop progression, though some damage may remain. Plan: blood and spinal fluid tests, treatment, protecting finances, and testing his partner.","hint":"A 48-year-old with new grandiosity, poor judgement and memory loss","tags":{"topic":"neurocognitive","difficulty":5,"objective":"Recognise neurosyphilis as a treatable cause of grandiosity and dementia","exams":["md-psychiatry","mcp-entrance"],"module":"neurocognitive","diagnosis":"General paresis (neurosyphilis)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-332', 'Ms Kaveri: headaches, worry and a painkiller every day (medication overuse headache with anxiety)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-332-1","text":"Mother has migraine and anxiety","bucket":"predisposing"},{"id":"form-332-2","text":"Fears a brain tumour and checks symptoms online","bucket":"perpetuating"},{"id":"form-332-3","text":"Worries constantly about work and her health","bucket":"presenting"},{"id":"form-332-4","text":"Migraine since her teens","bucket":"predisposing"},{"id":"form-332-5","text":"She works in Bengaluru","bucket":"distractor"},{"id":"form-332-6","text":"Normal brain scan","bucket":"protective"},{"id":"form-332-7","text":"Takes painkillers almost every day ''to prevent'' headaches","bucket":"perpetuating"},{"id":"form-332-8","text":"Skips meals and sleeps late","bucket":"perpetuating"},{"id":"form-332-9","text":"Supportive flatmate who does yoga with her","bucket":"protective"},{"id":"form-332-10","text":"Headache on most days for six months, waking with it","bucket":"presenting"},{"id":"form-332-11","text":"New job with long screen hours and a demanding manager","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ms Kaveri, 31, has medication overuse headache on top of migraine, with generalised anxiety. Taking painkillers on most days can itself cause daily headaches, and anxiety, poor sleep and missed meals make migraine worse. Migraine since her teens and a mother with migraine and anxiety (predisposing) raise her risk; a stressful new job with long screen hours (precipitating) increased headaches. Daily painkillers, irregular meals and sleep, and health fears with online checking (perpetuating) keep the cycle going. A normal scan and a supportive flatmate (protective) help. Plan: explain the cycle, withdraw painkillers with a plan, a migraine preventive, regular meals and sleep, and CBT for worry. Bengaluru is a distractor.","hint":"A 31-year-old with daily headaches and constant worry","tags":{"topic":"somatic","difficulty":2,"objective":"Formulate the cycle of anxiety, migraine and painkiller overuse","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"anxiety","diagnosis":"Medication overuse headache on a background of migraine, with generalised anxiety"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-333', 'Smita: the daughter who gave up her job for her father''s stroke (carer strain)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-333-1","text":"Father''s stroke left him unable to walk or speak clearly","bucket":"precipitating"},{"id":"form-333-2","text":"Tends to put others first","bucket":"predisposing"},{"id":"form-333-3","text":"Close friend who calls her daily","bucket":"protective"},{"id":"form-333-4","text":"Father''s physiotherapist who offers advice","bucket":"protective"},{"id":"form-333-5","text":"Only child of a widowed father","bucket":"predisposing"},{"id":"form-333-6","text":"She was a bank teller in Nagpur","bucket":"distractor"},{"id":"form-333-7","text":"Feels guilty if she takes any time for herself","bucket":"perpetuating"},{"id":"form-333-8","text":"Has stopped seeing friends and sleeps poorly","bucket":"presenting"},{"id":"form-333-9","text":"Tired, tearful and irritable for four months","bucket":"presenting"},{"id":"form-333-10","text":"Lost her income after leaving her job","bucket":"perpetuating"},{"id":"form-333-11","text":"Cares for him alone day and night","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Smita, 36, has carer strain with an adjustment disorder with low mood after becoming her father''s full-time carer following his stroke. Being an only child and putting others first (predisposing) left her as the sole carer; the stroke (precipitating) changed her life overnight. Caring alone, guilt about any rest and lost income (perpetuating) wear her down. A close friend and a helpful physiotherapist (protective) are supports. Plan: screen for depression and risk, arrange respite or a paid helper, look into disability and carer benefits, and encourage small breaks without guilt. Her former job is a distractor.","hint":"A 36-year-old who left work to look after her father after his stroke","tags":{"topic":"liaison","difficulty":1,"objective":"Sort carer strain after a parent''s stroke into the 5 Ps","exams":["cuet-pg","ma-semester","mcp-entrance"],"module":"lifespan","diagnosis":"Carer strain with adjustment disorder with depressed mood"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-334', 'Mr Kalra: tingling feet, a failing memory and a gloomy mood (vitamin B12 deficiency)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-334-1","text":"Tingling and numbness in his feet and unsteady walking in the dark","bucket":"presenting"},{"id":"form-334-2","text":"Diabetes on metformin for twelve years","bucket":"predisposing"},{"id":"form-334-3","text":"Avoids walks because of unsteadiness","bucket":"perpetuating"},{"id":"form-334-4","text":"Memory and mood blamed on ''age''","bucket":"perpetuating"},{"id":"form-334-5","text":"Symptoms are often reversible if treated early","bucket":"protective"},{"id":"form-334-6","text":"Wife who keeps track of his medicines","bucket":"protective"},{"id":"form-334-7","text":"Lifelong strict vegetarian diet","bucket":"predisposing"},{"id":"form-334-8","text":"Daily acid-reducing tablets started a year ago","bucket":"precipitating"},{"id":"form-334-9","text":"Gradual memory decline over five years with normal B12 and no numbness","bucket":"distractor"},{"id":"form-334-10","text":"Forgetfulness and low mood for eight months","bucket":"presenting"},{"id":"form-334-11","text":"No B12 test done yet","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Kalra, 66, has vitamin B12 deficiency causing memory problems, low mood and nerve damage in his feet. A strict vegetarian diet, long use of metformin and acid-reducing tablets all lower B12 (predisposing and precipitating). Blaming everything on age, no test so far and avoiding walks (perpetuating) delay recovery. Treating early often reverses many symptoms, and his wife tracks his medicines (protective). The distractor of slow decline over years with normal B12 and no numbness would suggest Alzheimer''s disease instead. Plan: B12 and other blood tests, B12 injections, review of acid tablets, falls safety and recheck memory and mood after treatment.","hint":"A 66-year-old vegetarian on metformin with numb feet and low mood","tags":{"topic":"neurocognitive","difficulty":3,"objective":"Identify a reversible cause of cognitive and mood symptoms","exams":["mcp-entrance","md-psychiatry"],"module":"neurocognitive","diagnosis":"Vitamin B12 deficiency with cognitive impairment, low mood and neuropathy"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-335', 'Mrs Fernandes: sweaty, shaky and frightened before lunch (hypoglycaemia mistaken for panic)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-335-1","text":"Insulin dose increased a month ago, and she started fasting on certain days for religious reasons","bucket":"precipitating"},{"id":"form-335-2","text":"Daughter who is a nurse","bucket":"protective"},{"id":"form-335-3","text":"Type 2 diabetes on insulin","bucket":"predisposing"},{"id":"form-335-4","text":"Has a glucose meter at home","bucket":"protective"},{"id":"form-335-5","text":"Episodes of sweating, shaking, racing heart, fear and confusion, usually late morning","bucket":"presenting"},{"id":"form-335-6","text":"Treated as panic and given a sleeping tablet that hides the warning signs","bucket":"perpetuating"},{"id":"form-335-7","text":"Attacks that come at any time, even after meals, with normal sugar readings","bucket":"distractor"},{"id":"form-335-8","text":"Has not checked her sugar during attacks","bucket":"perpetuating"},{"id":"form-335-9","text":"Skips breakfast on fasting days","bucket":"perpetuating"},{"id":"form-335-10","text":"Settles after eating something sweet","bucket":"presenting"},{"id":"form-335-11","text":"Anxious temperament","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Fernandes, 60, has recurrent low blood sugar from insulin, presenting as panic-like episodes: sweating, shaking, racing heart and fear, with confusion, relieved by sugar and timed before lunch. Panic attacks with normal sugar at any time, the distractor, would suggest panic disorder and does not fit. Diabetes on insulin and an anxious temperament (predisposing) set the stage; a higher insulin dose and fasting days (precipitating) caused the lows. A panic label with a sedative, skipped breakfast and no sugar checks during attacks (perpetuating) are dangerous, as low sugar can cause fits or falls. A glucose meter and a nurse daughter (protective) help. Plan: check sugar during episodes, adjust insulin with her doctor, plan fasting days safely and stop the sedative.","hint":"A 60-year-old on insulin with attacks of fear and confusion","tags":{"topic":"anxiety","difficulty":4,"objective":"Recognise low blood sugar behind episodes that look like panic","exams":["md-psychiatry","mcp-entrance"],"module":"anxiety","diagnosis":"Recurrent hypoglycaemia from insulin, presenting as panic-like episodes"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-336', 'Mr Dutta: tears that come from nowhere after the stroke (pseudobulbar affect, not depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-336-1","text":"Family thinks he is ''very depressed'' and avoids visitors","bucket":"perpetuating"},{"id":"form-336-2","text":"Sudden bursts of crying or laughing, lasting seconds, out of keeping with how he feels","bucket":"presenting"},{"id":"form-336-3","text":"Good recovery of walking","bucket":"protective"},{"id":"form-336-4","text":"No one has explained the condition","bucket":"perpetuating"},{"id":"form-336-5","text":"High blood pressure and diabetes","bucket":"predisposing"},{"id":"form-336-6","text":"Embarrassment stops him going to the club","bucket":"perpetuating"},{"id":"form-336-7","text":"Persistent low mood, guilt and hopelessness for weeks","bucket":"distractor"},{"id":"form-336-8","text":"Two strokes affecting both sides of the brain","bucket":"predisposing"},{"id":"form-336-9","text":"Says his mood is ''all right'' and he enjoys his grandchildren","bucket":"presenting"},{"id":"form-336-10","text":"Mood otherwise normal","bucket":"protective"},{"id":"form-336-11","text":"Second stroke three months ago","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Dutta, 68, has pseudobulbar affect after strokes: sudden, brief, uncontrollable episodes of crying or laughing that do not match his inner mood. Depression, as in the distractor of weeks of low mood, guilt and hopelessness, is different and should still be screened for, since both can occur after stroke. Strokes affecting both sides of the brain and vascular risk factors (predisposing) underlie it; the second stroke (precipitating) started the episodes. The family''s mistaken view, embarrassment and no explanation (perpetuating) lead to isolation. Normal mood and good physical recovery (protective) help. Plan: explain the condition to him and his family, simple techniques to interrupt episodes, consider medicine if frequent, and return to social life.","hint":"A 68-year-old who cries or laughs suddenly since a stroke","tags":{"topic":"neurocognitive","difficulty":3,"objective":"Tell emotional lability after brain injury apart from depression","exams":["mcp-entrance","md-psychiatry"],"module":"brain","diagnosis":"Pseudobulbar affect (post-stroke emotional lability)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-337', 'Mrs Sen: forgetting at fifty-two (early-onset Alzheimer''s disease)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-337-1","text":"Father developed memory loss at 55","bucket":"predisposing"},{"id":"form-337-2","text":"Still has access to bank systems and her own finances","bucket":"perpetuating"},{"id":"form-337-3","text":"Two years of worsening memory, errors at work and getting lost in her own branch","bucket":"presenting"},{"id":"form-337-4","text":"Warned at work after serious errors in customer accounts","bucket":"precipitating"},{"id":"form-337-5","text":"Husband who wants to plan ahead","bucket":"protective"},{"id":"form-337-6","text":"Low mood in her forties","bucket":"predisposing"},{"id":"form-337-7","text":"Teenage son is taking on caring alone","bucket":"perpetuating"},{"id":"form-337-8","text":"Still able to express her wishes clearly","bucket":"protective"},{"id":"form-337-9","text":"Now struggles to use her phone and pay bills","bucket":"presenting"},{"id":"form-337-10","text":"Memory problems only during weeks of severe low mood, with full recovery","bucket":"distractor"},{"id":"form-337-11","text":"Colleagues and family assumed it was stress or menopause, so diagnosis was delayed","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Sen, 52, has early-onset Alzheimer''s disease: progressive memory and daily function decline starting before 65. Young-onset dementia is often missed as stress, low mood or menopause, and it brings special problems with work, money and young families. A father with early memory loss (predisposing) suggests a possible genetic factor; serious work errors (precipitating) brought her to attention. Delayed diagnosis, continued access to bank systems and her teenage son caring alone (perpetuating) create risks. Her husband''s wish to plan and her clear wishes now (protective) allow good planning. The distractor of memory problems only during low mood with full recovery would suggest depression. Plan: full assessment, honest diagnosis, workplace adjustments or medical retirement, power of attorney and advance planning, genetic counselling, support for her son and medicine.","hint":"A 52-year-old bank officer making errors at work and getting lost","tags":{"topic":"neurocognitive","difficulty":5,"objective":"Build a full formulation of young-onset dementia with work, family and legal needs","exams":["md-psychiatry","mcp-entrance"],"module":"neurocognitive","diagnosis":"Major neurocognitive disorder due to Alzheimer''s disease, early onset"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-338', 'Mr Pathak: where did I put my glasses? (normal ageing with worry)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-338-1","text":"Supportive wife","bucket":"protective"},{"id":"form-338-2","text":"Anxious temperament","bucket":"predisposing"},{"id":"form-338-3","text":"Friend recently diagnosed with dementia","bucket":"predisposing"},{"id":"form-338-4","text":"Active social life and daily walks","bucket":"protective"},{"id":"form-338-5","text":"Occasionally forgets names and where he put his glasses, recalling them later","bucket":"presenting"},{"id":"form-338-6","text":"Normal memory testing and full independence in daily life","bucket":"presenting"},{"id":"form-338-7","text":"Read a newspaper article about early signs of dementia","bucket":"precipitating"},{"id":"form-338-8","text":"He was a bank manager in Kanpur","bucket":"distractor"},{"id":"form-338-9","text":"Interprets every slip as a sign of illness","bucket":"perpetuating"},{"id":"form-338-10","text":"Tests himself repeatedly, which raises worry","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Pathak, 70, has normal age-related forgetfulness with health anxiety. Forgetting names and recalling them later, with normal testing and full independence, is part of normal ageing. An anxious temperament and a friend''s diagnosis (predisposing) increase his worry; a newspaper article (precipitating) set it off. Constant self-testing and treating every slip as illness (perpetuating) feed anxiety. His active life and supportive wife (protective) protect his brain health. Plan: explain normal ageing, reduce self-testing, keep up activity and offer review if real changes appear. His former job is a distractor.","hint":"A 70-year-old who fears every forgotten name is the start of dementia","tags":{"topic":"neurocognitive","difficulty":1,"objective":"Recognise normal ageing forgetfulness and reassure appropriately","exams":["cuet-pg","ma-semester","mcp-entrance"],"module":"neurocognitive","diagnosis":"Normal age-related forgetfulness with health anxiety"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-339', 'Mr Bose: confused after the cold tablets and the bladder pills (anticholinergic delirium)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-339-1","text":"Confused, seeing insects on the wall and agitated at night for three days","bucket":"presenting"},{"id":"form-339-2","text":"Age eighty with mild memory problems","bucket":"predisposing"},{"id":"form-339-3","text":"Dry mouth, constipation, difficulty passing urine and a fast pulse","bucket":"presenting"},{"id":"form-339-4","text":"Started oxybutynin for urine frequency and an over-the-counter cold tablet with an antihistamine","bucket":"precipitating"},{"id":"form-339-5","text":"Already taking amitriptyline for nerve pain","bucket":"perpetuating"},{"id":"form-339-6","text":"Son who brought all the medicine strips","bucket":"protective"},{"id":"form-339-7","text":"A sleeping syrup given at night by his son","bucket":"perpetuating"},{"id":"form-339-8","text":"Gradual memory decline over three years without sudden change","bucket":"distractor"},{"id":"form-339-9","text":"Different doctors do not know what others prescribed","bucket":"perpetuating"},{"id":"form-339-10","text":"Symptoms usually clear when the medicines stop","bucket":"protective"},{"id":"form-339-11","text":"Enlarged prostate","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Bose, 80, has delirium caused by anticholinergic medicines: sudden confusion, hallucinations and agitation with dry mouth, constipation, urinary retention and a fast pulse. Several medicines with anticholinergic effects (oxybutynin, an antihistamine cold tablet and amitriptyline) add up in older people. Age, mild memory problems and an enlarged prostate (predisposing) raise his risk; the new medicines (precipitating) triggered it. Amitriptyline, a sedating syrup and uncoordinated prescribing (perpetuating) maintain it. His son bringing all the strips and the reversibility once medicines stop (protective) help. The distractor of slow decline over years would suggest dementia rather than delirium. Plan: stop the culprits, check for urinary retention, fluids, a calm environment and one doctor coordinating his medicines.","hint":"An 80-year-old who became confused after new medicines from two doctors","tags":{"topic":"neurocognitive","difficulty":3,"objective":"Recognise delirium caused by the combined effect of anticholinergic medicines","exams":["mcp-entrance","md-psychiatry"],"module":"pharmacokinetics","diagnosis":"Delirium due to anticholinergic medicines"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-340', 'Mrs Ghosh: from normal to bedbound in four months (Creutzfeldt-Jakob disease)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-340-1","text":"No family history of dementia","bucket":"predisposing"},{"id":"form-340-2","text":"Sudden jerks of her limbs, especially when startled","bucket":"presenting"},{"id":"form-340-3","text":"Memory loss, confusion and unsteady walking that progressed over four months","bucket":"presenting"},{"id":"form-340-4","text":"Slow decline over eight years with no jerks","bucket":"distractor"},{"id":"form-340-5","text":"First noticed when she could not follow a recipe she had cooked for decades","bucket":"precipitating"},{"id":"form-340-6","text":"Palliative care team available","bucket":"protective"},{"id":"form-340-7","text":"No specific treatment exists","bucket":"perpetuating"},{"id":"form-340-8","text":"Family exhausted and unprepared","bucket":"perpetuating"},{"id":"form-340-9","text":"Initially treated for depression and anxiety, delaying tests","bucket":"perpetuating"},{"id":"form-340-10","text":"Previously well","bucket":"predisposing"},{"id":"form-340-11","text":"Close-knit family who want to keep her comfortable","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Ghosh, 63, most likely has sporadic Creutzfeldt-Jakob disease: a rapidly progressive dementia over months with unsteady walking and sudden jerks (myoclonus), often startle-triggered. Brain scan, brain wave tests and spinal fluid tests help confirm it. It usually occurs without a family history in previously well people (predisposing context); the first sign was losing a long-practised skill (precipitating). Early misdiagnosis as depression, no specific treatment and an exhausted family (perpetuating) make care hard. Her close family and palliative care (protective) can keep her comfortable. Slow decline over eight years, the distractor, would point to Alzheimer''s disease. Plan: confirm the diagnosis, infection control advice for procedures, honest communication and palliative care.","hint":"A 63-year-old with rapid memory loss, unsteady walking and sudden jerks","tags":{"topic":"neurocognitive","difficulty":4,"objective":"Recognise a rapidly progressive dementia and its key signs","exams":["md-psychiatry","mcp-entrance"],"module":"neurocognitive","diagnosis":"Probable sporadic Creutzfeldt-Jakob disease"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-341', 'Rekha: pain everywhere and sleep that never refreshes (fibromyalgia with depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-341-1","text":"Enjoys gardening when pain allows","bucket":"protective"},{"id":"form-341-2","text":"Tends to push herself and not rest","bucket":"predisposing"},{"id":"form-341-3","text":"Low mood and loss of interest for four months","bucket":"presenting"},{"id":"form-341-4","text":"Widespread pain for two years, tiredness and unrefreshing sleep","bucket":"presenting"},{"id":"form-341-5","text":"Childhood with a violent father","bucket":"predisposing"},{"id":"form-341-6","text":"She lives in Ranchi","bucket":"distractor"},{"id":"form-341-7","text":"Normal blood tests and supportive husband","bucket":"protective"},{"id":"form-341-8","text":"Pain worsened after a road accident with minor injuries two years ago","bucket":"precipitating"},{"id":"form-341-9","text":"Has seen many doctors and feels disbelieved","bucket":"perpetuating"},{"id":"form-341-10","text":"Rests completely on bad days and overdoes it on good days","bucket":"perpetuating"},{"id":"form-341-11","text":"Poor sleep increases pain sensitivity","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rekha, 44, has fibromyalgia with a depressive episode: widespread pain, fatigue and unrefreshing sleep, with recent low mood. Pain processing in the nervous system becomes more sensitive, and sleep and mood are closely linked to it. A difficult childhood and a habit of pushing herself (predisposing) raise her risk; a road accident (precipitating) worsened her pain. Feeling disbelieved, a cycle of rest and overactivity, and poor sleep (perpetuating) keep it going. Normal tests, her husband and gardening (protective) help. Plan: a clear explanation, graded activity and pacing, sleep treatment, a medicine that helps both pain and mood, and CBT. Ranchi is a distractor.","hint":"A 44-year-old with widespread pain, fatigue and low mood","tags":{"topic":"somatic","difficulty":2,"objective":"Formulate chronic widespread pain with low mood and poor sleep","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"more-disorders","diagnosis":"Fibromyalgia with a depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-342', 'Mr Mehra: shouting in the care home at bath time (agitation in dementia from unmet needs)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-342-1","text":"Moved to a care home two months ago; new staff who do not know his routines","bucket":"precipitating"},{"id":"form-342-2","text":"Arthritis in both knees","bucket":"predisposing"},{"id":"form-342-3","text":"Moderate Alzheimer''s disease","bucket":"predisposing"},{"id":"form-342-4","text":"Daughter who visits and knows his habits","bucket":"protective"},{"id":"form-342-5","text":"Enjoys old Punjabi songs","bucket":"protective"},{"id":"form-342-6","text":"Bathed early in the morning, though he always bathed in the evening at home","bucket":"perpetuating"},{"id":"form-342-7","text":"Calm at other times, especially with music","bucket":"presenting"},{"id":"form-342-8","text":"Pain in his knees when moved, not treated because he cannot describe it","bucket":"perpetuating"},{"id":"form-342-9","text":"Shouts and hits out at staff during bathing and dressing, for six weeks","bucket":"presenting"},{"id":"form-342-10","text":"Staff request a sedative","bucket":"perpetuating"},{"id":"form-342-11","text":"He was a cloth merchant in Amritsar","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Mehra, 84, has agitation in moderate Alzheimer''s disease that is best understood as a response to unmet needs. He becomes agitated only during personal care, which points to pain from his arthritic knees and the change from his lifelong routine. Alzheimer''s disease and arthritis (predisposing) underlie it; the move to a care home with new staff (precipitating) disrupted his routines. Untreated pain, morning baths and the push for sedation (perpetuating) maintain it, and sedatives carry serious risks in dementia. Music and his daughter''s knowledge (protective) offer solutions. Plan: regular painkillers, bathing in the evening, music during care, consistent staff and avoiding antipsychotics unless there is severe risk. His former trade is a distractor.","hint":"An 84-year-old with dementia who hits out during personal care","tags":{"topic":"neurocognitive","difficulty":3,"objective":"Formulate agitation in dementia by looking for unmet needs before medicine","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"neurocognitive","diagnosis":"Agitation in moderate Alzheimer''s disease linked to pain and unmet needs"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-343', 'Mrs Rani: fluent speech that no longer means anything (semantic dementia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-343-1","text":"Fluent speech but empty, while memory for recent events and appointments is good","bucket":"presenting"},{"id":"form-343-2","text":"Family corrects her constantly, which upsets her","bucket":"perpetuating"},{"id":"form-343-3","text":"Previously a language teacher","bucket":"predisposing"},{"id":"form-343-4","text":"Students complained she could not explain simple words","bucket":"precipitating"},{"id":"form-343-5","text":"Treated as stressed or low, delaying assessment","bucket":"perpetuating"},{"id":"form-343-6","text":"New rigid routines around food","bucket":"perpetuating"},{"id":"form-343-7","text":"Good recent memory and orientation","bucket":"protective"},{"id":"form-343-8","text":"Uncle had ''speech trouble'' in his sixties","bucket":"predisposing"},{"id":"form-343-9","text":"Early loss of memory for recent events with good word meaning","bucket":"distractor"},{"id":"form-343-10","text":"Two years of losing the meaning of words and not recognising familiar objects","bucket":"presenting"},{"id":"form-343-11","text":"Husband who adapts his language","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Rani, 60, has semantic dementia, a form of frontotemporal lobar degeneration: progressive loss of word meaning and object knowledge with fluent but empty speech, while day-to-day memory is preserved. That pattern is the reverse of early Alzheimer''s disease, described by the distractor of early recent memory loss with good word meaning. A family history (predisposing) may be relevant; complaints from students (precipitating) brought it to light. Delayed assessment, constant correction and new rigid food routines (perpetuating) add distress. Preserved memory and an adaptable husband (protective) help. Plan: specialist assessment, speech and language therapy, communication aids, family education and planning for the future.","hint":"A 60-year-old who asks what everyday words mean","tags":{"topic":"neurocognitive","difficulty":4,"objective":"Recognise semantic dementia and tell it apart from Alzheimer''s disease","exams":["md-psychiatry","mcp-entrance"],"module":"neurocognitive","diagnosis":"Semantic variant primary progressive aphasia (semantic dementia)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-344', 'Mr Rao: refusing to leave his house for a care home (capacity in dementia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-344-1","text":"Moderate Alzheimer''s disease","bucket":"predisposing"},{"id":"form-344-2","text":"He was a temple priest","bucket":"distractor"},{"id":"form-344-3","text":"Refuses to move to a care home after three falls and leaving the gas on twice","bucket":"presenting"},{"id":"form-344-4","text":"Son insists on a care home without exploring other options","bucket":"perpetuating"},{"id":"form-344-5","text":"Says ''I was born in this house and I will die here''","bucket":"presenting"},{"id":"form-344-6","text":"Neighbour willing to check on him daily","bucket":"protective"},{"id":"form-344-7","text":"No home help or safety devices in place","bucket":"perpetuating"},{"id":"form-344-8","text":"Widowed, lives alone, son in another state","bucket":"predisposing"},{"id":"form-344-9","text":"A neighbour found him on the floor after a night-long fall","bucket":"precipitating"},{"id":"form-344-10","text":"Cannot recall the falls or the gas incidents when asked","bucket":"perpetuating"},{"id":"form-344-11","text":"Clear, consistent values about home and independence","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Rao, 83, has moderate Alzheimer''s disease and the question is whether he can decide where to live. Capacity is specific to the decision and the time; he must understand, remember, weigh and communicate the information. He holds clear values about home, but cannot recall the falls or gas incidents, so he may not be able to weigh the risks. Dementia and living alone (predisposing) raise risk; the night-long fall (precipitating) forced the question. Poor recall of events, his son''s all-or-nothing plan and no support at home (perpetuating) narrow the options. His clear values and a willing neighbour (protective) open middle paths. Plan: a careful capacity assessment with help to understand, explore home care, alarms, gas safety and daily checks, involve him in the decision, and use a best-interests process only if he lacks capacity. His former role is a distractor.","hint":"An 83-year-old with dementia who wants to stay at home despite falls","tags":{"topic":"capacity","difficulty":5,"objective":"Formulate a capacity question in dementia, balancing safety and rights","exams":["md-psychiatry","mcp-entrance"],"module":"ethics-law","diagnosis":"Moderate Alzheimer''s disease with a decision-specific capacity question about where to live"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-345', 'Mrs Kamath: up four times a night and dozing all afternoon (insomnia in later life)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-345-1","text":"Long afternoon naps","bucket":"perpetuating"},{"id":"form-345-2","text":"Moved in with her son''s family and lost her own routine and garden","bucket":"precipitating"},{"id":"form-345-3","text":"Naps for two hours every afternoon","bucket":"presenting"},{"id":"form-345-4","text":"Goes to bed at 8 pm with nothing else to do","bucket":"perpetuating"},{"id":"form-345-5","text":"Overactive bladder","bucket":"predisposing"},{"id":"form-345-6","text":"She was a music teacher in Udupi","bucket":"distractor"},{"id":"form-345-7","text":"Age seventy-five, when sleep naturally becomes lighter","bucket":"predisposing"},{"id":"form-345-8","text":"Enjoys morning prayers and walks when she can","bucket":"protective"},{"id":"form-345-9","text":"Wakes three or four times a night and cannot get back to sleep, for a year","bucket":"presenting"},{"id":"form-345-10","text":"Healthy otherwise","bucket":"protective"},{"id":"form-345-11","text":"Drinks tea in the evening","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Kamath, 75, has insomnia in later life with night-time waking from her bladder and long daytime naps. Sleep becomes lighter with age and an overactive bladder wakes her (predisposing); moving into her son''s home (precipitating) took away her routine. Very early bedtime, long naps and evening tea (perpetuating) reduce the drive to sleep at night. Good health and her morning routine (protective) help. Plan: a later bedtime, a short nap at most, no tea after lunch, treatment for her bladder, daytime light and activity, and avoiding sleeping tablets that raise the risk of falls. Her former job is a distractor.","hint":"A 75-year-old who sleeps badly and naps for hours","tags":{"topic":"sleep","difficulty":1,"objective":"Sort later-life insomnia into the 5 Ps","exams":["cuet-pg","ma-semester","mcp-entrance"],"module":"lifespan","diagnosis":"Insomnia disorder in later life with nocturia and long daytime naps"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-346', 'Mrs Rizvi: the conversations she can no longer follow (depression with hearing loss)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-346-1","text":"Low mood, loss of interest and poor sleep for four months","bucket":"presenting"},{"id":"form-346-2","text":"Believes hearing aids are only for ''very old people''","bucket":"perpetuating"},{"id":"form-346-3","text":"Embarrassed when she answered a question wrongly at a wedding and people laughed","bucket":"precipitating"},{"id":"form-346-4","text":"Family speaks to her less because it is ''difficult''","bucket":"perpetuating"},{"id":"form-346-5","text":"Hearing loss for several years, untreated","bucket":"predisposing"},{"id":"form-346-6","text":"Widowed, lives with her son''s family","bucket":"predisposing"},{"id":"form-346-7","text":"Isolation reduces enjoyment and conversation","bucket":"perpetuating"},{"id":"form-346-8","text":"Avoids family gatherings and the mosque women''s group","bucket":"presenting"},{"id":"form-346-9","text":"Close bond with her granddaughter","bucket":"protective"},{"id":"form-346-10","text":"Physically healthy","bucket":"protective"},{"id":"form-346-11","text":"She lives in Lucknow","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Rizvi, 72, has a depressive episode linked to untreated hearing loss. Hearing loss in later life increases isolation and the risk of depression, and treating it can help mood. Years of hearing loss and widowhood (predisposing) raised her risk; embarrassment at a wedding (precipitating) led her to withdraw. Isolation, stigma about hearing aids and the family talking to her less (perpetuating) maintain the low mood. Her granddaughter and good health (protective) help. Plan: risk assessment, hearing test and aids, coaching the family to speak face to face, treat depression and help her return to her group. Lucknow is a distractor.","hint":"A 72-year-old who stopped going out as her hearing faded","tags":{"topic":"depression","difficulty":2,"objective":"Link sensory loss, isolation and depression in later life","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"depression","diagnosis":"Depressive episode in later life with untreated hearing loss"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-347', 'Mr Joshi: the evening raids on the fridge (binge eating disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-347-1","text":"Disgust and guilt afterwards; no vomiting or laxatives","bucket":"presenting"},{"id":"form-347-2","text":"Uses food to calm himself since his teens","bucket":"predisposing"},{"id":"form-347-3","text":"Eats very large amounts quickly, in secret, three times a week for a year, feeling out of control","bucket":"presenting"},{"id":"form-347-4","text":"He lives in Hyderabad","bucket":"distractor"},{"id":"form-347-5","text":"Starts a new strict diet each Monday, which leads to binges by Thursday","bucket":"perpetuating"},{"id":"form-347-6","text":"Shame stops him talking to his wife","bucket":"perpetuating"},{"id":"form-347-7","text":"Wife who has noticed and is supportive","bucket":"protective"},{"id":"form-347-8","text":"Long, stressful work hours","bucket":"perpetuating"},{"id":"form-347-9","text":"Strict crash diet before his sister''s wedding","bucket":"precipitating"},{"id":"form-347-10","text":"Teased about weight as a child","bucket":"predisposing"},{"id":"form-347-11","text":"Enjoys badminton","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Joshi, 38, has binge eating disorder: repeated episodes of eating large amounts with loss of control, at least weekly for months, with marked distress and no compensatory behaviour such as vomiting. Childhood teasing and using food to soothe (predisposing) raised his risk; a crash diet (precipitating) set off the binge cycle. Repeated strict diets, work stress and secrecy (perpetuating) keep it going, because restriction leads to hunger and binges. A supportive wife and badminton (protective) help. Plan: regular meals without strict dieting, CBT for binge eating, stress management and checking for depression and metabolic health. Hyderabad is a distractor.","hint":"A 38-year-old IT manager who eats large amounts in secret after work","tags":{"topic":"eating","difficulty":2,"objective":"Recognise binge eating disorder and its cycle with dieting","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"more-disorders","diagnosis":"Binge eating disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-348', 'Rohit: the runner who stopped eating (anorexia nervosa in a man)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-348-1","text":"Perfectionist and competitive since school","bucket":"predisposing"},{"id":"form-348-2","text":"Joined a running group that focused on low body fat","bucket":"precipitating"},{"id":"form-348-3","text":"Lost 12 kg in six months, now very underweight, and runs twice a day","bucket":"presenting"},{"id":"form-348-4","text":"Teased as a ''fat boy'' in childhood","bucket":"predisposing"},{"id":"form-348-5","text":"Intense fear of gaining weight and sees himself as ''flabby''","bucket":"presenting"},{"id":"form-348-6","text":"Exercises even when injured","bucket":"perpetuating"},{"id":"form-348-7","text":"Friends praise his ''fitness'', so the illness is missed","bucket":"perpetuating"},{"id":"form-348-8","text":"He studies engineering in Pune","bucket":"distractor"},{"id":"form-348-9","text":"Believes eating disorders only affect girls, so he will not accept help","bucket":"perpetuating"},{"id":"form-348-10","text":"Wants to keep running, which needs a healthy body","bucket":"protective"},{"id":"form-348-11","text":"Mother who noticed his dizziness and cold hands","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rohit, 22, has anorexia nervosa, restricting type: very low weight from restricted eating and excessive exercise, an intense fear of weight gain and a distorted body image. Anorexia in men is often missed because it is wrongly seen as a female illness, and it may show as compulsive exercise. Perfectionism and childhood teasing (predisposing) raised his risk; a running group focused on body fat (precipitating) began the restriction. Praise for fitness, exercising through injury and stigma about eating disorders in men (perpetuating) maintain it. His mother''s concern and his wish to keep running (protective) can motivate treatment. Plan: medical checks, nutritional rehabilitation, limits on exercise and specialist therapy. His course is a distractor.","hint":"A 22-year-old marathon runner who has lost 12 kg","tags":{"topic":"eating","difficulty":3,"objective":"Recognise anorexia nervosa in a man, where it is often missed","exams":["mcp-entrance","md-psychiatry"],"module":"more-disorders","diagnosis":"Anorexia nervosa, restricting type"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-349', 'Nikita: skipping insulin to stay thin (eating disorder with insulin omission in type 1 diabetes)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-349-1","text":"Admits skipping insulin to lose weight; very high long-term sugar readings","bucket":"presenting"},{"id":"form-349-2","text":"Has early signs of eye damage, which frightens her","bucket":"protective"},{"id":"form-349-3","text":"Hides blood sugar readings from her doctor","bucket":"perpetuating"},{"id":"form-349-4","text":"Weight loss from skipping insulin feels rewarding","bucket":"perpetuating"},{"id":"form-349-5","text":"Mother very anxious about weight","bucket":"predisposing"},{"id":"form-349-6","text":"Three admissions in a year with dangerously high sugar and ketones","bucket":"presenting"},{"id":"form-349-7","text":"Close friend who knows and wants to help","bucket":"protective"},{"id":"form-349-8","text":"Gained weight after starting insulin properly and was teased at college","bucket":"precipitating"},{"id":"form-349-9","text":"She studies fashion design","bucket":"distractor"},{"id":"form-349-10","text":"Type 1 diabetes since age eight, with constant focus on food and numbers","bucket":"predisposing"},{"id":"form-349-11","text":"Diabetes team focuses only on sugar numbers, not mood or eating","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Nikita, 19, has an eating disorder with deliberate insulin omission to control weight, a dangerous pattern in type 1 diabetes. Without insulin, sugar spills into urine and weight falls, but ketoacidosis, eye, kidney and nerve damage follow, and death rates are raised. Years of focus on food and numbers and an anxious mother (predisposing) raised her risk; weight gain after correct insulin and teasing (precipitating) started it. The reward of weight loss, hiding readings and a team focused only on numbers (perpetuating) maintain it. A caring friend and her fear of eye damage (protective) can motivate change. Plan: joint diabetes and eating disorder care, gradual safe insulin restoration, ask about mood and suicide, and family work. Her course is a distractor.","hint":"A 19-year-old with type 1 diabetes and repeated hospital visits for high sugar","tags":{"topic":"eating","difficulty":5,"objective":"Build a full formulation of insulin omission for weight control and its dangers","exams":["md-psychiatry","mcp-entrance"],"module":"more-disorders","diagnosis":"Eating disorder with deliberate insulin omission in type 1 diabetes (other specified feeding or eating disorder)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-350', 'Mrs Kapoor: awake at two, eating at three (night eating syndrome)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-350-1","text":"Mother had similar eating habits","bucket":"predisposing"},{"id":"form-350-2","text":"Regular contact with her sister","bucket":"protective"},{"id":"form-350-3","text":"Eats little at breakfast and takes a large share of her food after dinner","bucket":"presenting"},{"id":"form-350-4","text":"Anxious and low in mood for years","bucket":"predisposing"},{"id":"form-350-5","text":"Wakes two or three times a night and must eat to fall asleep again, fully aware and remembering it","bucket":"presenting"},{"id":"form-350-6","text":"Willing to keep a food and sleep diary","bucket":"protective"},{"id":"form-350-7","text":"Weight gain makes her feel worse about herself","bucket":"perpetuating"},{"id":"form-350-8","text":"Believes she cannot sleep without eating","bucket":"perpetuating"},{"id":"form-350-9","text":"Loneliness at night","bucket":"perpetuating"},{"id":"form-350-10","text":"Husband transferred abroad for work six months ago","bucket":"precipitating"},{"id":"form-350-11","text":"Eating while asleep with no memory of it the next day","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Kapoor, 45, has night eating syndrome: repeated night-time eating after waking, with awareness and memory of it, and a large share of daily food eaten after the evening meal. Eating while asleep with no memory, the distractor, would suggest a sleep-related eating disorder, a different condition often linked to sleeping tablets. Long-standing anxiety and low mood and a family pattern (predisposing) raise her risk; her husband''s move abroad (precipitating) left her lonely at night. Loneliness, beliefs that she needs food to sleep and weight gain (perpetuating) maintain it. Her sister and her willingness to keep a diary (protective) help. Plan: regular daytime meals, CBT, treatment of low mood and sleep routines.","hint":"A 45-year-old who wakes at night and cannot sleep again until she eats","tags":{"topic":"eating","difficulty":3,"objective":"Recognise night eating syndrome and tell it apart from sleep-related eating","exams":["mcp-entrance","md-psychiatry"],"module":"more-disorders","diagnosis":"Night eating syndrome"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-351', 'Sneha: the illness came back with the pregnancy (anorexia nervosa relapse in pregnancy)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-351-1","text":"Anorexia nervosa at 17, treated, with full recovery for eight years","bucket":"predisposing"},{"id":"form-351-2","text":"Pregnancy and comments from relatives about ''getting fat''","bucket":"precipitating"},{"id":"form-351-3","text":"Exercises secretly to ''control'' the weight gain","bucket":"perpetuating"},{"id":"form-351-4","text":"Fear of losing control of her body","bucket":"perpetuating"},{"id":"form-351-5","text":"Has not told her obstetrician about her past illness","bucket":"perpetuating"},{"id":"form-351-6","text":"Perfectionist temperament","bucket":"predisposing"},{"id":"form-351-7","text":"Wants a healthy baby","bucket":"protective"},{"id":"form-351-8","text":"Husband who knows her history and is supportive","bucket":"protective"},{"id":"form-351-9","text":"Severe nausea and vomiting with weight loss, with no fear of weight gain","bucket":"distractor"},{"id":"form-351-10","text":"Distressed by her growing belly and weighing herself daily","bucket":"presenting"},{"id":"form-351-11","text":"Not gaining weight at four months pregnant and restricting food","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sneha, 28, has a relapse of anorexia nervosa in pregnancy: restricting food, distress about weight gain and daily weighing, with poor weight gain for the baby. Pregnancy can trigger relapse in women with past eating disorders because of body changes and loss of control. Severe vomiting without fear of weight gain, the distractor, would suggest hyperemesis instead. Past anorexia and perfectionism (predisposing) raise her risk; the pregnancy and relatives'' comments (precipitating) set it off. Hiding her history, secret exercise and fear of losing control (perpetuating) maintain it. Her wish for a healthy baby and a supportive husband (protective) are strong levers. Plan: tell the obstetric team, joint care with an eating disorder service, a meal plan, careful monitoring of the baby''s growth and support after birth.","hint":"A 28-year-old with past anorexia who is restricting food at four months pregnant","tags":{"topic":"eating","difficulty":4,"objective":"Formulate an eating disorder relapse in pregnancy and the risks to mother and baby","exams":["md-psychiatry","mcp-entrance"],"module":"more-disorders","diagnosis":"Anorexia nervosa, relapse in pregnancy"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-352', 'Aarti: bringing food back up and chewing again (rumination disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-352-1","text":"Normal endoscopy and tests","bucket":"protective"},{"id":"form-352-2","text":"Long history of stomach discomfort","bucket":"predisposing"},{"id":"form-352-3","text":"Anxious since childhood","bucket":"predisposing"},{"id":"form-352-4","text":"Began during a stressful hostel move, after a stomach infection","bucket":"precipitating"},{"id":"form-352-5","text":"Many tests and acid tablets without improvement","bucket":"perpetuating"},{"id":"form-352-6","text":"Eager to try a breathing technique","bucket":"protective"},{"id":"form-352-7","text":"Unaware that the habit uses her stomach muscles","bucket":"perpetuating"},{"id":"form-352-8","text":"Brings food back up into her mouth without effort within minutes of most meals, for eight months","bucket":"presenting"},{"id":"form-352-9","text":"Self-induced vomiting after binges to control weight","bucket":"distractor"},{"id":"form-352-10","text":"Embarrassment leads her to eat alone","bucket":"perpetuating"},{"id":"form-352-11","text":"Re-chews or spits it out; no nausea and no concern about weight","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Aarti, 20, has rumination disorder: repeated effortless bringing back of food after meals, which is then re-chewed or spat out, without nausea, and not due to a stomach disease. Self-induced vomiting after binges, the distractor, would point to bulimia nervosa and does not fit. An anxious temperament and long-standing stomach discomfort (predisposing) raised her risk; a stressful move after a stomach infection (precipitating) started it. Repeated tests and acid tablets, eating alone and not knowing that the behaviour is a learned muscle habit (perpetuating) maintain it. Normal tests and her eagerness (protective) help. Plan: explain the habit, teach diaphragmatic breathing after meals to compete with the habit, and manage anxiety.","hint":"A 20-year-old who effortlessly regurgitates food after meals","tags":{"topic":"eating","difficulty":3,"objective":"Recognise rumination disorder and tell it apart from vomiting in bulimia","exams":["mcp-entrance","md-psychiatry"],"module":"more-disorders","diagnosis":"Rumination disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-353', 'Vicky: never big enough (body dysmorphic disorder with muscle dysmorphia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-353-1","text":"Believes his body is small and weak despite being very muscular","bucket":"presenting"},{"id":"form-353-2","text":"Bullied for being thin as a teenager","bucket":"predisposing"},{"id":"form-353-3","text":"Trains four hours a day, checks mirrors constantly and avoids the beach","bucket":"presenting"},{"id":"form-353-4","text":"Ex-girlfriend compared him to a film star","bucket":"precipitating"},{"id":"form-353-5","text":"Skips work to train","bucket":"perpetuating"},{"id":"form-353-6","text":"Compares himself with fitness influencers","bucket":"perpetuating"},{"id":"form-353-7","text":"Sister who has raised concern","bucket":"protective"},{"id":"form-353-8","text":"Distress only from eating, with no concern about muscle size","bucket":"distractor"},{"id":"form-353-9","text":"Uses anabolic steroids and strict diets","bucket":"perpetuating"},{"id":"form-353-10","text":"Perfectionist temperament","bucket":"predisposing"},{"id":"form-353-11","text":"Insight that his life has become narrow","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Vicky, 25, has body dysmorphic disorder with muscle dysmorphia: a preoccupation that his body is too small or not muscular enough, despite being very muscular, with repetitive mirror-checking, excessive training and avoidance. Bullying for being thin and perfectionism (predisposing) raised his risk; his ex-girlfriend''s comparison (precipitating) sharpened the preoccupation. Steroids, social media comparison and skipping work (perpetuating) maintain it and add physical risks. His sister''s concern and partial insight (protective) help. The distractor, distress about eating without muscle concern, would point to an eating disorder. Plan: CBT for body dysmorphic disorder, an SSRI, safe stopping of steroids with medical review and assessment of suicide risk, which is raised in this condition.","hint":"A 25-year-old bodybuilder who thinks he looks tiny","tags":{"topic":"ocd","difficulty":4,"objective":"Recognise muscle dysmorphia as a form of body dysmorphic disorder","exams":["md-psychiatry","mcp-entrance"],"module":"ocd","diagnosis":"Body dysmorphic disorder with muscle dysmorphia"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-354', 'Mr Baig: tired, low and snoring like a train (obstructive sleep apnoea behind low mood)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-354-1","text":"Low mood, poor concentration and morning headaches for a year","bucket":"presenting"},{"id":"form-354-2","text":"High blood pressure","bucket":"predisposing"},{"id":"form-354-3","text":"Very sleepy in the day, falls asleep while reading and once at a traffic signal","bucket":"presenting"},{"id":"form-354-4","text":"Wife who noticed the breathing pauses","bucket":"protective"},{"id":"form-354-5","text":"Gained 10 kg after a knee injury stopped his walks","bucket":"precipitating"},{"id":"form-354-6","text":"Treated with an antidepressant that made him sleepier","bucket":"perpetuating"},{"id":"form-354-7","text":"Wife says he snores loudly and stops breathing at night","bucket":"perpetuating"},{"id":"form-354-8","text":"Willing to have a sleep study","bucket":"protective"},{"id":"form-354-9","text":"Drinks two pegs of whisky every night to sleep","bucket":"perpetuating"},{"id":"form-354-10","text":"Overweight with a thick neck","bucket":"predisposing"},{"id":"form-354-11","text":"Low mood with early waking and no snoring or daytime sleepiness","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Baig, 52, has obstructive sleep apnoea with depressive symptoms: loud snoring, breathing pauses seen by his wife, morning headaches and severe daytime sleepiness. Untreated sleep apnoea can cause low mood and poor concentration and is dangerous when driving. Being overweight with a thick neck and high blood pressure (predisposing) raise his risk; weight gain after his injury (precipitating) worsened it. Night-time alcohol, which relaxes the throat, and a sedating antidepressant (perpetuating) make it worse. The distractor of early waking without snoring or sleepiness would fit depression alone. His wife''s observation and his willingness for a sleep study (protective) help. Plan: sleep study, breathing machine treatment, weight loss, stop evening alcohol, review the antidepressant and advise against driving while sleepy.","hint":"A 52-year-old with daytime sleepiness and low mood who snores loudly","tags":{"topic":"sleep","difficulty":4,"objective":"Recognise sleep apnoea as a cause of tiredness and low mood","exams":["md-psychiatry","mcp-entrance"],"module":"more-disorders","diagnosis":"Obstructive sleep apnoea with depressive symptoms"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-355', 'Mrs Pillai: legs that will not stay still at night (restless legs syndrome)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-355-1","text":"Started an antidepressant for low mood six months ago, after which symptoms worsened","bucket":"precipitating"},{"id":"form-355-2","text":"Mother had similar symptoms","bucket":"predisposing"},{"id":"form-355-3","text":"She lives in Kollam","bucket":"distractor"},{"id":"form-355-4","text":"Poor sleep worsens her mood","bucket":"perpetuating"},{"id":"form-355-5","text":"Heavy periods for years before menopause","bucket":"predisposing"},{"id":"form-355-6","text":"Symptoms often respond to iron and changes in medicines","bucket":"protective"},{"id":"form-355-7","text":"Evening tea and long periods of sitting","bucket":"perpetuating"},{"id":"form-355-8","text":"Low iron stores not checked","bucket":"perpetuating"},{"id":"form-355-9","text":"Relieved by walking around; poor sleep for a year","bucket":"presenting"},{"id":"form-355-10","text":"Supportive daughter","bucket":"protective"},{"id":"form-355-11","text":"Crawling feelings deep in her legs with an urge to move them, in the evening and at night","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Pillai, 58, has restless legs syndrome: an urge to move the legs with unpleasant sensations, worse at rest and in the evening, relieved by movement. It often runs in families and is linked to low iron. Years of heavy periods and a family history (predisposing) raise her risk; an antidepressant, which can worsen restless legs (precipitating), coincided with worsening. Unchecked iron stores, evening tea and inactivity (perpetuating) maintain it, and poor sleep lowers her mood. Treatable causes and her daughter''s support (protective) help. Plan: check ferritin and give iron if low, review the antidepressant, reduce caffeine, regular exercise and leg stretching. Kollam is a distractor.","hint":"A 58-year-old who cannot sleep because of crawling feelings in her legs","tags":{"topic":"sleep","difficulty":2,"objective":"Recognise restless legs syndrome and its link to low iron","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"more-disorders","diagnosis":"Restless legs syndrome with iron deficiency"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-356', 'Arjun: three in the morning, every morning (delayed sleep phase in a student)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-356-1","text":"Misses morning lectures and feels exhausted on college days","bucket":"presenting"},{"id":"form-356-2","text":"Bright screens late at night","bucket":"perpetuating"},{"id":"form-356-3","text":"He studies commerce in Delhi","bucket":"distractor"},{"id":"form-356-4","text":"Cannot fall asleep before 3 am even when he tries; sleeps well until 11 am when allowed","bucket":"presenting"},{"id":"form-356-5","text":"Sleeps in on weekends","bucket":"perpetuating"},{"id":"form-356-6","text":"Drinks energy drinks in the evening","bucket":"perpetuating"},{"id":"form-356-7","text":"Father has the same pattern","bucket":"predisposing"},{"id":"form-356-8","text":"Motivated to keep his scholarship","bucket":"protective"},{"id":"form-356-9","text":"Always a ''night owl'' since his teens","bucket":"predisposing"},{"id":"form-356-10","text":"Long online gaming sessions during the summer holidays","bucket":"precipitating"},{"id":"form-356-11","text":"Sleeps well when allowed his own timing","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Arjun, 20, has a delayed sleep-wake phase disorder: his body clock runs late, so he cannot fall asleep until very late and struggles to wake early, though his sleep is normal when he can follow his own timing. A lifelong night-owl tendency and a father with the same pattern (predisposing) underlie it; holiday gaming (precipitating) pushed it later. Screens at night, sleeping in on weekends and evening energy drinks (perpetuating) keep the clock late. Good sleep at his own timing and his scholarship goals (protective) help. Plan: a fixed wake time every day, bright morning light, no screens and caffeine late, and possibly low-dose melatonin taken early in the evening. His course is a distractor.","hint":"A 20-year-old who cannot fall asleep before 3 am and misses morning lectures","tags":{"topic":"sleep","difficulty":2,"objective":"Recognise a delayed body clock and how to shift it","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"lifespan","diagnosis":"Delayed sleep-wake phase disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-357', 'Mr Bhatia: two pegs to sleep, then wide awake at three (insomnia maintained by alcohol)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-357-1","text":"Falls asleep quickly after drinking but wakes at 3 am, sweating and unable to sleep again, for a year","bucket":"presenting"},{"id":"form-357-2","text":"Light sleeper all his life","bucket":"predisposing"},{"id":"form-357-3","text":"Not yet dependent and willing to cut down","bucket":"protective"},{"id":"form-357-4","text":"He runs a jewellery shop in Jaipur","bucket":"distractor"},{"id":"form-357-5","text":"Tired and irritable in the day","bucket":"presenting"},{"id":"form-357-6","text":"Works long hours in a stressful business","bucket":"predisposing"},{"id":"form-357-7","text":"Business losses last year, when he began drinking to sleep","bucket":"precipitating"},{"id":"form-357-8","text":"Lies in bed worrying when awake","bucket":"perpetuating"},{"id":"form-357-9","text":"Has increased from two to four pegs","bucket":"perpetuating"},{"id":"form-357-10","text":"Alcohol breaks up sleep in the second half of the night","bucket":"perpetuating"},{"id":"form-357-11","text":"Wife who supports him","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Bhatia, 49, has insomnia kept going by using alcohol to sleep. Alcohol helps sleep come quickly but breaks up sleep later in the night, causing early waking, sweating and poor quality sleep, so it worsens the problem. A light-sleeping nature and work stress (predisposing) raise his vulnerability; business losses (precipitating) started his night drinking. Fragmented sleep from alcohol, rising amounts and worrying in bed (perpetuating) maintain it. Not yet being dependent and a supportive wife (protective) help. Plan: explain the effect of alcohol on sleep, stop or cut down drinking, CBT for insomnia and manage business worries. The jewellery shop is a distractor.","hint":"A 49-year-old who drinks to sleep but wakes every night","tags":{"topic":"sleep","difficulty":3,"objective":"Formulate insomnia kept going by using alcohol as a sleep aid","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"substance","diagnosis":"Insomnia disorder maintained by alcohol use"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-358', 'Sameer: found in the kitchen at midnight with no memory (sleepwalking in an adult)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-358-1","text":"Episodes are calm, without injury","bucket":"protective"},{"id":"form-358-2","text":"Flatmate tries to wake him suddenly","bucket":"perpetuating"},{"id":"form-358-3","text":"No memory of it the next morning","bucket":"presenting"},{"id":"form-358-4","text":"Sleepwalked as a child","bucket":"predisposing"},{"id":"form-358-5","text":"Drinks alcohol at weekends","bucket":"perpetuating"},{"id":"form-358-6","text":"Willing to improve his sleep routine","bucket":"protective"},{"id":"form-358-7","text":"Found walking around the flat at night, eyes open, two or three times a month","bucket":"presenting"},{"id":"form-358-8","text":"Irregular sleep timing","bucket":"perpetuating"},{"id":"form-358-9","text":"He works in a call centre in Gurugram","bucket":"distractor"},{"id":"form-358-10","text":"Months of sleep loss from night shifts and exam preparation","bucket":"precipitating"},{"id":"form-358-11","text":"Father also sleepwalked","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sameer, 26, has sleepwalking, a disorder of arousal from deep non-dream sleep: he walks with eyes open during the early night and has no memory of it. Sleepwalking as a child and a father who sleepwalked (predisposing) point to a family tendency; sleep loss from night shifts and studying (precipitating) increased episodes. Weekend alcohol, irregular sleep and being woken suddenly (perpetuating) can trigger more episodes. Calm episodes and his willingness to change (protective) help. Plan: regular sleep, enough sleep, avoid alcohol, make the flat safe by locking doors and windows, and guide him back to bed gently rather than waking him. His job is a distractor.","hint":"A 26-year-old whose flatmate finds him walking at night","tags":{"topic":"sleep","difficulty":1,"objective":"Sort adult sleepwalking into the 5 Ps","exams":["cuet-pg","ma-semester","mcp-entrance"],"module":"lifespan","diagnosis":"Non-rapid eye movement sleep arousal disorder, sleepwalking type"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-359', 'Mrs Desai: certain she never sleeps (paradoxical insomnia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-359-1","text":"Anxious temperament","bucket":"predisposing"},{"id":"form-359-2","text":"Open to seeing the results of the study","bucket":"protective"},{"id":"form-359-3","text":"Loud snoring with breathing pauses at night","bucket":"distractor"},{"id":"form-359-4","text":"Menopause and night sweats a year ago","bucket":"precipitating"},{"id":"form-359-5","text":"Catastrophic beliefs that lack of sleep will make her ill","bucket":"perpetuating"},{"id":"form-359-6","text":"Health worries since her sister''s illness","bucket":"predisposing"},{"id":"form-359-7","text":"Daytime function is better than she expects","bucket":"protective"},{"id":"form-359-8","text":"Sleep study shows about six hours of normal sleep","bucket":"presenting"},{"id":"form-359-9","text":"Has asked several doctors for stronger sleeping tablets","bucket":"perpetuating"},{"id":"form-359-10","text":"Clock-watching through the night","bucket":"perpetuating"},{"id":"form-359-11","text":"Says she has slept ''not even one hour'' for months","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Desai, 55, has paradoxical insomnia: a strong belief that she barely sleeps, while a sleep study shows mostly normal sleep. Her distress is real, but sleep is underestimated because of anxious, alert awareness during light sleep. An anxious temperament and health worries (predisposing) raise her risk; menopausal night sweats (precipitating) began her sleep worry. Clock-watching, catastrophic beliefs about sleep loss and pursuit of stronger tablets (perpetuating) maintain it. Her better than expected daytime function and openness to the results (protective) help. The distractor of snoring with breathing pauses would suggest sleep apnoea. Plan: share the sleep study gently, CBT for insomnia, remove the clock, avoid escalating sleeping tablets and manage menopausal symptoms.","hint":"A 55-year-old who says she has not slept for months, but the sleep study disagrees","tags":{"topic":"sleep","difficulty":4,"objective":"Understand insomnia where sleep is badly underestimated","exams":["md-psychiatry","mcp-entrance"],"module":"more-disorders","diagnosis":"Paradoxical insomnia (sleep state misperception)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-360', 'Vivek: always too soon (premature ejaculation)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-360-1","text":"Ejaculates within about a minute of penetration on almost every occasion since his first sexual experience","bucket":"presenting"},{"id":"form-360-2","text":"He works in a bank in Indore","bucket":"distractor"},{"id":"form-360-3","text":"Anxious temperament","bucket":"predisposing"},{"id":"form-360-4","text":"Buys herbal oils from roadside sellers","bucket":"perpetuating"},{"id":"form-360-5","text":"Wife is patient and caring","bucket":"protective"},{"id":"form-360-6","text":"Distressed and avoiding intimacy with his wife","bucket":"presenting"},{"id":"form-360-7","text":"Erections are normal","bucket":"protective"},{"id":"form-360-8","text":"Performance anxiety builds before every attempt","bucket":"perpetuating"},{"id":"form-360-9","text":"Marriage six months ago and pressure to have a child soon","bucket":"precipitating"},{"id":"form-360-10","text":"Wife and he do not talk about it","bucket":"perpetuating"},{"id":"form-360-11","text":"Learned about sex from pornography and peers","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Vivek, 27, has lifelong premature ejaculation: ejaculation within about a minute of penetration on almost all occasions since his first experiences, causing distress. It is common and treatable. An anxious nature and learning about sex from pornography and peers (predisposing) shape unrealistic expectations; marriage and pressure for a child (precipitating) increased anxiety. Performance anxiety, ineffective herbal oils and not talking about it (perpetuating) keep it going. Normal erections and a caring wife (protective) help. Plan: education, stop-start or squeeze techniques practised as a couple, anxiety reduction and, if needed, medicine. The bank is a distractor.","hint":"A 27-year-old newly married man who ejaculates within a minute","tags":{"topic":"sexual","difficulty":1,"objective":"Sort premature ejaculation into the 5 Ps","exams":["cuet-pg","ma-semester","mcp-entrance"],"module":"more-disorders","diagnosis":"Premature (early) ejaculation, lifelong"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-361', 'Mrs Rachna: no desire since the baby (female sexual interest and arousal disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-361-1","text":"Intercourse is painful and she avoids it","bucket":"presenting"},{"id":"form-361-2","text":"Husband willing to come for joint sessions","bucket":"protective"},{"id":"form-361-3","text":"Good relationship otherwise","bucket":"protective"},{"id":"form-361-4","text":"Breastfeeding causes vaginal dryness","bucket":"perpetuating"},{"id":"form-361-5","text":"Exhaustion from night feeds and no help at home","bucket":"perpetuating"},{"id":"form-361-6","text":"Husband''s irritation makes her feel guilty","bucket":"perpetuating"},{"id":"form-361-7","text":"Anxious temperament","bucket":"predisposing"},{"id":"form-361-8","text":"She lives in Ludhiana","bucket":"distractor"},{"id":"form-361-9","text":"Difficult delivery with stitches one year ago","bucket":"precipitating"},{"id":"form-361-10","text":"Little interest in sex and no arousal for a year since her baby was born","bucket":"presenting"},{"id":"form-361-11","text":"Strict upbringing in which sex was never discussed","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Rachna, 32, has acquired female sexual interest/arousal disorder with pain after childbirth. A strict upbringing and anxiety (predisposing) make it hard to talk about sex; a difficult delivery with stitches (precipitating) began the pain and loss of desire. Vaginal dryness during breastfeeding, exhaustion and her husband''s irritation (perpetuating) maintain it. A willing husband and a good relationship (protective) help. Plan: gynaecology check for pain, lubricants, sharing night feeds, screening for postnatal depression and couple therapy with sensate focus. Ludhiana is a distractor.","hint":"A 32-year-old with low desire and pain after childbirth","tags":{"topic":"sexual","difficulty":3,"objective":"Formulate low sexual interest in a woman with physical, mood and relationship factors","exams":["mcp-entrance","md-psychiatry"],"module":"more-disorders","diagnosis":"Female sexual interest/arousal disorder, acquired, with pain after childbirth"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-362', 'Shalini and Ravi: married a year and not yet together (genito-pelvic pain and penetration disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-362-1","text":"Painful attempt on the wedding night","bucket":"precipitating"},{"id":"form-362-2","text":"Pressure from in-laws for a grandchild","bucket":"perpetuating"},{"id":"form-362-3","text":"They live in Nashik","bucket":"distractor"},{"id":"form-362-4","text":"Fear of pain leads to muscle tightening, which causes pain","bucket":"perpetuating"},{"id":"form-362-5","text":"Loving, patient husband","bucket":"protective"},{"id":"form-362-6","text":"Anxious personality","bucket":"predisposing"},{"id":"form-362-7","text":"Told as a girl that the first time is ''very painful and bloody''","bucket":"predisposing"},{"id":"form-362-8","text":"Both feel too ashamed to see a doctor until now","bucket":"perpetuating"},{"id":"form-362-9","text":"Marriage of a year not consummated because her muscles tighten and she feels intense fear","bucket":"presenting"},{"id":"form-362-10","text":"Both enjoy other forms of closeness","bucket":"protective"},{"id":"form-362-11","text":"Enjoys kissing and touching, but panics at any attempt at penetration","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Shalini, 24, has genito-pelvic pain/penetration disorder, also called vaginismus: fear of penetration with involuntary tightening of the pelvic floor, preventing intercourse. It is common in India in unconsummated marriages and responds well to treatment. Frightening messages in childhood and anxiety (predisposing) set the stage; a painful wedding night (precipitating) began the fear. The fear, tightening and pain cycle, family pressure and shame (perpetuating) maintain it. A patient husband and enjoyment of other closeness (protective) help. Plan: education about the body, relaxation, gradual self-touch or dilator practice, sensate focus as a couple and reducing family pressure. Nashik is a distractor.","hint":"A 24-year-old woman whose marriage has not been consummated because of fear and tightening","tags":{"topic":"sexual","difficulty":2,"objective":"Recognise genito-pelvic pain and penetration disorder and its treatment","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"more-disorders","diagnosis":"Genito-pelvic pain/penetration disorder (vaginismus)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-363', 'Ankit: well on the tablets but not in the bedroom (antidepressant-induced sexual dysfunction)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-363-1","text":"Has been skipping doses on weekends to ''fix'' it, causing dizziness","bucket":"perpetuating"},{"id":"form-363-2","text":"Embarrassed to talk about sex","bucket":"predisposing"},{"id":"form-363-3","text":"Depression has improved well","bucket":"presenting"},{"id":"form-363-4","text":"Good response of mood to treatment","bucket":"protective"},{"id":"form-363-5","text":"Doctor who asks about side effects","bucket":"protective"},{"id":"form-363-6","text":"Wife thinks he no longer finds her attractive","bucket":"perpetuating"},{"id":"form-363-7","text":"Has not told his doctor","bucket":"perpetuating"},{"id":"form-363-8","text":"He sells cars in Pune","bucket":"distractor"},{"id":"form-363-9","text":"Delayed ejaculation and low desire since starting sertraline four months ago","bucket":"presenting"},{"id":"form-363-10","text":"Recurrent depression","bucket":"predisposing"},{"id":"form-363-11","text":"Dose increased two months ago","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ankit, 33, has sexual side effects from sertraline: delayed ejaculation and low desire that began with the medicine and worsened with a higher dose. SSRIs commonly cause this, and people often stop treatment without telling their doctor. Recurrent depression and embarrassment about sex (predisposing) shape the problem; the dose increase (precipitating) worsened it. Skipping weekend doses, which causes discontinuation symptoms and risks relapse, his wife''s hurt and not telling his doctor (perpetuating) add harm. Good mood response and a doctor who asks (protective) help. Plan: discuss openly, avoid skipping doses, consider a lower dose, switch to a medicine with fewer sexual effects or add a treatment, and explain to his wife. His job is a distractor.","hint":"A 33-year-old on sertraline with delayed ejaculation and low desire","tags":{"topic":"sexual","difficulty":2,"objective":"Recognise sexual side effects of an antidepressant and the risk of stopping","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"antidepressants","diagnosis":"Medicine-induced sexual dysfunction (SSRI)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-364', 'Mr Saxena: losing erections for two years (erectile dysfunction from diabetes, not anxiety alone)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-364-1","text":"Started a beta-blocker for blood pressure a year ago","bucket":"precipitating"},{"id":"form-364-2","text":"Anxiety about failing adds to the problem","bucket":"perpetuating"},{"id":"form-364-3","text":"Gradual loss of erections over two years in all situations, including no morning erections","bucket":"presenting"},{"id":"form-364-4","text":"Sugar remains poorly controlled","bucket":"perpetuating"},{"id":"form-364-5","text":"Poorly controlled diabetes for twelve years","bucket":"predisposing"},{"id":"form-364-6","text":"Supportive wife","bucket":"protective"},{"id":"form-364-7","text":"Embarrassed to raise it with his diabetes doctor","bucket":"perpetuating"},{"id":"form-364-8","text":"Now anxious before every attempt","bucket":"presenting"},{"id":"form-364-9","text":"Sudden onset after a quarrel, with normal morning erections","bucket":"distractor"},{"id":"form-364-10","text":"Treatable with medicines and better control","bucket":"protective"},{"id":"form-364-11","text":"Smokes and has high blood pressure","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Saxena, 55, has erectile disorder mainly due to diabetes and blood vessel disease, now with secondary performance anxiety. Gradual loss of erections in all situations, including loss of morning erections, points to a physical cause; sudden onset after a quarrel with normal morning erections, the distractor, would suggest a mainly psychological cause. Poorly controlled diabetes, smoking and high blood pressure (predisposing) damage nerves and vessels; a beta-blocker (precipitating) may have worsened it. Anxiety, poor sugar control and embarrassment (perpetuating) maintain it. Erectile problems can also signal heart disease, so a heart check is wise. A supportive wife and treatable causes (protective) help. Plan: improve diabetes and blood pressure control, review the beta-blocker, stop smoking, consider medicine and address anxiety.","hint":"A 55-year-old with diabetes and gradually failing erections","tags":{"topic":"sexual","difficulty":4,"objective":"Tell physical erectile dysfunction apart from performance anxiety","exams":["md-psychiatry","mcp-entrance"],"module":"more-disorders","diagnosis":"Erectile disorder due mainly to diabetes and vascular disease, with secondary performance anxiety"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-365', 'Mr Kartikeyan: trying for a baby but unable to finish (delayed ejaculation)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-365-1","text":"Distressed because they are trying to conceive","bucket":"presenting"},{"id":"form-365-2","text":"Loving relationship","bucket":"protective"},{"id":"form-365-3","text":"Families ask often about a baby","bucket":"perpetuating"},{"id":"form-365-4","text":"Normal semen test","bucket":"protective"},{"id":"form-365-5","text":"Sex has become a ''task'' on scheduled days","bucket":"perpetuating"},{"id":"form-365-6","text":"Fertility clinic advised timed intercourse on certain days","bucket":"precipitating"},{"id":"form-365-7","text":"Cannot ejaculate during intercourse for a year, though he can during masturbation","bucket":"presenting"},{"id":"form-365-8","text":"Fear of failing on those days","bucket":"perpetuating"},{"id":"form-365-9","text":"Frequent use of pornography with a particular style of masturbation","bucket":"predisposing"},{"id":"form-365-10","text":"He is a lecturer in Madurai","bucket":"distractor"},{"id":"form-365-11","text":"Rigid, controlled personality","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Kartikeyan, 34, has acquired delayed ejaculation: inability to ejaculate during intercourse, though he can during masturbation. A controlled personality and a habit of a particular masturbation style with pornography (predisposing) may make intercourse less stimulating; timed intercourse for fertility (precipitating) turned sex into a task. Pressure on scheduled days, fear of failure and family questions (perpetuating) maintain it. A loving relationship and a normal semen test (protective) help, and assisted insemination can allow conception while therapy continues. Plan: check medicines and health, reduce performance pressure, change masturbation habits, sensate focus and fertility options. His job is a distractor.","hint":"A 34-year-old who cannot ejaculate during intercourse while trying to conceive","tags":{"topic":"sexual","difficulty":3,"objective":"Formulate delayed ejaculation with pressure around fertility","exams":["mcp-entrance","md-psychiatry"],"module":"more-disorders","diagnosis":"Delayed ejaculation, acquired"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-366', 'Aryan: the bride his family has chosen (a transgender man facing marriage pressure)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-366-1","text":"Supportive older cousin","bucket":"protective"},{"id":"form-366-2","text":"Hides his identity at home to keep the peace","bucket":"perpetuating"},{"id":"form-366-3","text":"Conservative family who see it as a ''phase''","bucket":"predisposing"},{"id":"form-366-4","text":"Gender identity clear since childhood","bucket":"predisposing"},{"id":"form-366-5","text":"Interested in a transgender support group","bucket":"protective"},{"id":"form-366-6","text":"Lifelong identity as a man, assigned female at birth, with distress about his body","bucket":"presenting"},{"id":"form-366-7","text":"Low mood, poor sleep and panic for two months as his family arranges his marriage to a man","bucket":"presenting"},{"id":"form-366-8","text":"He likes trekking","bucket":"distractor"},{"id":"form-366-9","text":"No contact with others like him","bucket":"perpetuating"},{"id":"form-366-10","text":"Family fixed a wedding date without his consent","bucket":"precipitating"},{"id":"form-366-11","text":"Steady job as a software tester","bucket":"protective"},{"id":"form-366-12","text":"Fear of violence if he refuses","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Aryan, 27, is a transgender man with gender dysphoria and an adjustment disorder with low mood. Being transgender is not a mental illness; his distress comes from the mismatch with his body and, now, from family pressure to marry a man. A clear lifelong identity in a conservative family (predisposing) underlies his struggle; a wedding fixed without his consent (precipitating) triggered his symptoms. Hiding his identity, fear of violence and isolation (perpetuating) maintain them. His job, a cousin''s support and interest in a support group (protective) are strengths. Plan: assess suicide risk and safety at home, support for his rights, including under the transgender persons law, connection with community groups and therapy. Trekking is a distractor.","hint":"A 27-year-old transgender man whose family is arranging his marriage to a man","tags":{"topic":"gender","difficulty":3,"objective":"Formulate distress in a transgender adult without treating identity as illness","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"more-disorders","diagnosis":"Gender dysphoria with an adjustment disorder with depressed mood"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-367', 'Reshma: losing her guru and her place (depression in a transgender woman in a hijra community)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-367-1","text":"Says she feels ''no place in the world''","bucket":"presenting"},{"id":"form-367-2","text":"An NGO outreach worker she trusts","bucket":"protective"},{"id":"form-367-3","text":"Left her family home at 15 after rejection","bucket":"predisposing"},{"id":"form-367-4","text":"Stigma at the local clinic, so she avoids care","bucket":"perpetuating"},{"id":"form-367-5","text":"Experienced violence and discrimination for years","bucket":"predisposing"},{"id":"form-367-6","text":"Alcohol used to numb grief","bucket":"perpetuating"},{"id":"form-367-7","text":"Disputes in the gharana about succession","bucket":"perpetuating"},{"id":"form-367-8","text":"Low mood, crying, poor sleep and drinking every night for three months","bucket":"presenting"},{"id":"form-367-9","text":"Close chela sisters who care for her","bucket":"protective"},{"id":"form-367-10","text":"She lives in Hyderabad''s Old City","bucket":"distractor"},{"id":"form-367-11","text":"Death of her guru, who was her mother figure, four months ago","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Reshma, 30, a transgender woman in a hijra community, has a depressive episode with harmful alcohol use after the death of her guru. The guru-chela system is a family structure for many hijra people, so this is a deep loss of a mother figure and of security. Early family rejection and years of violence and discrimination (predisposing) raise her risk; her guru''s death (precipitating) triggered the episode. Succession disputes, stigma at the clinic and drinking to numb grief (perpetuating) maintain it. Her chela sisters and a trusted outreach worker (protective) are key. Plan: assess suicide risk, offer care through a respectful, community-linked service, grief support, alcohol help and screening for physical health. Her neighbourhood is a distractor.","hint":"A 30-year-old transgender woman drinking heavily since her guru died","tags":{"topic":"gender","difficulty":3,"objective":"Formulate depression in a marginalised community with respect for its structures","exams":["mcp-entrance","md-psychiatry"],"module":"depression","diagnosis":"Depressive episode with harmful alcohol use"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-368', 'Mrs Fatima: vomiting all day and losing hope (hyperemesis gravidarum with depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-368-1","text":"Husband who stays with her in hospital","bucket":"protective"},{"id":"form-368-2","text":"She lives in Malappuram","bucket":"distractor"},{"id":"form-368-3","text":"Severe vomiting many times a day for eight weeks, with weight loss and two admissions for drips","bucket":"presenting"},{"id":"form-368-4","text":"Unable to work or go out","bucket":"perpetuating"},{"id":"form-368-5","text":"Hyperemesis began at seven weeks of pregnancy","bucket":"precipitating"},{"id":"form-368-6","text":"Obstetrician who takes her symptoms seriously","bucket":"protective"},{"id":"form-368-7","text":"Fear of taking any medicine in pregnancy","bucket":"perpetuating"},{"id":"form-368-8","text":"In-laws say she is ''exaggerating''","bucket":"perpetuating"},{"id":"form-368-9","text":"Past episode of low mood at college","bucket":"predisposing"},{"id":"form-368-10","text":"Low mood, tearful and says she regrets the pregnancy","bucket":"presenting"},{"id":"form-368-11","text":"Lives far from her own family","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Fatima, 26, has a depressive episode in pregnancy linked to hyperemesis gravidarum, severe pregnancy sickness with weight loss and dehydration. Hyperemesis is a medical condition, not exaggeration, and it often causes depression and even thoughts of ending the pregnancy. A past low mood and distance from her family (predisposing) raise her risk; the hyperemesis (precipitating) started it. Disbelief from in-laws, isolation and fear of medicines (perpetuating) maintain it. Her husband and obstetrician (protective) help. Plan: effective anti-sickness treatment, explaining that untreated sickness also carries risks, assess mood and suicide risk, and support from her family. Her town is a distractor.","hint":"A 26-year-old in her first pregnancy who cannot keep food down","tags":{"topic":"perinatal","difficulty":2,"objective":"Recognise depression that grows out of severe pregnancy sickness","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"depression","diagnosis":"Depressive episode in pregnancy with hyperemesis gravidarum"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-369', 'Ms Neha: terrified of giving birth (tokophobia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-369-1","text":"Anxious temperament","bucket":"predisposing"},{"id":"form-369-2","text":"Avoids antenatal topics, so fears are never corrected","bucket":"perpetuating"},{"id":"form-369-3","text":"Reads frightening stories online","bucket":"perpetuating"},{"id":"form-369-4","text":"Husband who supports her pace","bucket":"protective"},{"id":"form-369-5","text":"Has avoided pregnancy for three years despite wanting a child","bucket":"presenting"},{"id":"form-369-6","text":"Open to talking with an obstetrician","bucket":"protective"},{"id":"form-369-7","text":"Husband''s family pressing for a grandchild","bucket":"precipitating"},{"id":"form-369-8","text":"She works as a lawyer in Mumbai","bucket":"distractor"},{"id":"form-369-9","text":"Believes she will die in labour","bucket":"perpetuating"},{"id":"form-369-10","text":"Intense fear of labour and delivery, with panic when she sees birth scenes","bucket":"presenting"},{"id":"form-369-11","text":"Witnessed her sister''s traumatic delivery as a teenager","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ms Neha, 30, has primary tokophobia, a severe fear of childbirth in a woman who has not given birth, which leads her to avoid pregnancy despite wanting a child. Witnessing her sister''s traumatic delivery and an anxious temperament (predisposing) shaped the fear; family pressure for a grandchild (precipitating) brought it to a head. Avoidance, frightening online stories and catastrophic beliefs (perpetuating) maintain it. Her husband''s patience and openness to talk to an obstetrician (protective) help. Plan: CBT with exposure to birth information, a birth plan discussed with an obstetrician, including options for pain relief and mode of delivery, and support from her husband. Her job is a distractor.","hint":"A 30-year-old who wants a child but is terrified of labour","tags":{"topic":"perinatal","difficulty":3,"objective":"Formulate a severe fear of childbirth","exams":["mcp-entrance","md-psychiatry"],"module":"anxiety","diagnosis":"Specific phobia of childbirth (primary tokophobia)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-370', 'Mrs Kavya: the emergency caesarean she keeps reliving (PTSD after childbirth)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-370-1","text":"Avoids the hospital, feels numb and startles easily","bucket":"presenting"},{"id":"form-370-2","text":"Feels guilty that she cannot bond fully with her baby","bucket":"perpetuating"},{"id":"form-370-3","text":"Anxious before the pregnancy","bucket":"predisposing"},{"id":"form-370-4","text":"Avoids the postnatal check-up","bucket":"perpetuating"},{"id":"form-370-5","text":"She lives in Mysuru","bucket":"distractor"},{"id":"form-370-6","text":"Past childhood trauma","bucket":"predisposing"},{"id":"form-370-7","text":"Flashbacks and nightmares of an emergency caesarean four months ago, when she feared her baby would die","bucket":"presenting"},{"id":"form-370-8","text":"Husband who listens","bucket":"protective"},{"id":"form-370-9","text":"Emergency caesarean under general anaesthesia after a sudden drop in the baby''s heartbeat","bucket":"precipitating"},{"id":"form-370-10","text":"Healthy baby","bucket":"protective"},{"id":"form-370-11","text":"No one explained what happened during the surgery","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Kavya, 29, has PTSD after childbirth: flashbacks, nightmares, avoidance, numbness and startle after an emergency caesarean when she feared her baby would die. Birth trauma is common and often missed. Past trauma and pre-existing anxiety (predisposing) raised her risk; the sudden emergency surgery (precipitating) was the traumatic event. No explanation of events, avoiding check-ups and guilt about bonding (perpetuating) maintain it. A healthy baby and a listening husband (protective) help. Plan: a debrief with the obstetric team to explain what happened, trauma-focused therapy, support for bonding and screening for depression. Mysuru is a distractor.","hint":"A 29-year-old with flashbacks after a frightening emergency delivery","tags":{"topic":"perinatal","difficulty":3,"objective":"Recognise birth trauma and PTSD after delivery","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"trauma","diagnosis":"Post-traumatic stress disorder after childbirth"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-371', 'Mrs Rhea: frightening pictures of harming her baby (perinatal OCD, not psychosis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-371-1","text":"Intrusive, horrifying images of dropping her baby or harming him with a knife since the birth six weeks ago","bucket":"presenting"},{"id":"form-371-2","text":"Supportive mother staying with her","bucket":"protective"},{"id":"form-371-3","text":"Past mild checking habits in college","bucket":"predisposing"},{"id":"form-371-4","text":"Perfectionist temperament","bucket":"predisposing"},{"id":"form-371-5","text":"Birth of her first baby","bucket":"precipitating"},{"id":"form-371-6","text":"Believes the baby is possessed and must be saved by harm, with no distress about it","bucket":"distractor"},{"id":"form-371-7","text":"Avoids bathing him, hides the knives and checks him all night","bucket":"presenting"},{"id":"form-371-8","text":"Believes having the thoughts means she is dangerous","bucket":"perpetuating"},{"id":"form-371-9","text":"Horrified by the thoughts and wants help","bucket":"protective"},{"id":"form-371-10","text":"Avoids caring for the baby alone, which keeps fear high","bucket":"perpetuating"},{"id":"form-371-11","text":"Seeks constant reassurance from her mother","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Rhea, 31, has OCD with postpartum onset: unwanted, horrifying intrusive thoughts of harming her baby, which she resists, with avoidance and checking. Such thoughts are common after birth and, in OCD, the risk of acting on them is very low because they go against her wishes. The distractor, a belief that the baby is possessed and must be harmed without distress, would point to postpartum psychosis, an emergency, and does not fit. Past checking and perfectionism (predisposing) raise her risk; the birth (precipitating) triggered it. Avoidance, reassurance-seeking and believing the thoughts mean she is dangerous (perpetuating) maintain it. Her horror at the thoughts and her mother''s support (protective) help. Plan: clear explanation, CBT with exposure and response prevention, and an SSRI compatible with breastfeeding if needed.","hint":"A 31-year-old new mother terrified by thoughts of dropping or hurting her baby","tags":{"topic":"perinatal","difficulty":4,"objective":"Tell perinatal OCD apart from postpartum psychosis and understand the low risk of acting","exams":["md-psychiatry","mcp-entrance"],"module":"ocd","diagnosis":"Obsessive-compulsive disorder with postpartum onset"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-372', 'Mr Anand: the new father who stopped laughing (paternal postnatal depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-372-1","text":"Feels he is a failure as a father","bucket":"presenting"},{"id":"form-372-2","text":"Believes men should not complain","bucket":"perpetuating"},{"id":"form-372-3","text":"His own father was distant","bucket":"predisposing"},{"id":"form-372-4","text":"Birth of his first child, with his wife unwell after delivery","bucket":"precipitating"},{"id":"form-372-5","text":"Sleep loss from night feeds","bucket":"perpetuating"},{"id":"form-372-6","text":"Low mood, irritability, poor sleep and working late to avoid home, for three months since his daughter''s birth","bucket":"presenting"},{"id":"form-372-7","text":"He is an accountant in Nagpur","bucket":"distractor"},{"id":"form-372-8","text":"Close friend who is also a new father","bucket":"protective"},{"id":"form-372-9","text":"Loves his daughter","bucket":"protective"},{"id":"form-372-10","text":"Past episode of low mood","bucket":"predisposing"},{"id":"form-372-11","text":"Money worries after his wife stopped working","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Anand, 33, has paternal postnatal depression: low mood, irritability and withdrawal after the birth of his child. Fathers can develop depression in the first year, often showing as irritability, overworking or drinking, and it is easily missed. A past low mood and a distant father (predisposing) raise his risk; the birth with his wife unwell (precipitating) brought heavy responsibility. Beliefs that men should not complain, sleep loss and money worries (perpetuating) maintain it. His love for his daughter and a friend who is also a new father (protective) help. Plan: risk assessment, treatment for depression, sharing night duties, financial planning and screening his wife too. His job is a distractor.","hint":"A 33-year-old father who has become low and withdrawn since the baby","tags":{"topic":"perinatal","difficulty":2,"objective":"Recognise depression in a new father","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"depression","diagnosis":"Depressive episode in a father after the birth of a child (paternal postnatal depression)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-373', 'Mrs Shilpa: three losses and terrified of the fourth (anxiety after recurrent miscarriage)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-373-1","text":"Pregnancy confirmed eight weeks ago","bucket":"precipitating"},{"id":"form-373-2","text":"Three earlier miscarriages","bucket":"predisposing"},{"id":"form-373-3","text":"Avoids telling anyone or buying baby things in case of loss","bucket":"perpetuating"},{"id":"form-373-4","text":"Poor sleep and repeated visits for scans for reassurance","bucket":"presenting"},{"id":"form-373-5","text":"Constant fear of losing this pregnancy, checking for bleeding many times a day","bucket":"presenting"},{"id":"form-373-6","text":"Relatives blame her for the earlier losses","bucket":"perpetuating"},{"id":"form-373-7","text":"She lives in Varanasi","bucket":"distractor"},{"id":"form-373-8","text":"Each reassurance helps only for hours","bucket":"perpetuating"},{"id":"form-373-9","text":"Anxious temperament","bucket":"predisposing"},{"id":"form-373-10","text":"Husband who shares her hopes","bucket":"protective"},{"id":"form-373-11","text":"Specialist obstetric care","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Shilpa, 34, has anxiety in pregnancy after three miscarriages: constant fear of loss, repeated checking and reassurance seeking, with poor sleep. Pregnancy after loss is often marked by anxiety and unresolved grief. Previous losses and an anxious temperament (predisposing) raise her risk; the new pregnancy (precipitating) brought the fear back. Reassurance that lasts only hours, holding back from hope and relatives'' blame (perpetuating) maintain it. Specialist care and her husband''s support (protective) help. Plan: a planned schedule of check-ups rather than repeated emergency visits, space to grieve earlier losses, CBT for anxiety, and challenging blame from relatives. Varanasi is a distractor.","hint":"A 34-year-old who is pregnant again after three miscarriages and cannot stop checking","tags":{"topic":"perinatal","difficulty":2,"objective":"Formulate pregnancy anxiety after repeated loss","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"anxiety","diagnosis":"Anxiety in pregnancy after recurrent pregnancy loss (adjustment disorder with anxiety)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-374', 'Mrs Divya: anxious, then exhausted, months after the birth (postpartum thyroiditis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-374-1","text":"Diagnosed elsewhere with ''postnatal depression'' with no thyroid tests","bucket":"presenting"},{"id":"form-374-2","text":"Mother has thyroid disease","bucket":"predisposing"},{"id":"form-374-3","text":"Low mood since the second week after birth with normal thyroid tests","bucket":"distractor"},{"id":"form-374-4","text":"Exhaustion from night feeds","bucket":"perpetuating"},{"id":"form-374-5","text":"Often settles with treatment of the thyroid","bucket":"protective"},{"id":"form-374-6","text":"Supportive husband and mother","bucket":"protective"},{"id":"form-374-7","text":"Childbirth six months ago","bucket":"precipitating"},{"id":"form-374-8","text":"At three months after birth, anxious with a racing heart and weight loss; now at six months, tired, low, cold and gaining weight","bucket":"presenting"},{"id":"form-374-9","text":"Positive thyroid antibodies found in early pregnancy","bucket":"predisposing"},{"id":"form-374-10","text":"Antidepressant started without blood tests","bucket":"perpetuating"},{"id":"form-374-11","text":"Symptoms put down to ''new mother stress''","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Divya, 28, has postpartum thyroiditis: an inflammation of the thyroid after birth that often causes an overactive phase in the first months, then an underactive phase with tiredness, low mood and weight gain. A mother with thyroid disease and positive antibodies in pregnancy (predisposing) raise her risk; childbirth (precipitating) triggered it. Calling it stress, starting an antidepressant without tests and night feeds (perpetuating) delay the right treatment. The distractor, low mood from week two with normal thyroid tests, would fit postnatal depression alone. Her family and a treatable cause (protective) help. Plan: thyroid tests, treatment of the underactive phase, monitoring, and continued screening for postnatal depression.","hint":"A 28-year-old with racing heart at three months postpartum and low mood at six months","tags":{"topic":"perinatal","difficulty":4,"objective":"Look for thyroid changes behind mood symptoms after childbirth","exams":["md-psychiatry","mcp-entrance"],"module":"depression","diagnosis":"Postpartum thyroiditis with depressive symptoms"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-375', 'Mrs Meenu: the third failed cycle (depression after unsuccessful IVF)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-375-1","text":"Low mood, crying, poor sleep and withdrawal for two months after a third failed IVF cycle","bucket":"presenting"},{"id":"form-375-2","text":"Third unsuccessful IVF cycle","bucket":"precipitating"},{"id":"form-375-3","text":"Long history of infertility and a sense that motherhood defines her worth","bucket":"predisposing"},{"id":"form-375-4","text":"Husband who loves her regardless","bucket":"protective"},{"id":"form-375-5","text":"Avoids family functions and baby showers","bucket":"presenting"},{"id":"form-375-6","text":"She lives in Indore","bucket":"distractor"},{"id":"form-375-7","text":"Relatives ask about a baby at every gathering","bucket":"perpetuating"},{"id":"form-375-8","text":"Past anxiety","bucket":"predisposing"},{"id":"form-375-9","text":"Close friend who also went through infertility","bucket":"protective"},{"id":"form-375-10","text":"Couple not talking about what to do next","bucket":"perpetuating"},{"id":"form-375-11","text":"Large debts from treatment","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Meenu, 36, has a depressive episode after a third failed IVF cycle. Infertility and treatment failure bring grief, loss of hope and often stigma, especially where motherhood is central to identity. A long struggle with infertility, linking her worth to motherhood and past anxiety (predisposing) raise her risk; the failed cycle (precipitating) triggered the episode. Relatives'' questions, debts and silence between the couple (perpetuating) maintain it. A loving husband and a friend who understands (protective) help. Plan: assess risk, grief-focused therapy, couple sessions on next steps including stopping, donor options or adoption, and treatment for depression. Indore is a distractor.","hint":"A 36-year-old who has stopped going out after a third failed fertility treatment","tags":{"topic":"perinatal","difficulty":3,"objective":"Formulate depression after fertility treatment failure","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"depression","diagnosis":"Depressive episode after repeated failed fertility treatment"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-376', 'Mrs Asha: tearful on day four (baby blues)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-376-1","text":"Still caring for and bonding with her baby","bucket":"presenting"},{"id":"form-376-2","text":"Tearful, irritable and anxious on day four after a normal delivery","bucket":"presenting"},{"id":"form-376-3","text":"Mild premenstrual mood changes","bucket":"predisposing"},{"id":"form-376-4","text":"First baby","bucket":"predisposing"},{"id":"form-376-5","text":"Sleep loss from feeds","bucket":"perpetuating"},{"id":"form-376-6","text":"No past mental illness","bucket":"protective"},{"id":"form-376-7","text":"Mother staying to help","bucket":"protective"},{"id":"form-376-8","text":"Many visitors at home","bucket":"perpetuating"},{"id":"form-376-9","text":"She lives in Kolhapur","bucket":"distractor"},{"id":"form-376-10","text":"Delivery four days ago and sudden hormone changes","bucket":"precipitating"},{"id":"form-376-11","text":"Worry that crying means she is a bad mother","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Asha, 25, has postpartum blues: tearfulness, irritability and anxiety peaking around day three to five after birth, which affects many new mothers and usually settles by two weeks. Being a first-time mother and having mild premenstrual mood changes (predisposing) shape her sensitivity; the delivery and hormone changes (precipitating) trigger it. Sleep loss, many visitors and worry about being a bad mother (perpetuating) add stress. Her mother''s help and no past illness (protective) predict quick recovery. Plan: reassurance, rest, fewer visitors and advice to seek help if symptoms last beyond two weeks or become severe. Kolhapur is a distractor.","hint":"A 25-year-old who cries easily four days after a normal delivery","tags":{"topic":"perinatal","difficulty":1,"objective":"Recognise the baby blues and when to worry","exams":["cuet-pg","ma-semester","mcp-entrance"],"module":"lifespan","diagnosis":"Postpartum blues (baby blues)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-377', 'Ms Ritika: the stomach that runs her life (irritable bowel syndrome with anxiety)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-377-1","text":"Belly cramps, bloating and urgent loose motions on most days for a year, worse before meetings","bucket":"presenting"},{"id":"form-377-2","text":"Worry about accidents triggers more symptoms","bucket":"perpetuating"},{"id":"form-377-3","text":"Plans every journey around toilets and avoids eating out","bucket":"perpetuating"},{"id":"form-377-4","text":"Many dietary restrictions from the internet","bucket":"perpetuating"},{"id":"form-377-5","text":"She lives in Gurugram","bucket":"distractor"},{"id":"form-377-6","text":"Mother has similar stomach problems","bucket":"predisposing"},{"id":"form-377-7","text":"Stomach infection during a trip, followed by a stressful new job","bucket":"precipitating"},{"id":"form-377-8","text":"Willing to try a structured plan","bucket":"protective"},{"id":"form-377-9","text":"Anxious since childhood","bucket":"predisposing"},{"id":"form-377-10","text":"Normal colonoscopy and blood tests","bucket":"presenting"},{"id":"form-377-11","text":"Supportive manager","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ms Ritika, 27, has irritable bowel syndrome with generalised anxiety. The gut and brain are linked, so worry and stress can make the gut more sensitive and active. An anxious temperament and a family pattern (predisposing) raise her risk; a stomach infection followed by a stressful job (precipitating) started symptoms. Planning around toilets, worry about accidents and many internet diet rules (perpetuating) keep the cycle going. A supportive manager and willingness to try a plan (protective) help. Plan: explain the gut-brain link, a guided diet change, CBT for anxiety and gut-directed relaxation. Gurugram is a distractor.","hint":"A 27-year-old with cramps and urgency that worsen before meetings","tags":{"topic":"somatic","difficulty":1,"objective":"Sort irritable bowel syndrome with anxiety into the 5 Ps","exams":["cuet-pg","ma-semester","mcp-entrance"],"module":"anxiety","diagnosis":"Irritable bowel syndrome with generalised anxiety"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-378', 'Mr Joseph: the floor that seems to sway (persistent postural-perceptual dizziness)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-378-1","text":"Normal ear and brain tests","bucket":"presenting"},{"id":"form-378-2","text":"Avoids malls, escalators and busy roads","bucket":"perpetuating"},{"id":"form-378-3","text":"Past panic attacks in his twenties","bucket":"predisposing"},{"id":"form-378-4","text":"Uses a walking stick he does not need","bucket":"perpetuating"},{"id":"form-378-5","text":"Constant feeling of rocking or unsteadiness for a year, worse in shopping malls and when standing","bucket":"presenting"},{"id":"form-378-6","text":"He is a tailor in Kottayam","bucket":"distractor"},{"id":"form-378-7","text":"Stiffens and watches his balance all the time","bucket":"perpetuating"},{"id":"form-378-8","text":"A short attack of spinning vertigo from an inner ear infection a year ago","bucket":"precipitating"},{"id":"form-378-9","text":"Anxious, watchful nature","bucket":"predisposing"},{"id":"form-378-10","text":"Ear specialist who explained the condition","bucket":"protective"},{"id":"form-378-11","text":"Wife who encourages him to go out","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Joseph, 48, has persistent postural-perceptual dizziness: long-lasting unsteadiness that is worse when upright and in busy visual settings, after an inner ear problem has healed. The brain stays on high alert for balance problems. An anxious nature and past panic (predisposing) raise his risk; an attack of vertigo (precipitating) set it off. Over-monitoring balance, stiffening, avoidance and an unnecessary stick (perpetuating) keep the brain from re-learning normal balance. A clear explanation and his wife''s encouragement (protective) help. Plan: vestibular rehabilitation exercises, graded return to busy places, CBT for anxiety and possibly an SSRI. His trade is a distractor.","hint":"A 48-year-old who has felt unsteady for a year since a bout of vertigo","tags":{"topic":"somatic","difficulty":3,"objective":"Formulate chronic functional dizziness kept going by fear and avoidance","exams":["mcp-entrance","md-psychiatry"],"module":"more-disorders","diagnosis":"Persistent postural-perceptual dizziness"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-379', 'Ms Bharti: the voice that vanished after the engagement (functional voice loss)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-379-1","text":"Quiet, obedient daughter who rarely voices disagreement","bucket":"predisposing"},{"id":"form-379-2","text":"Eager to finish her nursing course","bucket":"protective"},{"id":"form-379-3","text":"Can only whisper for three weeks; coughs normally","bucket":"presenting"},{"id":"form-379-4","text":"Family fixed her engagement to a man she has met once","bucket":"precipitating"},{"id":"form-379-5","text":"Similar episode of weakness after exams at sixteen","bucket":"predisposing"},{"id":"form-379-6","text":"ENT examination shows normal vocal cords that move well","bucket":"presenting"},{"id":"form-379-7","text":"Close to her elder sister","bucket":"protective"},{"id":"form-379-8","text":"Repeated visits for injections and tonics","bucket":"perpetuating"},{"id":"form-379-9","text":"Hoarse voice with a painful throat and fever","bucket":"distractor"},{"id":"form-379-10","text":"Family speaks for her and visitors fuss over her","bucket":"perpetuating"},{"id":"form-379-11","text":"Fear of saying she does not want the marriage","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ms Bharti, 23, has functional aphonia: loss of voice with normal vocal cords that move well and a normal cough, which shows the voice system can work. It is a real, involuntary symptom, often linked to stress that is hard to put into words. A habit of not voicing disagreement and a past functional episode (predisposing) shape her vulnerability; an engagement fixed without her agreement (precipitating) triggered it. Family speaking for her, fear of expressing her wishes and repeated treatments (perpetuating) maintain it. Her sister and her course (protective) help. A sore throat with fever, the distractor, would point to laryngitis. Plan: clear explanation, speech therapy, a safe space to voice her wishes about marriage and family work.","hint":"A 23-year-old who can only whisper since her engagement was announced","tags":{"topic":"somatic","difficulty":2,"objective":"Recognise functional voice loss and the stress behind it","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"more-disorders","diagnosis":"Functional neurological symptom disorder with speech symptoms (functional aphonia)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-380', 'Mr Tenzin: watching his life through glass (depersonalisation-derealisation disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-380-1","text":"Panic attack after smoking strong cannabis at a party","bucket":"precipitating"},{"id":"form-380-2","text":"Good insight","bucket":"protective"},{"id":"form-380-3","text":"Firmly believes the world has been replaced by a copy","bucket":"distractor"},{"id":"form-380-4","text":"Avoids friends and stays in his room","bucket":"perpetuating"},{"id":"form-380-5","text":"Constant feelings of being detached from himself and that the world is unreal, for a year","bucket":"presenting"},{"id":"form-380-6","text":"Constantly checks whether he feels real","bucket":"perpetuating"},{"id":"form-380-7","text":"Knows the feelings are not true and is frightened he is going mad","bucket":"presenting"},{"id":"form-380-8","text":"Supportive older sister","bucket":"protective"},{"id":"form-380-9","text":"Anxious since childhood","bucket":"predisposing"},{"id":"form-380-10","text":"Grew up with an alcoholic father and frequent fights","bucket":"predisposing"},{"id":"form-380-11","text":"Fear of going mad keeps him anxious","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Tenzin, 24, has depersonalisation-derealisation disorder: persistent detachment from himself and a sense the world is unreal, while knowing it is a feeling, not reality. That intact reality testing separates it from psychosis; a firm belief that the world has been replaced, the distractor, would be a delusion. Childhood anxiety and a chaotic home (predisposing) raise his vulnerability; a panic attack after strong cannabis (precipitating) triggered it. Checking, fear of madness and withdrawal (perpetuating) keep attention locked on the feelings. Insight and his sister (protective) help. Plan: explain that it is common and not madness, CBT that reduces checking and avoidance, avoid cannabis and treat anxiety.","hint":"A 24-year-old who has felt detached from himself for a year","tags":{"topic":"somatic","difficulty":3,"objective":"Formulate persistent depersonalisation with intact reality testing","exams":["mcp-entrance","md-psychiatry"],"module":"more-disorders","diagnosis":"Depersonalisation-derealisation disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-381', 'Ms Lalitha: the fevers no one can explain (factitious disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-381-1","text":"A thermometer was found heated in hot water; blood cultures repeatedly grow mixed skin bacteria","bucket":"presenting"},{"id":"form-381-2","text":"Emotional neglect at home","bucket":"predisposing"},{"id":"form-381-3","text":"Broke up with her partner shortly before the first admission","bucket":"precipitating"},{"id":"form-381-4","text":"She is claiming insurance money for each admission","bucket":"distractor"},{"id":"form-381-5","text":"Skilled nurse with a stable job","bucket":"protective"},{"id":"form-381-6","text":"Moves between hospitals so the pattern is missed","bucket":"perpetuating"},{"id":"form-381-7","text":"Shame makes it hard to admit","bucket":"perpetuating"},{"id":"form-381-8","text":"Six admissions in a year for fevers that appear only when she is unobserved","bucket":"presenting"},{"id":"form-381-9","text":"A close colleague who is worried about her","bucket":"protective"},{"id":"form-381-10","text":"Childhood illness with long hospital stays, the only time she felt cared for","bucket":"predisposing"},{"id":"form-381-11","text":"Hospital admissions bring care and attention","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ms Lalitha, 32, has factitious disorder imposed on self: she falsifies or causes signs of illness, without obvious outside reward, to take on the role of a patient. Claiming insurance money for gain, the distractor, would point to malingering instead. A childhood in which care came only through illness and emotional neglect (predisposing) shaped her need; a breakup (precipitating) came before the first admission. The care and attention of admission, moving between hospitals and shame (perpetuating) maintain it. Her nursing skill and a worried colleague (protective) are strengths. Plan: one consistent team, a calm, non-shaming conversation about the findings, avoiding unnecessary tests, and longer-term therapy for underlying needs.","hint":"A 32-year-old nurse with repeated unexplained fevers and admissions","tags":{"topic":"somatic","difficulty":4,"objective":"Recognise factitious disorder and plan a non-shaming response","exams":["md-psychiatry","mcp-entrance"],"module":"more-disorders","diagnosis":"Factitious disorder imposed on self"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-382', 'Mr Kailash: forgetting everything before the trial (malingering in a remand prisoner)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-382-1","text":"History of fraud and deceit","bucket":"predisposing"},{"id":"form-382-2","text":"Belief that illness will delay or avoid trial","bucket":"perpetuating"},{"id":"form-382-3","text":"He was a property dealer in Ghaziabad","bucket":"distractor"},{"id":"form-382-4","text":"Family willing to give a history","bucket":"protective"},{"id":"form-382-5","text":"Claims total loss of memory, including his name and family, since his arrest","bucket":"presenting"},{"id":"form-382-6","text":"No real brain injury or illness on assessment","bucket":"protective"},{"id":"form-382-7","text":"Knows about mental illness from a cousin''s case","bucket":"predisposing"},{"id":"form-382-8","text":"Prison staff saw him playing cards skilfully and phoning his lawyer from memory","bucket":"presenting"},{"id":"form-382-9","text":"Inconsistent results on memory tests, worse than chance on some","bucket":"perpetuating"},{"id":"form-382-10","text":"Lawyer has asked for a psychiatric report","bucket":"perpetuating"},{"id":"form-382-11","text":"Charged with a large financial fraud and facing a long sentence","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Kailash, 40, shows features of malingering: intentionally producing false symptoms of memory loss for an outside gain, here to delay or avoid trial. Malingering is a judgement, not a mental disorder, and should be reached carefully on evidence: total loss of personal identity is very rare, he shows intact memory in daily life, and some test results are worse than chance. A history of deceit and knowledge of mental illness (predisposing) shape his presentation; facing serious charges (precipitating) gives the motive. The belief that illness helps, inconsistent testing and the legal request (perpetuating) maintain it. No real brain illness and family willing to help (protective) allow a clear report. Plan: careful documentation, collateral history, neutral, honest reporting to the court and continued review in case a genuine illness emerges.","hint":"A 40-year-old accused of fraud who now claims he cannot remember his own name","tags":{"topic":"forensic","difficulty":5,"objective":"Formulate suspected malingering with care and evidence","exams":["md-psychiatry","mcp-entrance"],"module":"ethics-law","diagnosis":"Malingering (feigned memory loss) in a remand prisoner"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-383', 'Mrs Arora: exhausted for two years after the fever (chronic fatigue with depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-383-1","text":"Low mood and loss of interest for six months","bucket":"presenting"},{"id":"form-383-2","text":"Past episode of low mood","bucket":"predisposing"},{"id":"form-383-3","text":"Normal blood tests rule out other causes","bucket":"protective"},{"id":"form-383-4","text":"Pushes too hard on good days and crashes for days after","bucket":"perpetuating"},{"id":"form-383-5","text":"She lives in Chandigarh","bucket":"distractor"},{"id":"form-383-6","text":"Dengue fever two years ago","bucket":"precipitating"},{"id":"form-383-7","text":"High-achieving, rarely rested","bucket":"predisposing"},{"id":"form-383-8","text":"Supportive husband","bucket":"protective"},{"id":"form-383-9","text":"Doctors told her it was ''all in her head''","bucket":"perpetuating"},{"id":"form-383-10","text":"Severe tiredness for two years, worse after even small effort, with poor sleep and poor concentration","bucket":"presenting"},{"id":"form-383-11","text":"Lost her job and social contact","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Arora, 41, has chronic fatigue syndrome with a depressive episode: long-lasting fatigue that worsens after effort, with unrefreshing sleep and thinking problems, after a viral illness, and recent low mood. A high-achieving style and past low mood (predisposing) raise her vulnerability; dengue fever (precipitating) began the illness. A push-and-crash pattern, being disbelieved and losing work and friends (perpetuating) maintain both fatigue and depression. A supportive husband and normal tests (protective) help. Plan: validate the illness, pacing activity within her limits, sleep support, treatment for depression and careful, gradual return to activity. Chandigarh is a distractor.","hint":"A 41-year-old who has been tired and unable to work since a viral illness","tags":{"topic":"somatic","difficulty":3,"objective":"Formulate persistent post-viral fatigue with mood and activity factors","exams":["mcp-entrance","md-psychiatry"],"module":"more-disorders","diagnosis":"Chronic fatigue syndrome (myalgic encephalomyelitis) with a depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-384', 'Mr Sinha: checking his oxygen since the pandemic (health anxiety after COVID)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-384-1","text":"He works as an accountant in Patna","bucket":"distractor"},{"id":"form-384-2","text":"Anxious temperament","bucket":"predisposing"},{"id":"form-384-3","text":"Good physical health","bucket":"protective"},{"id":"form-384-4","text":"A mild cough last winter","bucket":"precipitating"},{"id":"form-384-5","text":"Each normal reading calms him for minutes only","bucket":"perpetuating"},{"id":"form-384-6","text":"Lost his brother to COVID in 2021","bucket":"predisposing"},{"id":"form-384-7","text":"Checks his oxygen level and temperature dozens of times a day for eighteen months","bucket":"presenting"},{"id":"form-384-8","text":"Wife who supports change","bucket":"protective"},{"id":"form-384-9","text":"Reads health news for hours","bucket":"perpetuating"},{"id":"form-384-10","text":"Convinced he will catch a deadly infection; tests are normal","bucket":"presenting"},{"id":"form-384-11","text":"Avoids crowded places and the office","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Sinha, 45, has illness anxiety disorder: persistent fear of having or catching a serious illness, with excessive checking and avoidance, despite normal tests. An anxious temperament and his brother''s death in the pandemic (predisposing) raise his risk; a mild cough (precipitating) set off the current episode. Brief relief from each reading, avoidance and hours of health news (perpetuating) maintain the fear. His wife and good health (protective) help. Plan: CBT to reduce checking and reassurance seeking, gradual return to normal activities, grief work for his brother and possibly an SSRI. His job is a distractor.","hint":"A 45-year-old who checks his oxygen level dozens of times a day","tags":{"topic":"anxiety","difficulty":2,"objective":"Recognise health anxiety and its checking cycle","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"anxiety","diagnosis":"Illness anxiety disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-385', 'Ms Pooja: the band around her head every exam season (tension-type headache)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-385-1","text":"Perfectionist","bucket":"predisposing"},{"id":"form-385-2","text":"Enjoys yoga","bucket":"protective"},{"id":"form-385-3","text":"No vomiting, no visual change, normal examination","bucket":"presenting"},{"id":"form-385-4","text":"She studies history in Allahabad","bucket":"distractor"},{"id":"form-385-5","text":"Pressing, band-like headache on both sides most afternoons for a month","bucket":"presenting"},{"id":"form-385-6","text":"Drinks strong tea all evening","bucket":"perpetuating"},{"id":"form-385-7","text":"Skips meals and sleeps late","bucket":"perpetuating"},{"id":"form-385-8","text":"Supportive roommate","bucket":"protective"},{"id":"form-385-9","text":"Mother has frequent headaches","bucket":"predisposing"},{"id":"form-385-10","text":"Final-year exams approaching","bucket":"precipitating"},{"id":"form-385-11","text":"Studies for hours without breaks, hunched over books","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ms Pooja, 20, has tension-type headache linked to stress: a pressing, band-like headache on both sides without warning signs. Perfectionism and a family pattern of headache (predisposing) raise her risk; approaching exams (precipitating) triggered it. Long study without breaks and poor posture, skipped meals, late nights and strong tea (perpetuating) maintain it. Yoga and her roommate (protective) help. Plan: regular breaks and posture changes, meals and sleep routine, less caffeine, relaxation and limiting painkillers to a few days a week to avoid overuse headache. Her course is a distractor.","hint":"A 20-year-old student with daily pressing headaches during exams","tags":{"topic":"somatic","difficulty":1,"objective":"Sort a stress-linked tension-type headache into the 5 Ps","exams":["cuet-pg","ma-semester","mcp-entrance"],"module":"anxiety","diagnosis":"Tension-type headache linked to stress"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-386', 'Mr Venkatesh: afraid to bend since the operation (chronic pain with fear-avoidance)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-386-1","text":"Back pain for a year after a successful disc operation, with a normal follow-up scan","bucket":"presenting"},{"id":"form-386-2","text":"Worrying temperament","bucket":"predisposing"},{"id":"form-386-3","text":"Surgeon who confirms the spine is healed","bucket":"protective"},{"id":"form-386-4","text":"Worries the pain means damage","bucket":"perpetuating"},{"id":"form-386-5","text":"He lives in Coimbatore","bucket":"distractor"},{"id":"form-386-6","text":"Avoids bending and lifting and has stopped work; low mood","bucket":"presenting"},{"id":"form-386-7","text":"Lies in bed most of the day","bucket":"perpetuating"},{"id":"form-386-8","text":"Wife who encourages walking","bucket":"protective"},{"id":"form-386-9","text":"Manual worker all his life","bucket":"predisposing"},{"id":"form-386-10","text":"Avoids movement, so muscles weaken and pain increases","bucket":"perpetuating"},{"id":"form-386-11","text":"Told by a relative that bending could ''break the operation''","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Venkatesh, 52, has chronic post-surgical pain kept going by fear-avoidance, with depressive symptoms. When pain is believed to mean harm, people avoid movement, muscles weaken and pain grows. Years of heavy manual work and a worrying temperament (predisposing) raise his risk; a relative''s warning (precipitating) planted the fear. Avoidance, bed rest and the belief that pain means damage (perpetuating) maintain it. The surgeon''s reassurance and his wife''s encouragement (protective) help. Plan: explain that hurt does not mean harm, graded physiotherapy, pacing, treatment of low mood and a plan for return to work. Coimbatore is a distractor.","hint":"A 52-year-old with ongoing back pain a year after successful spine surgery","tags":{"topic":"somatic","difficulty":3,"objective":"Formulate chronic pain kept going by fear and avoidance","exams":["mcp-entrance","md-psychiatry"],"module":"more-disorders","diagnosis":"Chronic post-surgical pain with fear-avoidance and depressive symptoms"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-387', 'Mr Dharmendra: does he understand the court? (fitness to stand trial in schizophrenia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-387-1","text":"Stopped medicines months before the arrest for theft of food","bucket":"precipitating"},{"id":"form-387-2","text":"He used to sell tea near the bus stand","bucket":"distractor"},{"id":"form-387-3","text":"Believes the judge and his lawyer are spies working against him and refuses to speak in court","bucket":"presenting"},{"id":"form-387-4","text":"Suspicion stops him talking to his lawyer","bucket":"perpetuating"},{"id":"form-387-5","text":"Hears voices commenting on him; cannot follow what the charges mean","bucket":"presenting"},{"id":"form-387-6","text":"Prison doctor who referred him","bucket":"protective"},{"id":"form-387-7","text":"No treatment in jail for the first weeks","bucket":"perpetuating"},{"id":"form-387-8","text":"Schizophrenia for ten years","bucket":"predisposing"},{"id":"form-387-9","text":"Overcrowded jail with poor sleep","bucket":"perpetuating"},{"id":"form-387-10","text":"Responded well to treatment in the past","bucket":"protective"},{"id":"form-387-11","text":"Homeless and without family support","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Dharmendra, 36, has an acute relapse of schizophrenia that currently makes him unfit to stand trial: he cannot understand the charges, follow proceedings or work with his lawyer, because of persecutory beliefs about the judge and lawyer and active voices. Fitness is about his present ability, not guilt. Long-standing schizophrenia and homelessness (predisposing) underlie it; stopping medicines (precipitating) led to relapse and the arrest for stealing food. No treatment in jail, suspicion of his lawyer and poor sleep (perpetuating) maintain it. Good past response and a referring doctor (protective) help. Plan: treatment, often in a hospital setting under the law for prisoners with mental illness, regular reports to the court and reassessment of fitness once well. His work is a distractor.","hint":"A 36-year-old accused of theft who believes the judge is a spy","tags":{"topic":"forensic","difficulty":4,"objective":"Formulate fitness to stand trial in a person with psychosis","exams":["md-psychiatry","mcp-entrance"],"module":"ethics-law","diagnosis":"Schizophrenia, acute relapse, currently unfit to stand trial"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-388', 'Mr Ramesh: the act he did while hearing God''s voice (the defence of unsound mind)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-388-1","text":"He planned the attack to settle a land dispute and later hid the weapon","bucket":"distractor"},{"id":"form-388-2","text":"Clear history from family and earlier medical records","bucket":"protective"},{"id":"form-388-3","text":"Stopped medicines a year ago","bucket":"predisposing"},{"id":"form-388-4","text":"Family sought only ritual treatment, delaying care","bucket":"perpetuating"},{"id":"form-388-5","text":"First psychotic episode at 25","bucket":"predisposing"},{"id":"form-388-6","text":"Assaulted his neighbour, believing God''s voice told him the neighbour was a demon about to kill his family","bucket":"presenting"},{"id":"form-388-7","text":"Ill and untreated for months before the incident, according to family","bucket":"presenting"},{"id":"form-388-8","text":"Increasing voices and sleeplessness for two months before the assault","bucket":"precipitating"},{"id":"form-388-9","text":"Shows remorse when treated","bucket":"protective"},{"id":"form-388-10","text":"Remains psychotic in custody","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Ramesh, 34, has schizophrenia and committed an assault while acutely psychotic, believing a divine voice that his neighbour was a demon threatening his family. In Indian law, a person is not criminally responsible if, at the time, unsoundness of mind made him unable to know the nature of the act or that it was wrong or against the law (Section 22 of the Bharatiya Nyaya Sanhita, earlier Section 84 of the Indian Penal Code). Planning for a land dispute and hiding the weapon, the distractor, would suggest he knew it was wrong. Early illness and stopping medicines (predisposing), worsening voices (precipitating), ritual-only treatment and ongoing psychosis (perpetuating) are all relevant. A clear history and remorse when treated (protective) help. The psychiatrist''s role is to describe his mental state at the time; the court decides.","hint":"A 34-year-old who assaulted his neighbour during an untreated psychotic episode","tags":{"topic":"forensic","difficulty":4,"objective":"Formulate a question of criminal responsibility in psychosis","exams":["md-psychiatry","mcp-entrance"],"module":"ethics-law","diagnosis":"Schizophrenia with an offence committed while acutely psychotic; question of criminal responsibility"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-389', 'Mr Bhargav: certain his wife is unfaithful, and getting angrier (morbid jealousy)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-389-1","text":"He runs a hardware shop in Rajkot","bucket":"distractor"},{"id":"form-389-2","text":"Brother who has noticed the danger","bucket":"protective"},{"id":"form-389-3","text":"Checks her phone, clothes and movements daily and has threatened to kill her","bucket":"presenting"},{"id":"form-389-4","text":"Isolated from friends","bucket":"perpetuating"},{"id":"form-389-5","text":"Insecure, suspicious personality","bucket":"predisposing"},{"id":"form-389-6","text":"Wife''s attempts to prove her innocence are taken as more evidence","bucket":"perpetuating"},{"id":"form-389-7","text":"Wife has relatives she can stay with","bucket":"protective"},{"id":"form-389-8","text":"Fixed belief for a year that his wife is having an affair, despite no evidence","bucket":"presenting"},{"id":"form-389-9","text":"Developed erectile difficulties a year ago","bucket":"precipitating"},{"id":"form-389-10","text":"Heavy drinking for twenty years","bucket":"predisposing"},{"id":"form-389-11","text":"Alcohol increases his suspicion and anger","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Bhargav, 46, has delusional disorder, jealous type (morbid jealousy), with an alcohol use disorder. Delusional jealousy carries a real risk of serious violence and even homicide towards the partner, so safety is the first priority. Long drinking and a suspicious personality (predisposing) raise his risk; erectile difficulties (precipitating) may have fed his insecurity and the belief. Alcohol, his wife''s efforts to prove innocence becoming ''evidence'' and isolation (perpetuating) maintain it. His brother''s concern and his wife''s relatives (protective) give safety options. Plan: assess risk urgently, advise his wife on safety and separation if needed, treat with antipsychotic medicine, address alcohol and erectile problems, and consider admission if risk is high. His shop is a distractor.","hint":"A 46-year-old who checks his wife''s phone and underwear and has threatened her","tags":{"topic":"psychosis","difficulty":4,"objective":"Formulate delusional jealousy and the risk of violence to the partner","exams":["md-psychiatry","mcp-entrance"],"module":"psychosis","diagnosis":"Delusional disorder, jealous type, with alcohol use disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-390', 'Arman: sixteen and accused of a serious crime (assessment under the juvenile justice law)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-390-1","text":"He likes kabaddi","bucket":"distractor"},{"id":"form-390-2","text":"Peer pressure and loyalty to the group","bucket":"perpetuating"},{"id":"form-390-3","text":"Untreated attention problems in childhood","bucket":"predisposing"},{"id":"form-390-4","text":"No adult supervision","bucket":"perpetuating"},{"id":"form-390-5","text":"Impulsive and restless since early school years","bucket":"presenting"},{"id":"form-390-6","text":"Responds well to one mentor at a youth centre","bucket":"protective"},{"id":"form-390-7","text":"Joined an older group involved in crime after dropping out of school","bucket":"precipitating"},{"id":"form-390-8","text":"Father''s violence and family poverty","bucket":"predisposing"},{"id":"form-390-9","text":"Daily cannabis use","bucket":"perpetuating"},{"id":"form-390-10","text":"Accused of a serious group assault; history of fights, truancy and cannabis use since age fourteen","bucket":"presenting"},{"id":"form-390-11","text":"Younger sister he protects","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Arman, 16, is accused of a serious offence, and the juvenile justice board has asked for an assessment of his mental and physical capacity, his ability to understand the consequences and the circumstances, to decide how he should be dealt with. He shows adolescent-onset conduct problems, cannabis use and attention problems from childhood. Violence at home, poverty and untreated attention problems (predisposing) raise his risk; dropping out and joining an older group (precipitating) led to offending. Peer loyalty, cannabis and no supervision (perpetuating) maintain it. Care for his sister and response to a mentor (protective) show capacity to change. The report should be balanced and focus on development, treatment needs and rehabilitation. Kabaddi is a distractor.","hint":"A 16-year-old accused of a serious assault, with a request for a mental assessment","tags":{"topic":"forensic","difficulty":4,"objective":"Formulate a young person''s maturity and mental health for the juvenile justice board","exams":["md-psychiatry","mcp-entrance"],"module":"child","diagnosis":"Conduct disorder, adolescent onset, with cannabis use and ADHD traits; assessment of mental capacity and maturity"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-391', 'Mr Prem: low and silent in his first month in jail (depression in custody)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-391-1","text":"Low mood, crying, not eating and not sleeping in his first month in jail","bucket":"presenting"},{"id":"form-391-2","text":"Past episode of low mood after his father''s death","bucket":"predisposing"},{"id":"form-391-3","text":"Arrested after a road accident that killed a pedestrian","bucket":"precipitating"},{"id":"form-391-4","text":"Says his life is over and his family is shamed","bucket":"presenting"},{"id":"form-391-5","text":"First time in custody","bucket":"predisposing"},{"id":"form-391-6","text":"Mother who writes letters","bucket":"protective"},{"id":"form-391-7","text":"He drove a taxi in Bhubaneswar","bucket":"distractor"},{"id":"form-391-8","text":"Isolated in an overcrowded barrack","bucket":"perpetuating"},{"id":"form-391-9","text":"Family has not visited","bucket":"perpetuating"},{"id":"form-391-10","text":"Guilt about the death","bucket":"perpetuating"},{"id":"form-391-11","text":"Prison welfare officer who noticed him","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Prem, 29, has a depressive episode in custody. The first weeks in prison are a time of very high suicide risk, especially for first-time prisoners with guilt and shame. A past low mood and being new to custody (predisposing) raise his risk; arrest after a fatal accident (precipitating) triggered the episode. Isolation, no family visits and guilt (perpetuating) maintain it. His mother''s letters and an observant welfare officer (protective) help. Plan: urgent suicide risk assessment, observation and removal of means in his cell, treatment for depression, family contact and legal aid. His job is a distractor.","hint":"A 29-year-old under trial who has stopped eating in prison","tags":{"topic":"forensic","difficulty":2,"objective":"Recognise depression and suicide risk in a newly imprisoned man","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"depression","diagnosis":"Depressive episode in custody with raised suicide risk"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-392', 'Mr Anoop: asking for help before he ever acts (paedophilic disorder in a man seeking treatment)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-392-1","text":"Has never acted on them and avoids being alone with children","bucket":"presenting"},{"id":"form-392-2","text":"Shame and fear of being reported stop him talking to anyone","bucket":"perpetuating"},{"id":"form-392-3","text":"Sexually abused by an older cousin at age ten","bucket":"predisposing"},{"id":"form-392-4","text":"Avoids adult relationships","bucket":"perpetuating"},{"id":"form-392-5","text":"Recurrent sexual urges and fantasies about prepubescent children since adolescence, causing him great distress","bucket":"presenting"},{"id":"form-392-6","text":"Has sought help on his own","bucket":"protective"},{"id":"form-392-7","text":"Strong wish never to harm a child","bucket":"protective"},{"id":"form-392-8","text":"His sister asked him to babysit her young daughter, which frightened him into seeking help","bucket":"precipitating"},{"id":"form-392-9","text":"Socially isolated adolescence","bucket":"predisposing"},{"id":"form-392-10","text":"He works in a printing press","bucket":"distractor"},{"id":"form-392-11","text":"Loneliness and low mood","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Anoop, 31, has paedophilic disorder: persistent sexual urges and fantasies about prepubescent children that cause marked distress, though he has never acted on them. The overriding priority is the safety of children, alongside treatment that helps him never offend. A lonely adolescence and his own abuse as a child (predisposing) are part of the background; being asked to babysit (precipitating) frightened him into seeking help. Shame, loneliness, low mood and avoiding adult relationships (perpetuating) raise risk. His strong wish not to harm and his help-seeking (protective) are important strengths. Plan: avoid unsupervised contact with children, specialist therapy for sexual urges, treat low mood, build adult relationships and be clear about the limits of confidentiality if a child is at risk. His job is a distractor.","hint":"A 31-year-old troubled by sexual urges towards children who has never offended","tags":{"topic":"forensic","difficulty":5,"objective":"Formulate a paraphilic disorder with child protection at the centre","exams":["md-psychiatry","mcp-entrance"],"module":"more-disorders","diagnosis":"Paedophilic disorder, non-exclusive type, without offending"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-393', 'Kishan: fires in the fields, for the thrill of the flames (pyromania)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-393-1","text":"Set five haystack fires in a year, feeling tension before and pleasure and relief while watching","bucket":"presenting"},{"id":"form-393-2","text":"Boredom and stress with no work","bucket":"perpetuating"},{"id":"form-393-3","text":"Feels guilty afterwards and wants to stop","bucket":"protective"},{"id":"form-393-4","text":"Lost his job at a brick kiln","bucket":"precipitating"},{"id":"form-393-5","text":"Not yet caught, so no consequences","bucket":"perpetuating"},{"id":"form-393-6","text":"Fascinated by fire engines and fires since childhood","bucket":"presenting"},{"id":"form-393-7","text":"Close to his grandmother","bucket":"protective"},{"id":"form-393-8","text":"Sets fires to take revenge on a landlord or for insurance money","bucket":"distractor"},{"id":"form-393-9","text":"Lonely childhood with few friends","bucket":"predisposing"},{"id":"form-393-10","text":"Impulsive temperament","bucket":"predisposing"},{"id":"form-393-11","text":"Watches fire videos online","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Kishan, 25, has pyromania: repeated deliberate fire-setting with tension before, fascination with fire and pleasure or relief during it, not done for money, revenge or because of psychosis or intoxication. Fire-setting for revenge or insurance, the distractor, would rule out pyromania. A lonely childhood and impulsivity (predisposing) raise his risk; losing his job (precipitating) increased stress and boredom. Boredom, no consequences so far and fire videos (perpetuating) maintain it. His guilt and his grandmother (protective) help. Plan: assess risk to others, CBT for urges, structured activity and work, and clarity about legal duties if lives are at risk.","hint":"A 25-year-old who has set several haystack fires and feels relief watching them","tags":{"topic":"forensic","difficulty":4,"objective":"Tell pyromania apart from fire-setting for other reasons","exams":["md-psychiatry","mcp-entrance"],"module":"more-disorders","diagnosis":"Pyromania"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-394', 'Raju: Down syndrome and the change at forty-eight (Alzheimer''s disease in Down syndrome)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-394-1","text":"Poor hearing untreated","bucket":"perpetuating"},{"id":"form-394-2","text":"Over a year, lost skills such as making tea and finding his room in the day centre","bucket":"presenting"},{"id":"form-394-3","text":"Mild intellectual disability with a long stable baseline","bucket":"predisposing"},{"id":"form-394-4","text":"Loss of skills that improved after a thyroid tablet was started","bucket":"distractor"},{"id":"form-394-5","text":"Familiar day centre staff","bucket":"protective"},{"id":"form-394-6","text":"Death of his mother, who knew all his routines, eighteen months ago","bucket":"precipitating"},{"id":"form-394-7","text":"New fits and more forgetfulness; quieter and more irritable","bucket":"presenting"},{"id":"form-394-8","text":"Hypothyroidism not checked recently","bucket":"perpetuating"},{"id":"form-394-9","text":"Changes put down to grief or ''his disability''","bucket":"perpetuating"},{"id":"form-394-10","text":"Down syndrome, with high lifetime risk of Alzheimer''s disease","bucket":"predisposing"},{"id":"form-394-11","text":"Sister who kept a record of his skills","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Raju, 48, has Alzheimer''s disease in Down syndrome: loss of long-held skills, increasing forgetfulness and new seizures in middle age. People with Down syndrome have a high lifetime risk of Alzheimer''s disease, often from their forties. Down syndrome and a long stable baseline (predisposing) make the change clear; his mother''s death (precipitating) also brought grief and routine loss. Diagnostic overshadowing, unchecked thyroid and poor hearing (perpetuating) can hide treatable contributors. The distractor, skills that recover with thyroid treatment, would mean hypothyroidism rather than dementia. His sister''s records and familiar staff (protective) help. Plan: check thyroid, hearing and vision, compare with his baseline, treat seizures, support grief and plan care.","hint":"A 48-year-old man with Down syndrome who is losing skills he had for years","tags":{"topic":"neurocognitive","difficulty":4,"objective":"Recognise early Alzheimer''s disease in a man with Down syndrome","exams":["md-psychiatry","mcp-entrance"],"module":"neurocognitive","diagnosis":"Alzheimer''s disease in Down syndrome"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-395', 'Munna: hitting out and not sleeping since his father left (depression in intellectual disability)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-395-1","text":"His father moved away for work","bucket":"precipitating"},{"id":"form-395-2","text":"Moderate intellectual disability with limited speech","bucket":"predisposing"},{"id":"form-395-3","text":"Day centre staff who know his usual self","bucket":"protective"},{"id":"form-395-4","text":"Lost his daily walks with his father","bucket":"perpetuating"},{"id":"form-395-5","text":"Over two months, hits out, cries, sleeps poorly and has stopped eating his favourite foods","bucket":"presenting"},{"id":"form-395-6","text":"Mother with depression","bucket":"predisposing"},{"id":"form-395-7","text":"Cannot put his feelings into words","bucket":"perpetuating"},{"id":"form-395-8","text":"No longer enjoys his music or the day centre","bucket":"presenting"},{"id":"form-395-9","text":"Behaviour is seen as ''just his disability'' and punished","bucket":"perpetuating"},{"id":"form-395-10","text":"Behaviour that improves when a toothache is treated","bucket":"distractor"},{"id":"form-395-11","text":"Responds to music therapy","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Munna, 22, has a depressive episode with moderate intellectual disability, shown through changes in behaviour, sleep, appetite and enjoyment rather than words. People with intellectual disability are often not diagnosed because changes are put down to the disability, which is diagnostic overshadowing. Limited speech and a mother with depression (predisposing) raise his risk; his father leaving (precipitating) was a major loss. Punishment, difficulty expressing feelings and loss of routine (perpetuating) maintain it. A pain cause such as a toothache, the distractor, should always be ruled out. Staff who know him and his response to music (protective) help. Plan: physical check, treat depression, restore routines, regular video calls with his father and positive behaviour support.","hint":"A 22-year-old with moderate intellectual disability whose behaviour changed","tags":{"topic":"neurodevelopmental","difficulty":3,"objective":"Recognise depression showing as behaviour change in intellectual disability","exams":["mcp-entrance","md-psychiatry"],"module":"child","diagnosis":"Depressive episode in a young man with moderate intellectual disability"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-396', 'Chinu: always hungry and taking food from bins (Prader-Willi syndrome)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-396-1","text":"Kitchen not locked","bucket":"perpetuating"},{"id":"form-396-2","text":"Floppy, poor feeder as a baby, then hunger from early childhood","bucket":"predisposing"},{"id":"form-396-3","text":"Genetic test confirmed Prader-Willi syndrome","bucket":"predisposing"},{"id":"form-396-4","text":"Little exercise","bucket":"perpetuating"},{"id":"form-396-5","text":"Enjoys helping at a garden project","bucket":"protective"},{"id":"form-396-6","text":"Moved to a hostel where food was less controlled","bucket":"precipitating"},{"id":"form-396-7","text":"Family gives food to stop outbursts","bucket":"perpetuating"},{"id":"form-396-8","text":"Constant hunger, taking food from bins and neighbours, with severe weight gain","bucket":"presenting"},{"id":"form-396-9","text":"Temper outbursts when food is refused and skin picking","bucket":"presenting"},{"id":"form-396-10","text":"Loving parents","bucket":"protective"},{"id":"form-396-11","text":"Overeating that started only after starting an antipsychotic","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Chinu, 19, has Prader-Willi syndrome, a genetic condition with poor feeding in infancy followed by constant hunger, food seeking, weight gain, mild intellectual disability, temper outbursts and skin picking. The hunger is driven by the brain and does not respond to willpower. The genetic syndrome (predisposing) underlies it; a hostel with less food control (precipitating) worsened food seeking. Unlocked food, giving food to stop outbursts and little exercise (perpetuating) maintain it. Overeating that began only with an antipsychotic, the distractor, would point to a medicine effect instead. Loving parents and the garden project (protective) help. Plan: a secure food environment, predictable meal times, daily exercise, behaviour support and monitoring for diabetes and sleep apnoea.","hint":"A 19-year-old with mild intellectual disability and constant food seeking","tags":{"topic":"neurodevelopmental","difficulty":4,"objective":"Recognise a genetic syndrome behind food seeking and behaviour","exams":["md-psychiatry","mcp-entrance"],"module":"child","diagnosis":"Prader-Willi syndrome with food-seeking behaviour and temper outbursts"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-397', 'Neetu: her new ''friend'' at the bus stand (sexual vulnerability in intellectual disability)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-397-1","text":"Mild intellectual disability with difficulty judging others'' intentions","bucket":"predisposing"},{"id":"form-397-2","text":"Mother who noticed the gifts and brought her","bucket":"protective"},{"id":"form-397-3","text":"Secrecy because the man told her to keep it private","bucket":"perpetuating"},{"id":"form-397-4","text":"She is learning tailoring","bucket":"distractor"},{"id":"form-397-5","text":"Began travelling alone by bus to a vocational course","bucket":"precipitating"},{"id":"form-397-6","text":"Trusts her course teacher","bucket":"protective"},{"id":"form-397-7","text":"Meeting a 40-year-old man secretly who gives her gifts and phone credit","bucket":"presenting"},{"id":"form-397-8","text":"Wants friends and acceptance","bucket":"predisposing"},{"id":"form-397-9","text":"Missed periods this month; says he is her ''boyfriend''","bucket":"presenting"},{"id":"form-397-10","text":"No sex education given at home or school","bucket":"perpetuating"},{"id":"form-397-11","text":"Lonely at home","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Neetu, 20, has mild intellectual disability and is at high risk of sexual exploitation by an older man using gifts and secrecy. A missed period needs urgent checking. Difficulty judging others'' intentions and a strong wish for acceptance (predisposing) raise her vulnerability; travelling alone (precipitating) brought contact with him. No sex education, secrecy and loneliness (perpetuating) maintain risk. Her mother and course teacher (protective) help. Plan: pregnancy test and health care, assess her capacity to consent to sex and relationships, safeguarding and legal steps if abuse is found, sex and relationship education at her level, and safe social opportunities. Tailoring is a distractor.","hint":"A 20-year-old with mild intellectual disability who is meeting an older man secretly","tags":{"topic":"neurodevelopmental","difficulty":3,"objective":"Formulate risk of sexual exploitation in a young woman with intellectual disability","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"ethics-law","diagnosis":"Mild intellectual disability with high risk of sexual exploitation"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-398', 'Gopal: the first job at the bakery (transition to work in mild intellectual disability)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-398-1","text":"No one to ask for help at work","bucket":"perpetuating"},{"id":"form-398-2","text":"Supportive job coach from his course","bucket":"protective"},{"id":"form-398-3","text":"Worries he will make mistakes and be shouted at","bucket":"presenting"},{"id":"form-398-4","text":"Started his first job after finishing a vocational course","bucket":"precipitating"},{"id":"form-398-5","text":"Instructions given quickly and only once","bucket":"perpetuating"},{"id":"form-398-6","text":"Parents let him stay home","bucket":"perpetuating"},{"id":"form-398-7","text":"Sheltered at home and school","bucket":"predisposing"},{"id":"form-398-8","text":"Mild intellectual disability","bucket":"predisposing"},{"id":"form-398-9","text":"He lives in Thane","bucket":"distractor"},{"id":"form-398-10","text":"Anxious, sleeping poorly and refusing to go to his new job at a bakery for two weeks","bucket":"presenting"},{"id":"form-398-11","text":"Likes baking and is good at it","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Gopal, 21, has an adjustment disorder with anxiety while starting his first job, in the context of mild intellectual disability. Mild intellectual disability and a sheltered upbringing (predisposing) make change harder; starting work (precipitating) triggered his anxiety. Rushed instructions, no one to ask and staying home (perpetuating) maintain it. His baking skill and job coach (protective) are strengths. Plan: reasonable adjustments such as written or picture instructions, a named buddy at work, a gradual start with the job coach and praise for progress. Thane is a distractor.","hint":"A 21-year-old with mild intellectual disability anxious about starting work","tags":{"topic":"neurodevelopmental","difficulty":1,"objective":"Sort a transition stress in a young man with intellectual disability into the 5 Ps","exams":["cuet-pg","ma-semester","mcp-entrance"],"module":"child","diagnosis":"Adjustment disorder with anxiety in a young man with mild intellectual disability"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-399', 'Bunty: talking to himself, put down to his disability (psychosis in intellectual disability)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-399-1","text":"Mild intellectual disability","bucket":"predisposing"},{"id":"form-399-2","text":"Uncle with schizophrenia","bucket":"predisposing"},{"id":"form-399-3","text":"Limited words to describe experiences","bucket":"perpetuating"},{"id":"form-399-4","text":"Good functioning at the workshop before","bucket":"protective"},{"id":"form-399-5","text":"Over four months, fearful, talking and laughing to himself, covering his ears and saying ''the men in the wall'' talk about him","bucket":"presenting"},{"id":"form-399-6","text":"Stopped going to his workshop and neglects himself","bucket":"presenting"},{"id":"form-399-7","text":"Death of his grandfather, his main carer, five months ago","bucket":"precipitating"},{"id":"form-399-8","text":"Talking to himself in a calm, playful way all his life, with no fear","bucket":"distractor"},{"id":"form-399-9","text":"Sister who noticed he was ''not himself''","bucket":"protective"},{"id":"form-399-10","text":"Sleeping poorly and pacing at night","bucket":"perpetuating"},{"id":"form-399-11","text":"Changes put down to grief or ''his disability'' by staff","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Bunty, 26, has schizophrenia alongside mild intellectual disability: new fearfulness, responding to voices, persecutory ideas and decline over four months. Talking to himself calmly and playfully throughout life, the distractor, can be part of intellectual disability and would not suggest psychosis; the key is change from his baseline. Mild intellectual disability and an uncle with schizophrenia (predisposing) raise his risk; his grandfather''s death (precipitating) may have added stress. Diagnostic overshadowing, limited language and poor sleep (perpetuating) delay care. His sister''s concern and good past functioning (protective) help. Plan: physical check, careful assessment using simple language and observation, low-dose antipsychotic with close side effect monitoring, grief support and return to his workshop.","hint":"A 26-year-old with mild intellectual disability who has become fearful and withdrawn","tags":{"topic":"psychosis","difficulty":5,"objective":"Recognise psychosis in intellectual disability and avoid diagnostic overshadowing","exams":["md-psychiatry","mcp-entrance"],"module":"psychosis","diagnosis":"Schizophrenia in a man with mild intellectual disability"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
